INSERT OR IGNORE INTO verses (id, ref, book, chapter, verse, text, text_normalized, text_html, testament, translation_key, dialect, tags, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41411, 'Jeremiah 48:44', 'Jeremiah', 48, 44, 'هر څوک چې د دهشت نه وتښتى نو په کنده کښې به وغورزيږى. څوک چې د کندې نه راوچت شى نو په دام کښې به ګرفتار شى، ځکه چې زۀ په موآب باندې د سزا وخت راولم، مالِک خُدائ فرمائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah48_verse_044.mp3', NULL, 1761758917, 1761758917),
(41412, 'Jeremiah 48:45', 'Jeremiah', 48, 45, 'کوم خلق چې حسبون ته د پناه دپاره وتښتى نو هلته به بې‌وسه ودريږى، ځکه چې د حسبون نه د اور شُغلې راوچتيږى، د بادشاه سيحون د زوړ کور نه به د اور لمبې راوچتيږى. دا اور د موآب تندے سوزوى، او د شور اچوونکو لافوانو کوپړۍ سوزوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah48_verse_045.mp3', NULL, 1761758917, 1761758917),
(41413, 'Jeremiah 48:46', 'Jeremiah', 48, 46, 'په تا دې افسوس وى اے موآبه. د کموس بُت عبادت کوونکى تباه شول، ستاسو زامن مُلک بدر شول او ستاسو لوڼه ونيولے شوې او جلاوطن کړے شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah48_verse_046.mp3', NULL, 1761758917, 1761758917),
(41414, 'Jeremiah 48:47', 'Jeremiah', 48, 47, 'خو زۀ به بيا موآب په راتلونکى وخت کښې دوباره بحال کړم، مالِک خُدائ فرمائى.“ نو دلته د موآب په حقله د يرمياه نبى پېشګوئې ختمه شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah48_verse_047.mp3', NULL, 1761758917, 1761758917),
(41415, 'Judges 2:1', 'Judges', 2, 1, 'د څښتن فرښته د جلجال څخه بوکیم ته لاړه او اسراییلیانو ته یې وویل: «ما تاسو د مصر څخه راوویستلئ او هغې خاورې ته مې راوستلئ چې ستاسو د نیکونو سره مې د هغې وعده کړې وه. ما وویل چې زه به هېڅکله ستاسو سره خپل لوظ مات نه کړم،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_001.mp3', NULL, 1761758917, 1761758917),
(41416, 'Judges 2:2', 'Judges', 2, 2, 'نو تاسو د دغې خاورې د خلکو سره کوم لوظ ونه کړئ او د هغوی د قربانۍ ځایونه راوغورځوئ. خو څه چې ما درته ویلي وو تاسو هغه ونه کړل. ولې مو داسې وکړل؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_002.mp3', NULL, 1761758917, 1761758917),
(41417, 'Judges 2:3', 'Judges', 2, 3, 'نو اوس تاسو ته وایم چې زه به دا خلک ستاسو له مخې څخه لېرې نه کړم. هغوی به ستاسو دښمنان وي او د هغوی د خدایانو په عبادت کولو سره به د هغوی په دام کې راګېر اوسئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_003.mp3', NULL, 1761758917, 1761758917),
(41418, 'Judges 2:4', 'Judges', 2, 4, 'کله چې د څښتن فرښتې دا خبرې وکړې، نو د اسراییلو ټول قوم په لوړ اواز سره وژړل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_004.mp3', NULL, 1761758917, 1761758917),
(41419, 'Judges 2:5', 'Judges', 2, 5, 'نو په دې خاطر دوی په هغه ځای باندې د بوکیم نوم کېښود او هلته یې څښتن ته قربانۍ وړاندې کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_005.mp3', NULL, 1761758917, 1761758917),
(41420, 'Judges 2:6', 'Judges', 2, 6, 'وروسته له هغې چې یوشع اسراییلیان رخصت کړل، دوی هر یو لاړ چې د خپلې برخې ځمکې ملکیت تر لاسه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_006.mp3', NULL, 1761758917, 1761758917),
(41421, 'Judges 2:7', 'Judges', 2, 7, 'ترڅو پورې چې یوشع ژوندی ؤ، د اسراییلو خلک څښتن ته وفادار وو او حتی د هغه د مړینې څخه وروسته هم ترڅو پورې چې د قوم هغه سپین ږیري ژوندي وو چې د څښتن هغه لوی لوی کارونه په خپلو سترګو لیدلي وو چې د اسراییلو دپاره یې کړي وو، هغوی څښتن ته وفادار پاتې شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_007.mp3', NULL, 1761758917, 1761758917),
(41422, 'Judges 2:8', 'Judges', 2, 8, 'د څښتن خدمتګار یوشع د نون زوی د یو سلو لسو کالو په عمر مړ شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_008.mp3', NULL, 1761758917, 1761758917),
(41423, 'Judges 2:9', 'Judges', 2, 9, 'هغه یې په خپله ځمکه کې په تمنه حارس کې چې د افرایم په غرنۍ سیمه کې او د جاعش د غره په شمال کې وه، ښخ کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_009.mp3', NULL, 1761758917, 1761758917),
(41424, 'Judges 2:10', 'Judges', 2, 10, 'کله چې هغه ټول نسل مړ شو او د خپلو نیکونو سره یوځای شو، نو راتلونکي نسل څښتن او د هغه کارونه چې د اسراییلو دپاره یې کړي وو، هېر کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_010.mp3', NULL, 1761758917, 1761758917),
(41425, 'Judges 2:11', 'Judges', 2, 11, 'د اسراییلو خلکو بیا داسې کارونه وکړل چې د څښتن په نظر کې بد وو او د بعل د بتانو په عبادت یې پیل وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_011.mp3', NULL, 1761758917, 1761758917),
(41426, 'Judges 2:12', 'Judges', 2, 12, 'هغوی د هغه څښتن عبادت کول پرېښودل چې د دوی د نیکونو خدای ؤ او دوی یې د مصر څخه راویستلي وو. دوی د خپل شاوخوا خلکو خدایانو ته عبادت کاوه. هغوی ته یې سجده کوله او څښتن یې په قهر کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_012.mp3', NULL, 1761758917, 1761758917),
(41427, 'Judges 2:13', 'Judges', 2, 13, 'هغوی څښتن پرېښود او د بعل او عشتاروت د بتانو عبادت یې غوره کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_013.mp3', NULL, 1761758917, 1761758917),
(41428, 'Judges 2:14', 'Judges', 2, 14, 'نو څښتن په اسراییلو باندې ډېر په قهر شو او هغوی یې یرغلګرو ته په لاس ورکړل او یرغلګرو هغوی لوټ کړل. څښتن دوی خپلو دښمنانو ته تسلیم کړل او اسراییلیانو نور نه شو کولای چې د هغوی په وړاندې مقاومت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_014.mp3', NULL, 1761758917, 1761758917),
(41429, 'Judges 2:15', 'Judges', 2, 15, 'هر ځل چې اسراییلیان د جګړې دپاره وتل، څښتن د هغوی په خلاف عمل کاوه چې ماتې وخوري، ځکه چې هغه دوی ته قسم خوړلی ؤ چې دا کار به کوي. هغوی په لوی مصیبت اخته شوي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_015.mp3', NULL, 1761758917, 1761758917),
(41430, 'Judges 2:16', 'Judges', 2, 16, 'بیا څښتن اسراییلیانو ته ځانګړي مشران چې د قاضیانو په نوم هم یادېدل ورکړل چې هغوی د یرغلګرو څخه وژغوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_016.mp3', NULL, 1761758917, 1761758917),
(41431, 'Judges 2:17', 'Judges', 2, 17, 'خو اسراییلیانو خپلو مشرانو ته غوږ نه نیوه. اسراییلو د څښتن سره بې وفایي کوله او د نورو خدایانو عبادت به یې کاوه. د هغوی پلرونو به د څښتن حکمونو ته غاړه ایښودله، خو نوي نسل زر دا کار پرېښود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_017.mp3', NULL, 1761758917, 1761758917),
(41432, 'Judges 2:18', 'Judges', 2, 18, 'هرکله چې څښتن اسراییلو ته یو مشر ورکاوه، څښتن به د هغه مشر سره مرسته کوله او ترڅو پورې به چې هغه مشر ژوندی ؤ، خلک به یې د خپلو دښمنانو څخه ژغورل. څښتن په هغوی باندې رحم کاوه، ځکه چې هغوی به د ظلم او کړېدلو د لاسه فریاد کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_018.mp3', NULL, 1761758917, 1761758917),
(41433, 'Judges 2:19', 'Judges', 2, 19, 'خو کله به چې هغه مشر مړ شو، خلک به بېرته خپلو بدو لارو ته راګرځېدل او د خپلو نیکونو څخه به یې نور هم زیات فساد کاوه. د نورو خدایانو پیروي او عبادت به یې کاوه. دوی به خپل بد عملونه او سرزوري نه پرېښودله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_019.mp3', NULL, 1761758917, 1761758917),
(41434, 'Judges 2:20', 'Judges', 2, 20, 'نو بیا څښتن په اسراییلو باندې ډېر په قهر شو او ویې ویل: «په دې خاطر چې دې قوم هغه لوظ مات کړی دی چې د هغوی د نیکونو سره مې کړی ؤ او زما حکم یې نه دی منلی،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_020.mp3', NULL, 1761758917, 1761758917),
(41435, 'Judges 2:21', 'Judges', 2, 21, 'نو زه به نور هغه قومونه چې د یوشع د مړینې څخه وروسته پاتې شوي وو، ونه شړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_021.mp3', NULL, 1761758917, 1761758917),
(41436, 'Judges 2:22', 'Judges', 2, 22, 'زه به د هغوی څخه کار واخلم، ترڅو دا معلومه شي چې دا اسراییلیان د خپلو پلرونو په شان زما په لاره باندې روان دي او که نه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_022.mp3', NULL, 1761758917, 1761758917),
(41437, 'Judges 2:23', 'Judges', 2, 23, 'نو څښتن هغه قومونه پرېښودل چې په هغې خاوره کې پاتې شي. هغه یوشع ته په هغوی باندې بری ورنه کړ او نه یې د یوشع د مړینې څخه وروسته هغوی زر وشړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges2_verse_023.mp3', NULL, 1761758917, 1761758917),
(41438, 'Jeremiah 9:1', 'Jeremiah', 9, 1, '”کاش چې زما سر د اوبو چينه وے، او زما سترګې د اوښکو چينې وے، ترڅو چې ما شپه او ورځ د خپلو خلقو په قتلولو ژړا انګولا کولے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_001.mp3', NULL, 1761758917, 1761758917),
(41439, 'Jeremiah 9:2', 'Jeremiah', 9, 2, 'کاش چې په صحرا کښې زما يو سرائى وے، چرته چې ما خپل خلق پرېښودى وے او هلته د دوئ نه لرې اوسېدلم. ځکه چې دوئ ټول د خُدائ پاک سره بې‌وفائى کوى، او د بې‌ايمانانو يوه ډله ده.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_002.mp3', NULL, 1761758917, 1761758917),
(41440, 'Jeremiah 9:3', 'Jeremiah', 9, 3, 'مالِک خُدائ فرمائى، ”هغوئ د خپلو ژبو نه ليندې جوړې کړې دى او د دروغو غشى هر وخت ورَوى. د دې مُلک په ديانتدارۍ کښې صداقت نشته، هغوئ د يوې ګناه دپاسه بله ګناه کوى، هغوئ ما نۀ پېژنى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_003.mp3', NULL, 1761758917, 1761758917),
(41441, 'Jeremiah 9:4', 'Jeremiah', 9, 4, 'تاسو هر يو په خپل دوست نظر ساتئ او په خپل ورور هم اعتبار مۀ کوئ. ځکه چې هر يو ورور ستاسو دوکه مار دے، او هر يو دوست غېبت کوونکے دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_004.mp3', NULL, 1761758917, 1761758917),
(41442, 'Jeremiah 9:5', 'Jeremiah', 9, 5, 'هر يو دوست بل دوست سره دوکه کوى، او يو هم رښتيا خبره نۀ کوى، هغوئ خپلو ژبو ته د دروغو وئيلو تعليم ورکړے دے، او په ګناه کولو سره خپل ځان ستړے کوى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_005.mp3', NULL, 1761758917, 1761758917),
(41443, 'Jeremiah 9:6', 'Jeremiah', 9, 6, 'مالِک خُدائ فرمائى چې، ”تاسو د دوکه مارانو او د دروغژنو په مينځ کښې اوسېږئ، او د خپلو دوکه کولو په وجه دوئ نۀ غواړى چې ما وپېژنى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_006.mp3', NULL, 1761758917, 1761758917),
(41444, 'Jeremiah 9:7', 'Jeremiah', 9, 7, 'نو په دې وجه مالِک خُدائ ربُ الافواج فرمائى، ”زۀ به دوئ لکه د کچه سپينو زرو په شان د اور بټۍ کښې واچوم، صفا به يې کړم او وبه يې آزمايمه، زۀ نور د دې ګناه ګار قوم سره څۀ وکړم؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_007.mp3', NULL, 1761758917, 1761758917),
(41445, 'Jeremiah 9:8', 'Jeremiah', 9, 8, 'د هغوئ ژبې لکه د زهريله غشو په شان دى، او هغوئ همېشه دروغ وائى. او هغوئ په خولۀ د خپل ګاونډى سره خوږه لهجه کوى، خو په حقيقت کښې د هغوئ دپاره بدې منصوبې جوړوى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_008.mp3', NULL, 1761758917, 1761758917),
(41446, 'Jeremiah 9:9', 'Jeremiah', 9, 9, 'مالِک خُدائ فرمائى چې، ”آيا زۀ دوئ ته د دې بدو کارونو سزا ورنۀ کړم څۀ؟ آيا د داسې قوم نه بدله خپله وانۀ خلم څۀ؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_009.mp3', NULL, 1761758917, 1761758917),
(41447, 'Jeremiah 9:10', 'Jeremiah', 9, 10, 'زۀ به د غرونو دپاره ژړا وکړم، او د بيابان د څرن په ځايونو به د غم سندرې ووايم. ځکه چې څوک هم په هغې تګ راتګ نۀ کوى، او ټول شينکے سوزېدلے او اوچ شوے دے او د رمو آوازونه په کښې نۀ اورېدلے کيږى. د هوا مارغان او ځنګلى ځناور ټول ترې نه تښتېدلى دى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_010.mp3', NULL, 1761758917, 1761758917),
(41448, 'Jeremiah 9:11', 'Jeremiah', 9, 11, 'مالِک خُدائ فرمائى چې، ”زۀ به د يروشلم نه د خاورو ډېرے، او د ګيدړانو غار جوړ کړم. او د يهوداه ښارونه به وران او خاموشه کړم، نو هيڅوک به هلته کښې نۀ اوسيږى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_011.mp3', NULL, 1761758917, 1761758917),
(41449, 'Jeremiah 9:12', 'Jeremiah', 9, 12, 'نو بيا به څوک دومره هوښيار وى چې په دې ټوله موضوع پوهه شى؟ چا ته د مالِک خُدائ نه دومره هدايت مِلاو شوے دے چې دا بيان کړى چې دا مُلک ولې وران شوے دے؟ دا ولې په ريګستان بدل شوے دے، او دومره ولې وران او خراب شوے دے چې هيڅوک هم پرې تېرېدلے نۀ شى؟“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_012.mp3', NULL, 1761758917, 1761758917),
(41450, 'Jeremiah 9:13', 'Jeremiah', 9, 13, 'مالِک خُدائ وفرمائيل چې، ”دا ځکه چې هغوئ زما شريعت هېر کړو کوم تعليم چې ما هغوئ ته وړاندې کړے وو، نۀ هغوئ زما کلام ومنلو او نۀ يې د هغې پيروى وکړه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_013.mp3', NULL, 1761758917, 1761758917),
(41451, 'Jeremiah 9:14', 'Jeremiah', 9, 14, 'بلکې د دې په ځائ هغوئ د خپل سرکشه زړونو پيروى وکړه، او هغوئ د بعل د بُت پيروى وکړه لکه څنګه چې د هغوئ پلار نيکۀ ورته د عبادت کولو تعليم ورکړے وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_014.mp3', NULL, 1761758917, 1761758917),
(41452, 'Jeremiah 9:15', 'Jeremiah', 9, 15, 'نو ځکه، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، ګورئ، زۀ به هغوئ ته د خوړلو دپاره ګنډير ورکړم او د څښلو دپاره به زهريله اوبۀ ورکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_015.mp3', NULL, 1761758917, 1761758917),
(41453, 'Jeremiah 9:16', 'Jeremiah', 9, 16, 'زۀ به هغوئ په داسې قومونو کښې خوارۀ وارۀ کړم چې نۀ به يې دوئ او نۀ به يې د دوئ پلار نيکۀ پېژنى، او زۀ به په دوئ جنګ راولم ترڅو چې يې هلاک کړى نۀ وى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_016.mp3', NULL, 1761758917, 1761758917),
(41454, 'Jeremiah 9:17', 'Jeremiah', 9, 17, 'مالِک خُدائ ربُ الافواج دا فرمائى چې، ”هغه څۀ چې کېدونکى دى په هغې غور وکړئ. سندرې ويونکې او ماتم کوونکې ښځې راوغواړئ چې راشى، او هغه ښځې راوغواړئ چې په مړى په ژړا کولو کښې ماهرې دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_017.mp3', NULL, 1761758917, 1761758917),
(41455, 'Jeremiah 9:18', 'Jeremiah', 9, 18, 'لاړ شئ او هغوئ زر راولئ چې په مونږ باندې دومره ژړا او سندرې ووائى ترڅو زمونږ سترګې د اوښکو نه ډکې شى، او زمونږ د بڼو نه اوښکې روانې شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_018.mp3', NULL, 1761758917, 1761758917),
(41456, 'Jeremiah 9:19', 'Jeremiah', 9, 19, 'د صيون نه د ژړا آوازونه اورېدلے کيږى چې وائى، ”واى، واى، مونږه څنګه تباه شُو او په شرمونو وشرمېدو. مونږ مُلک پرېښودو ته مجبوره شوى يُو، ځکه چې زمونږ کورونه تباه شوى دى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_019.mp3', NULL, 1761758917, 1761758917),
(41457, 'Jeremiah 9:20', 'Jeremiah', 9, 20, 'اے ښځو، د مالِک خُدائ کلام ته غوږ ونيسئ، او د هغۀ د خولې هرې خبرې ته غوږ ونيسئ. خپلو لوڼو ته د سندرو او ماتم کولو تعليم ورکړئ، او يو بل ته په خپلو کښې د ماتم کولو تعليم ورکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_020.mp3', NULL, 1761758917, 1761758917),
(41458, 'Jeremiah 9:21', 'Jeremiah', 9, 21, 'ځکه چې مرګ زمونږ کور ته په کړکو راننوتے دے او زمونږ قلعو ته رادننه شوے دے، هغه اوس ماشومان د کوڅو نه او ځوانان د بازارونو او چوکونو نه راټولوى او تېروى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_021.mp3', NULL, 1761758917, 1761758917),
(41459, 'Jeremiah 9:22', 'Jeremiah', 9, 22, 'مالِک خُدائ فرمائى، ”خلقو ته ووايه چې د مړو لاشونه به په پټو کښې لکه د ډېران د سرې پراتۀ وى، او لکه د غنمو وږې په شان د لَوګرى شا ته اخوا ديخوا پراتۀ وى دغه شان به مړى هرې خوا ته پراتۀ وى او د راټولولو به يې څوک نۀ وى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_022.mp3', NULL, 1761758917, 1761758917),
(41460, 'Jeremiah 9:23', 'Jeremiah', 9, 23, 'مالِک خُدائ فرمائى، ”هوښيار دې په خپله هوښيارتيا فخر ونۀ کړى، نۀ دې زورَور په خپل زور باندې او نۀ دې دولتمند په خپل دولت باندې فخر وکړى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_023.mp3', NULL, 1761758917, 1761758917),
(41461, 'Jeremiah 9:24', 'Jeremiah', 9, 24, 'مالِک خُدائ فرمائى چې، ”کۀ څوک فخر کول غواړى نو هغه دې په دې خبره فخر وکړى چې دوئ ما پېژنى او په دې پوهيږى چې زۀ هغه مالِک خُدائ يم چې په زمکه باندې نۀ ختمېدونکې مينه، عدل و اِنصاف او صداقت راولم. ځکه چې په دې څيزونو کښې زما خوشحالى ده.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_024.mp3', NULL, 1761758917, 1761758917),
(41462, 'Jeremiah 9:25', 'Jeremiah', 9, 25, 'مالِک خُدائ فرمائى، ”هغه ورځې راروانې دى چې، زۀ به ټولو هغه خلقو ته سزا ورکړم څوک چې صرف جسمانى سنت شوى دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_025.mp3', NULL, 1761758917, 1761758917),
(41463, 'Jeremiah 9:26', 'Jeremiah', 9, 26, 'زۀ به مِصر، ادوم، عمون، موآب او هغوئ ته څوک چې په دشتو او ميرو کښې اوسيږى سزا ورکړم، او ورسره به بنى اِسرائيل ته هم سزا ورکړم. ځکه چې د ټولو بُت پرستو قومونو په شان، د دوئ زړونه هم مالِک خُدائ ته وقف نۀ دى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah9_verse_026.mp3', NULL, 1761758917, 1761758917),
(41464, 'Exodus 14:1', 'Exodus', 14, 1, 'بیا څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_001.mp3', NULL, 1761758917, 1761758917),
(41465, 'Exodus 14:2', 'Exodus', 14, 2, '«اسراییلیانو ته ووایه چې بېرته راوګرځي او فم الحیروت ته مخامخ چې د مجدل او د سرې بحیرې ترمنځ او بعل صفون ته نژدې دی خېمې ودروي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_002.mp3', NULL, 1761758917, 1761758917),
(41466, 'Exodus 14:3', 'Exodus', 14, 3, 'فرعون به فکر وکړي چې اسراییلیان به په وطن کې سرګردانه ګرځي او د وارخطایۍ په حالت کې په دښته کې بند پاتې دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_003.mp3', NULL, 1761758917, 1761758917),
(41467, 'Exodus 14:4', 'Exodus', 14, 4, 'زه به د فرعون زړه سخت کړم او هغه به دوی تعقیب کړي. خو د فرعون او د هغه په لښکرو باندې به زما بریالیتوب زما د جلال سبب شي. بیا به مصریان پوه شي چې زه څښتن یم.» لکه څنګه چې هغوی ته ویل شوي وو، اسراییلیانو هماغسې وکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_004.mp3', NULL, 1761758917, 1761758917),
(41468, 'Exodus 14:5', 'Exodus', 14, 5, 'کله چې فرعون خبر شو چې د اسراییلو قوم تښتېدلی دی، هغه او د هغه درباریانو د هغوی په هکله خپله پرېکړه بدله کړه او ویې ویل: «مونږ څه وکړل؟ مونږ اسراییلیان پرېښودل چې وتښتي او هغوی چې زمونږ غلامان وو له لاسه مو ورکړل!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_005.mp3', NULL, 1761758917, 1761758917),
(41469, 'Exodus 14:6', 'Exodus', 14, 6, 'فرعون خپلې جنګي ګاډۍ ګانې او لښکرې تیارې کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_006.mp3', NULL, 1761758917, 1761758917),
(41470, 'Exodus 14:7', 'Exodus', 14, 7, 'هغه د ځان سره شپږ سوه ښې ښې جنګي ګاډۍ ګانې د مصر د نورو ټولو جنګي ګاډیو سره چې د هر یو سره خپل خپل قوماندان ؤ، یووړلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_007.mp3', NULL, 1761758917, 1761758917),
(41471, 'Exodus 14:8', 'Exodus', 14, 8, 'څښتن د فرعون زړه سخت کړ، نو هغه د اسراییلیانو پسې چې په زوړورتیا سره د مصر څخه ووتل، روان شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_008.mp3', NULL, 1761758917, 1761758917),
(41472, 'Exodus 14:9', 'Exodus', 14, 9, 'د مصریانو لښکرې، د فرعون ټول اسونه، جنګي ګاډۍ ګانې، اس سواران او لښکرې د اسراییلیانو پسې روان شول او د هغوی څخه مخکې شول، چېرته چې هغوی د بحیرې سره چې فم الحیروت او بعل صفون ته نژدې ؤ، خېمې ودرولې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_009.mp3', NULL, 1761758917, 1761758917),
(41473, 'Exodus 14:10', 'Exodus', 14, 10, 'څنګه چې فرعون نژدې شو، اسراییلیانو سترګې پورته کړې او ویې لیدل چې مصریان هغوی پسې راروان دي. هغوی ډېر ووېرېدل او څښتن ته یې فریاد وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_010.mp3', NULL, 1761758917, 1761758917),
(41474, 'Exodus 14:11', 'Exodus', 14, 11, 'هغوی موسی ته وویل: «ایا په مصر کې قبرونه نه وو چې تا دلته دښتې ته راوستلو چې مړه شو؟ ګوره تا زمونږ سره څه وکړل چې د مصر څخه دې راوویستلو؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_011.mp3', NULL, 1761758917, 1761758917),
(41475, 'Exodus 14:12', 'Exodus', 14, 12, 'ایا تاته مونږ په مصر کې ونه ویل چې مونږ پرېږده چې د مصریانو غلامان اوسو؟ مونږ ته په دښته کې د مړه کېدلو څخه د مصریانو غلامي ښه ده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_012.mp3', NULL, 1761758917, 1761758917),
(41476, 'Exodus 14:13', 'Exodus', 14, 13, 'موسی په ځواب کې وویل: «مه وېرېږئ! په خپل ځای کې ودرېږئ. تاسو به ووینئ چې څښتن نن تاسو ته څنګه خلاصون درکوي. کوم مصریان چې نن یې وینئ، هغه به بیا هېڅکله ونه وینئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_013.mp3', NULL, 1761758917, 1761758917),
(41477, 'Exodus 14:14', 'Exodus', 14, 14, 'تاسو غلي اوسئ، څښتن به ستاسو دپاره جګړه وکړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_014.mp3', NULL, 1761758917, 1761758917),
(41478, 'Exodus 14:15', 'Exodus', 14, 15, 'څښتن موسی ته وویل: «ته ولې ماته د مرستې په خاطر فریاد کوې؟ خلکو ته ووایه چې وړاندې لاړ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_015.mp3', NULL, 1761758917, 1761758917),
(41479, 'Exodus 14:16', 'Exodus', 14, 16, 'خپله امسا پورته کړه او د بحیرې خواته یې ونیسه. اوبه به بېلې شي او اسراییلیان به وکولای شي چې په بحیره کې په وچه ځمکه باندې تېر شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_016.mp3', NULL, 1761758917, 1761758917),
(41480, 'Exodus 14:17', 'Exodus', 14, 17, 'زه به د مصریانو زړونه سخت کړم چې هغوی تاسو پسې درشي او زه به په فرعون، د هغه په لښکرو او جنګي ګاډیو او د هغو په چلوونکو باندې د بریالیتوب په سبب جلال ومومم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_017.mp3', NULL, 1761758917, 1761758917),
(41481, 'Exodus 14:18', 'Exodus', 14, 18, 'کله چې زه د فرعون، د هغه جنګي ګاډیو او اس سوارانو ته ماتې ورکړم او خپل جلال ښکاره کړم، مصریان به پوه شي چې زه څښتن یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_018.mp3', NULL, 1761758917, 1761758917),
(41482, 'Exodus 14:19', 'Exodus', 14, 19, 'د خدای فرښته چې د اسراییلو د لښکرو په مخکې روانه وه، شاته لاړه. هغه د ستنې په شان ورېځ هم د هغوی شاته حرکت وکړ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_019.mp3', NULL, 1761758917, 1761758917),
(41483, 'Exodus 14:20', 'Exodus', 14, 20, 'او هغه د مصریانو او د اسراییلیانو په منځ کې شوه. د شپې په دوران کې ورېځې په مصریانو باندې تیاره راوستله، خو د اسراییلو په قوم یې رڼا راوستله. نو لښکرې په ټوله شپه کې یو بل ته نژدې نه شوې ورتللی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_020.mp3', NULL, 1761758917, 1761758917),
(41484, 'Exodus 14:21', 'Exodus', 14, 21, 'موسی د بحیرې دپاسه خپل لاس ونیوه او څښتن په قوي ختیځ باد باندې د بحیرې اوبه شاته یووړلې. دا باد ټوله شپه ولګېده او بحیره یې په وچه ځمکه بدله کړه. اوبه بېلې شوې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_021.mp3', NULL, 1761758917, 1761758917),
(41485, 'Exodus 14:22', 'Exodus', 14, 22, 'او اسراییلیان په بحیره کې په وچه ځمکه باندې تېر شول او دواړو خواو ته د اوبو دېوالونه وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_022.mp3', NULL, 1761758917, 1761758917),
(41486, 'Exodus 14:23', 'Exodus', 14, 23, 'مصریان د خپلو ټولو اسونو، جنګي ګاډیو او د اس سوارانو سره هغوی تعقیب کړل او په بحیره کې ورپسې روان شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_023.mp3', NULL, 1761758917, 1761758917),
(41487, 'Exodus 14:24', 'Exodus', 14, 24, 'د سهار د رڼا نه مخکې، څښتن د اور او ورېځې له منځ څخه د مصریانو لښکرو ته وکتل او هغوی یې وارخطا کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_024.mp3', NULL, 1761758917, 1761758917),
(41488, 'Exodus 14:25', 'Exodus', 14, 25, 'څښتن د هغوی د ګاډیو ارابې له کاره وغورځولې، نو هغه په سختۍ سره چلېدلې. او مصریانو وویل: «راځئ چې له دې ځای څخه وتښتو، ځکه چې څښتن زمونږ په خلاف د اسراییلیانو دپاره جنګیږي!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_025.mp3', NULL, 1761758917, 1761758917),
(41489, 'Exodus 14:26', 'Exodus', 14, 26, 'بیا څښتن موسی ته وویل: «خپل لاس دې د بحیرې ته اوږد کړه. نو اوبه به بېرته په مصریانو، د هغوی په جنګي ګاډیو او اس سوارانو باندې راشي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_026.mp3', NULL, 1761758917, 1761758917),
(41490, 'Exodus 14:27', 'Exodus', 14, 27, 'نو موسی خپل لاس د بحیرې خواته اوږد کړ او د سهار وختي اوبه خپل لومړني حالت ته راوګرځېدلې. مصریانو هڅه وکړه چې وتښتي، خو څښتن بحیرې ته وروغورځول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_027.mp3', NULL, 1761758917, 1761758917),
(41491, 'Exodus 14:28', 'Exodus', 14, 28, 'اوبه راوګرځېدلې او جنګي ګاډۍ ګانې، اس سواران او ټولې مصري لښکرې یې چې په بحیره کې د اسراییلیانو پسې وې، ډوب کړل او یو هم ژوندی پاتې نه شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_028.mp3', NULL, 1761758917, 1761758917),
(41492, 'Exodus 14:29', 'Exodus', 14, 29, 'خو اسراییلیان په بحیره کې په وچه ځمکه باندې چې اوبه د هغې دواړو خواو ته لکه د دېوالونو په شان ولاړې وې، تېر شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_029.mp3', NULL, 1761758917, 1761758917),
(41493, 'Exodus 14:30', 'Exodus', 14, 30, 'په هغه ورځ څښتن اسراییلیان د مصریانو څخه وژغورل او اسراییلیانو هغوی ولیدل چې د بحیرې په غاړه مړه پراته وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_030.mp3', NULL, 1761758917, 1761758917),
(41494, 'Exodus 14:31', 'Exodus', 14, 31, 'کله چې اسراییلیانو د څښتن لوی قدرت چې هغه مصریانو ته وښوده ولیده، نو هغوی د څښتن څخه ووېرېدل او په هغه او د هغه په خدمتګار موسی باندې یې ایمان راوړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus14_verse_031.mp3', NULL, 1761758917, 1761758917),
(41495, 'Exodus 23:1', 'Exodus', 23, 1, 'د دروغو خبر مه خپروئ. د دروغو په شاهدۍ ورکولو سره د بدکاره سړي سره مرسته مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_001.mp3', NULL, 1761758917, 1761758917),
(41496, 'Exodus 23:2', 'Exodus', 23, 2, 'په بد کار کې د اکثریت څخه پیروي مه کوئ. کله چې تاسو په یوه دعوه کې شاهدي ورکوئ، د اکثریت څخه د طرفدارۍ په کولو سره عدالت تر پښو لاندې مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_002.mp3', NULL, 1761758917, 1761758917),
(41497, 'Exodus 23:3', 'Exodus', 23, 3, 'د یو غریب سړي په محاکمه کې په دې خاطر چې هغه غریب دی، د هغه طرفداري مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_003.mp3', NULL, 1761758917, 1761758917),
(41498, 'Exodus 23:4', 'Exodus', 23, 4, 'که چېرې تاسو ناڅاپه د خپل دښمن غویی یا خر ووینئ چې لار یې غلطه کړې ده، هغه بېرته ورولئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_004.mp3', NULL, 1761758917, 1761758917),
(41499, 'Exodus 23:5', 'Exodus', 23, 5, 'که چېرې تاسو ولیدل چې ستاسو د دښمن خر د بار لاندې پرېوتی دی، هغه هلته مه پرېږدئ، د هغه سره مرسته وکړئ چې خر یې بېرته پاڅیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_005.mp3', NULL, 1761758917, 1761758917),
(41500, 'Exodus 23:6', 'Exodus', 23, 6, 'په محکمه کې د غریب سره بې انصافي مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_006.mp3', NULL, 1761758917, 1761758917),
(41501, 'Exodus 23:7', 'Exodus', 23, 7, 'په دروغو تهمت مه لګوئ او د یو بې ګناه یا صادق سړي د مړینې سبب کېږئ مه. ځکه چې زه به ګناهکار ونه بخښم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_007.mp3', NULL, 1761758917, 1761758917),
(41502, 'Exodus 23:8', 'Exodus', 23, 8, 'رشوت مه اخلئ، ځکه چې رشوت بینا خلک ړندوي او د بې ګناه خلکو حق ورباندې تر پښو لاندې کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_008.mp3', NULL, 1761758917, 1761758917),
(41503, 'Exodus 23:9', 'Exodus', 23, 9, 'په یو مسافر سړي باندې تېری مه کوئ. ځکه چې تاسو خپله په مصر کې مسافران وئ او د مسافرانو د حال څخه خبر یئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_009.mp3', NULL, 1761758917, 1761758917),
(41504, 'Exodus 23:10', 'Exodus', 23, 10, 'تاسو باید شپږ کاله خپلې ځمکې وکرئ او حاصل یې ورېبئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_010.mp3', NULL, 1761758917, 1761758917),
(41505, 'Exodus 23:11', 'Exodus', 23, 11, 'خو په اووم کال هغه ځمکه شاړه پرېږدئ او څه شی چې په کې شنه شوي وي، هغه ورڅخه مه رېبئ. څه چې په کې پاتې وي هغه به غریبان خلک او وحشي حیوانات وخوري. خپل د انګورو باغونو او د زیتونو د ونو د باغونو سره همداسې کار وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_011.mp3', NULL, 1761758917, 1761758917),
(41506, 'Exodus 23:12', 'Exodus', 23, 12, 'په هفته کې شپږ ورځې خپل کار وکړئ، خو په اوومه ورځ کار مه کوئ، ترڅو ستاسو غلامان او پردي خلک چې ستاسو دپاره کار کوي او حتی ستاسو حیوانات هم وکولای شي ارام وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_012.mp3', NULL, 1761758917, 1761758917),
(41507, 'Exodus 23:13', 'Exodus', 23, 13, 'هرڅه چې ما څښتن درته ویلي دي، په هغو باندې عمل کوئ. د نورو خدایانو په نوم دعا مه کوئ، حتی د هغوی نومونه هم په ژبه مه اخلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_013.mp3', NULL, 1761758917, 1761758917),
(41508, 'Exodus 23:14', 'Exodus', 23, 14, 'زما د درناوي په خاطر په کال کې درې ځله اخترونه لمانځئ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_014.mp3', NULL, 1761758917, 1761758917),
(41509, 'Exodus 23:15', 'Exodus', 23, 15, 'لومړی د فطیرې ډوډۍ اختر. لکه څنګه چې ما درته حکم کړی دی اووه ورځې فطیره ډوډۍ وخورئ. دا کار د ابیب په میاشت کې وکړئ، ځکه چې په دې میاشت کې تاسو له مصر څخه راووتلئ. په دې اختر کې دې هېڅوک زما حضور ته خالي لاس نه راځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_015.mp3', NULL, 1761758917, 1761758917),
(41510, 'Exodus 23:16', 'Exodus', 23, 16, 'تاسو د لو کولو اختر د خپلو لومړنیو حاصلاتو سره چې په خپلو پټیو کې مو کرلي دي، ولمانځئ. د کال په اخر کې د حاصل د راټولولو اختر ولمانځئ، یعنې کله چې تاسو د پټیو څخه حاصل راټولوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_016.mp3', NULL, 1761758917, 1761758917),
(41511, 'Exodus 23:17', 'Exodus', 23, 17, 'هر کال باید په دغو درېو اخترونو کې ستاسو ټول نارینه زما یعنې ستاسو د څښتن تعالی د عبادت دپاره راشي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_017.mp3', NULL, 1761758917, 1761758917),
(41512, 'Exodus 23:18', 'Exodus', 23, 18, 'کله چې تاسو ماته یو حیوان قرباني کوئ، د هغه سره خمیره ډوډۍ مه وړاندې کوئ. هغه حیوانات چې په دغو اخترونو کې ماته قرباني کیږي، د هغې وازګه باید تر سهاره پورې پاتې نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_018.mp3', NULL, 1761758917, 1761758917),
(41513, 'Exodus 23:19', 'Exodus', 23, 19, 'هر کال د خپل څښتن خدای کور ته د خپل لومړني حاصل ډېرې ښې غلې دانې راوړئ. یو سېرلی د خپلې مور په شیدو کې مه پخوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_019.mp3', NULL, 1761758917, 1761758917),
(41514, 'Exodus 23:20', 'Exodus', 23, 20, 'ګورئ، زه ستاسو مخې ته یوه فرښته درلېږم چې په لاره کې ستاسو ساتنه وکړي او هغه ځای ته مو راولي چې ستاسو دپاره مې تیار کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_020.mp3', NULL, 1761758917, 1761758917),
(41515, 'Exodus 23:21', 'Exodus', 23, 21, 'هرڅه چې هغه فرښته وایي په غور سره ورڅخه اطاعت وکړئ. د هغې په وړاندې سرکښي مه کوئ، هغه به ستاسو سرکښي ونه بخښي، ځکه چې پوره اختیار مې ورته ورکړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_021.mp3', NULL, 1761758917, 1761758917),
(41516, 'Exodus 23:22', 'Exodus', 23, 22, 'که چېرې تاسو په غور سره د هغې خبرو ته غوږ ونیسئ او هرڅه چې زه درته وایم هغه وکړئ، نو زه به ستاسو د دښمنانو دښمن شم او زه به د هغه چا په خلاف شم چې ستاسو په خلاف وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_022.mp3', NULL, 1761758917, 1761758917),
(41517, 'Exodus 23:23', 'Exodus', 23, 23, 'زما فرښته به ستاسو په مخکې روانه وي او تاسو به د اموریانو، حیتیانو، فرزیانو، کنعانیانو، حویانو او یبوسیانو خاورې ته بوځي او زه به هغوی ټول له منځه یوسم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_023.mp3', NULL, 1761758917, 1761758917),
(41518, 'Exodus 23:24', 'Exodus', 23, 24, 'د هغوی خدایانو ته سجده یا عبادت مه کوئ او د هغوی د رواجونو څخه پیروي مه کوئ. د هغوی بتان له منځه یوسئ او هغه لویې تیږې چې د هغوی د عبادت دپاره ورڅخه کار اخیستل کیږي، ټوټې ټوټې کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_024.mp3', NULL, 1761758917, 1761758917),
(41519, 'Exodus 23:25', 'Exodus', 23, 25, 'که چېرې تاسو زما یعنې د خپل څښتن خدای عبادت وکړئ، نو زه به ستاسو په خوراک او اوبو کې برکت واچوم او ستاسو ټولې ناروغۍ به لېرې کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_025.mp3', NULL, 1761758917, 1761758917),
(41520, 'Exodus 23:26', 'Exodus', 23, 26, 'ستاسو په خاوره کې به هېڅ یوه ښځه خپل اولاد نقصان نه کړي او نه به شنډه شي. زه به تاسو ته اوږده عمرونه درکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_026.mp3', NULL, 1761758917, 1761758917),
(41521, 'Exodus 23:27', 'Exodus', 23, 27, 'زه به په هغو قومونو باندې سخته وېره راولم او ستاسو دښمنان به دومره وارخطا کړم چې درڅخه وتښتي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_027.mp3', NULL, 1761758917, 1761758917),
(41522, 'Exodus 23:28', 'Exodus', 23, 28, 'زه به ستاسو په دښمنانو کې سخته وېره پیدا کړم او حویان، کنعانیان او حیتیان به ستاسو له مخې څخه لېرې کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_028.mp3', NULL, 1761758917, 1761758917),
(41523, 'Exodus 23:29', 'Exodus', 23, 29, 'خو زه به هغوی په یو کال کې ونه باسم، ځکه چې ځمکه به ویجاړه پاتې شي او وحشي حیوانات به ډېر زیات شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_029.mp3', NULL, 1761758917, 1761758917),
(41524, 'Exodus 23:30', 'Exodus', 23, 30, 'بلکې هغوی به لږ لږ شړم، ترڅو تاسو دومره ډېر شئ چې هغه خاوره ونیسئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_030.mp3', NULL, 1761758917, 1761758917),
(41525, 'Exodus 23:31', 'Exodus', 23, 31, 'زه به ستاسو د خاورې سرحدونه د سرې بحیرې څخه نیولې د مدیترانې تر بحیرې پورې او د دښتې څخه نیولې د فرات تر سینده پورې وغزوم. زه به تاسو سره مرسته وکړم چې هغو خلکو ته چې اوس په دې خاوره کې اوسیږي، ماتې ورکړئ او هغوی به وشړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_031.mp3', NULL, 1761758917, 1761758917),
(41526, 'Exodus 23:32', 'Exodus', 23, 32, 'د هغوی یا د هغوی د خدایانو سره هېڅ ډول تړون مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_032.mp3', NULL, 1761758917, 1761758917),
(41527, 'Exodus 23:33', 'Exodus', 23, 33, 'هغوی مه پرېږدئ چې ستاسو په هېواد کې واوسیږي. که چېرې تاسو هغوی پرېږدئ، هغوی به تاسو زما په ضد په ګناه کولو باندې مجبور کړي. که چېرې تاسو د هغوی د خدایانو عبادت وکړئ، نو دا به ستاسو دپاره یو وژونکی دام وي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus23_verse_033.mp3', NULL, 1761758917, 1761758917),
(41528, 'Psalms 100:1', 'Psalms', 100, 1, 'ای ټولې نړۍ، څښتن ته ووهئ د خوشحالۍ چیغې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms100_verse_001.mp3', NULL, 1761758917, 1761758917),
(41529, 'Psalms 100:2', 'Psalms', 100, 2, 'وکړئ عبادت د څښتن خدای په خوشحالۍ سره په سندرو د خوښۍ د هغه حضور ته راشئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms100_verse_002.mp3', NULL, 1761758917, 1761758917),
(41530, 'Psalms 100:3', 'Psalms', 100, 3, 'ومنئ دا چې څښتن خدای دی مونږ یو خلق کړي هغه او د هغه یو مونږه مونږ یو خلک د هغه او رمه یې د څړځای یو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms100_verse_003.mp3', NULL, 1761758917, 1761758917),
(41531, 'Psalms 100:4', 'Psalms', 100, 4, 'شکر کولو سره ننوځئ د هغه دروازو ته د هغه عبادتځای ته د ثنا سره ورننوځئ شکر یې ادا کړئ او صفت یې د نامه وکړئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms100_verse_004.mp3', NULL, 1761758917, 1761758917),
(41532, 'Psalms 100:5', 'Psalms', 100, 5, 'ځکه څښتن دی نېک او ده ابدي د هغه مینه وفاداري یې ده جاري د یو نسل نه تر بله پورې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms100_verse_005.mp3', NULL, 1761758917, 1761758917),
(41533, 'Nahum 2:1', 'Nahum', 2, 1, 'ای نینوا، ته د حملې لاندې یې وساته خپلې جنګي کلاوې وڅاره لارې، جنګ ته تیار اوسه کړه راټول خپل قوتونه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_001.mp3', NULL, 1761758917, 1761758917),
(41534, 'Nahum 2:2', 'Nahum', 2, 2, 'څښتن به د اسراییلو هغه شان او شوکت چې دښمنانو یې له منځه وړی ؤ، لکه د یهودا د شان او شوکت په شان بېرته ورته راولي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_002.mp3', NULL, 1761758917, 1761758917),
(41535, 'Nahum 2:3', 'Nahum', 2, 3, 'راروان کړي د دښمن لښکرو سره سپرونه د هغه عسکرو دی اغوستی سور لباس ځلیږي په ګاډیو لګېدلی فلز په هغه ورځ چې کړي تیار هغوی نو عسکر به کړي راپورته خپلې نېزې او خوځوي به هغه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_003.mp3', NULL, 1761758917, 1761758917),
(41536, 'Nahum 2:4', 'Nahum', 2, 4, 'د توفان په شان روانې دي جنګي ګاډۍ کوڅو کې تېزې تېزې ځي راځي په څلور لارو کې هغوی پړقیږي څراغونو په شان او تېزې روانې دي لکه برېښنا په شان', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_004.mp3', NULL, 1761758917, 1761758917),
(41537, 'Nahum 2:5', 'Nahum', 2, 5, 'راټولیږي عسکري منصبداران څنګه چې ځي هغوی په لاره نو ښوییږي هغوی په چټکۍ سره روان دي هغوی د دېوالونو خواته چې کړي جوړ د محاصرې برج', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_005.mp3', NULL, 1761758917, 1761758917),
(41538, 'Nahum 2:6', 'Nahum', 2, 6, 'دي خلاص شوي د اوبو بندونه او په رالوېدو ده ماڼۍ', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_006.mp3', NULL, 1761758917, 1761758917),
(41539, 'Nahum 2:7', 'Nahum', 2, 7, 'ملکه یې لوڅه شوې او وړل شوې هغه کوي ویر د هغې وینځې کړي زګېروي لکه کوترو په شان او له خفګانه وهي خپلې سینې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_007.mp3', NULL, 1761758917, 1761758917),
(41540, 'Nahum 2:8', 'Nahum', 2, 8, 'ده نینوا لکه د ډنډ په شان چې اوبه وي ترې روانې وهي چیغې منصبداران: ودرېږئ! ودرېږئ! خو شاته نه ګوري هېڅوک', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_008.mp3', NULL, 1761758917, 1761758917),
(41541, 'Nahum 2:9', 'Nahum', 2, 9, 'د دښمن عسکران چیغې وهي چې لوټ کړئ سپین زر، لوټ کړئ سره زر خزانې یې نه خلاصیږي د هر ډول قیمتي شیانو', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_009.mp3', NULL, 1761758917, 1761758917),
(41542, 'Nahum 2:10', 'Nahum', 2, 10, 'نینوا دی وران، شاړ او ویجاړ پروت دی کمزوري شوي زړونه او رپیږي یې زنګنونه ټول قوت یې تللی او رنګ یې الوتی له مخونو څخه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_010.mp3', NULL, 1761758917, 1761758917),
(41543, 'Nahum 2:11', 'Nahum', 2, 11, 'اوس دی چېرته نینوا هغه غار د زمرو هغه ځای چې ورکولو به هغوی خپلو بچو ته خواړه هغه ځای چې به ورتلل ورته نران او ښځینه زمریان او په کې خوندي وو د زمرو بچيان؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_011.mp3', NULL, 1761758917, 1761758917),
(41544, 'Nahum 2:12', 'Nahum', 2, 12, 'زمري وکړ پوره ښکار خپلو بچو ته ټوټې ټوټې کوي هغه خپلې زمرۍ دپاره او ډکوي خپل غار د غوښو له ټوټو نه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_012.mp3', NULL, 1761758917, 1761758917),
(41545, 'Nahum 2:13', 'Nahum', 2, 13, 'مطلق قادر څښتن داسې وایي: «زه ستا په خلاف یم! زه به ستا جنګي ګاډۍ وسوځوم. ستا عسکر به په جنګ کې مړه شي او کوم شیان چې تا د نورو خلکو نه لوټ کړي دي، هغه به درڅخه بېرته واخلم. ستا د استازو غوښتنې به نور نه اورېدل کیږي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nahum2_verse_013.mp3', NULL, 1761758917, 1761758917),
(41546, 'Psalms 137:1', 'Psalms', 137, 1, 'مونږه په غاړه د سیندونو د بابل کښېناستو مونږ هلته وژړل په یاد د صهیون', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms137_verse_001.mp3', NULL, 1761758917, 1761758917),
(41547, 'Psalms 137:2', 'Psalms', 137, 2, 'مونږه ځوړند کړل خپل ربابونه د سپېدار په څانګو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms137_verse_002.mp3', NULL, 1761758917, 1761758917),
(41548, 'Psalms 137:3', 'Psalms', 137, 3, 'هغو کسانو چې نیولي یې وو مونږ هلته مونږ ته یې وویل چې سندرې وایئ چې زمونږ وخت ښه تېر شي مونږ ته ووایئ یوه سندره د صهیون په هکله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms137_verse_003.mp3', NULL, 1761758917, 1761758917),
(41549, 'Psalms 137:4', 'Psalms', 137, 4, 'څنګه کولای شو مونږ چې د څښتن سندره ووایو په پردي وطن کې؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms137_verse_004.mp3', NULL, 1761758917, 1761758917),
(41550, 'Psalms 137:5', 'Psalms', 137, 5, 'ای اورشلیمه، که مې هېر کړلې ته نو زما ښي لاس دې شي شل چې بیا ونه وهم رباب', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms137_verse_005.mp3', NULL, 1761758917, 1761758917),
(41551, 'Psalms 137:6', 'Psalms', 137, 6, 'که زه تا یاد نه کړمه اورشلیمه که زه د ستا په هکله ونه کړم فکر چې ته یې لویه خوشحالي زما نو ودې نښلي زما ژبه په تالو کې چې بیا ونه وایم سندرې کله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms137_verse_006.mp3', NULL, 1761758917, 1761758917),
(41552, 'Psalms 137:7', 'Psalms', 137, 7, 'یاد کړه څښتنه، څه وکړل ادومیانو په هغه ورځ چې اورشلیم تسخیر شو یاد کړه چې څنګه دوی وهلې چیغې: «هغه وران کړئ، هغه وران کړئ وران یې کړئ تر تهدابونو پورې»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms137_verse_007.mp3', NULL, 1761758917, 1761758917),
(41553, 'Psalms 137:8', 'Psalms', 137, 8, 'ته به نابود شې ای بابله بختور دي هغه خلک چې تا سره وکړي هغه کار چې تا کړی ؤ زمونږ سره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms137_verse_008.mp3', NULL, 1761758917, 1761758917),
