(41555, 'Psalms 48:1', 'Psalms', 48, 1, 'څښتن خدای دی لوی هغه لایق دی د ثنا ټولې په هغه ښار کې چېرې اوسیږي چې په خپل سپېڅلي غر باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_001.mp3', NULL, 1761758917, 1761758917),
(41556, 'Psalms 48:2', 'Psalms', 48, 2, 'لوړ او ښایسته دی صهیون د هغه لوی پاچا ښار کوم چې خوشحالي راوړي نړۍ ټولې ته دی د هغه لوړ غر په څېر کوم چې شمال کې پروت دی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_002.mp3', NULL, 1761758917, 1761758917),
(41557, 'Psalms 48:3', 'Psalms', 48, 3, 'خلکو ته وښودله خدای چې خوندیتوب دی د هغه سره دا خوندیتوب په پناه ځای د ښار کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_003.mp3', NULL, 1761758917, 1761758917),
