(41561, 'Psalms 48:7', 'Psalms', 48, 7, 'داسې نابود دې کړل هغوی لکه شرقي باد چې کشتۍ د ترشیش ماتې کړلې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_007.mp3', NULL, 1761758917, 1761758917),
(41562, 'Psalms 48:8', 'Psalms', 48, 8, 'هغو کارو په هکله مونږ وو اورېدلي کوم چې کړي دي خدای هغه مو اوس ولیدل دا د مطلق قادر څښتن ښار کې د خپل خدای ښار کې هغه به خوندي وساتي تل ترتله دغه ښار', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_008.mp3', NULL, 1761758917, 1761758917),
(41563, 'Psalms 48:9', 'Psalms', 48, 9, 'خدایه، د ستا د کور په منځ کې مونږ کوو فکر ستا د مینې په هکله د تلپاتې مینې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_009.mp3', NULL, 1761758917, 1761758917),
(41564, 'Psalms 48:10', 'Psalms', 48, 10, 'نوم دې خپور شوی دی په ټول جهان کې ځکه خلک هرځای کې ثنا وایي ستا ته په انصاف سره حکومت کوې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_010.mp3', NULL, 1761758917, 1761758917),
