(41566, 'Psalms 48:12', 'Psalms', 48, 12, 'ای د خدای قومه، د صهیون په شاوخوا وګرځئ تاسو حساب کړئ د هغه برجونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_012.mp3', NULL, 1761758917, 1761758917),
(41567, 'Psalms 48:13', 'Psalms', 48, 13, 'په دېوالونو یې په غور سره نظر واچوئ او امتحان یې کړئ جنګي کلاوې راتلونکي نسل ته بیا تاسو دا ویلی شئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms48_verse_013.mp3', NULL, 1761758917, 1761758917),
