(41569, 'Exodus 2:1', 'Exodus', 2, 1, 'په همدې وخت کې یو سړي چې د لاوي د قبیلې څخه ؤ د خپلې قبیلې د یوې ښځې سره واده وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_001.mp3', NULL, 1761758917, 1761758917),
(41570, 'Exodus 2:2', 'Exodus', 2, 2, 'هغه ښځه امیدواره شوه او زوی یې پیدا شو. کله چې هغې ولیدل چې ماشوم یې ښکلی دی، نو هغه یې د درېو میاشتو دپاره پټ وساته.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_002.mp3', NULL, 1761758917, 1761758917),
(41571, 'Exodus 2:3', 'Exodus', 2, 3, 'کله چې هغې نور نه شو کولای چې هغه ماشوم پټ وساتي، نو د لوخو څخه یې یوه ټوکرۍ جوړه کړه او د قیرو پوښ یې ورته ورکړ. هغې ماشوم په ټوکرۍ کې واچاوه او د نیل د سیند په غاړه یې د لوخو په منځ کې لاهو کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_003.mp3', NULL, 1761758917, 1761758917),
(41572, 'Exodus 2:4', 'Exodus', 2, 4, 'د ماشوم خور لږه لېرې ودرېدله چې وګوري په ماشوم باندې څه کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_004.mp3', NULL, 1761758917, 1761758917),
(41573, 'Exodus 2:5', 'Exodus', 2, 5, 'په دې وخت کې د فرعون لور د لمبلو دپاره سیند ته راغله او د هغې وینځې د سیند په غاړه ګرځېدلې. په دې وخت کې هغې د لوخو په منځ کې هغه ټوکرۍ ولیدله او یوه ښځه یې ورولېږله چې هغه د اوبو څخه راوباسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_005.mp3', NULL, 1761758917, 1761758917),
(41574, 'Exodus 2:6', 'Exodus', 2, 6, 'کله چې د فرعون لور ټوکرۍ پرانیستله هغې ماشوم ولیده او ورباندې خفه شوه، ځکه چې هغه ژړل. هغې وویل: «دا یو عبرانی ماشوم دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_006.mp3', NULL, 1761758917, 1761758917),
(41575, 'Exodus 2:7', 'Exodus', 2, 7, 'ناڅاپه د ماشوم خور راغله او پوښتنه یې وکړه: «ایا ته غواړې چې زه لاړه شم او دغه ماشوم ته یوه عبرانۍ ښځه راولم چې تی ورکړي؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_007.mp3', NULL, 1761758917, 1761758917),
(41576, 'Exodus 2:8', 'Exodus', 2, 8, 'د فرعون لور په ځواب کې وویل: «هو، لاړه شه.» نو انجلۍ لاړه او د ماشوم خپله مور یې راوستله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_008.mp3', NULL, 1761758917, 1761758917),
(41577, 'Exodus 2:9', 'Exodus', 2, 9, 'د فرعون لور هغې ښځې ته وویل: «دا ماشوم واخله او زما دپاره شیدې ورکوه او روزنه یې کوه. زه به تاته پیسې درکوم.» هغې ماشوم یووړ او د هغه روزنه یې کوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_009.mp3', NULL, 1761758917, 1761758917),
(41578, 'Exodus 2:10', 'Exodus', 2, 10, 'کله چې دا ماشوم لوی شو، نو هغه یې د فرعون لور ته یووړ او هغې لکه د خپل زوی په شان وساته. هغې په دې ماشوم باندې موسی نوم کېښود، ځکه چې هغې د ځان سره وویل: «ما هغه د اوبو څخه راوویست.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_010.mp3', NULL, 1761758917, 1761758917),
(41579, 'Exodus 2:11', 'Exodus', 2, 11, 'کله چې موسی لوی شو، هغه د خپل قوم سره د لیدنې کتنې دپاره لاړ. هغه ولیدل چې د هغه قوم څومره سخت کار کاوه. هغه یو مصری ولیده چې یو عبرانی یې واهه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_011.mp3', NULL, 1761758917, 1761758917),
(41580, 'Exodus 2:12', 'Exodus', 2, 12, 'موسی یو خوا بل خوا وکتل، کله چې پوه شو څوک یې نه ویني، نو هغه مصری یې وواژه او په شګه کې یې پټ کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_012.mp3', NULL, 1761758917, 1761758917),
(41581, 'Exodus 2:13', 'Exodus', 2, 13, 'کله چې موسی بله ورځ ووت، هغه دوه عبرانیان ولیدل چې یو د بل سره یې جګړه کوله. نو موسی له هغه یو څخه چې ملامت ؤ، پوښتنه وکړه: «ته ولې خپل عبرانی وطندار وهې؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_013.mp3', NULL, 1761758917, 1761758917),
(41582, 'Exodus 2:14', 'Exodus', 2, 14, 'هغه سړي په ځواب کې وویل: «ته چا په مونږ باندې حاکم او قاضي ټاکلی یې؟ ته غواړې چې ما هم ووژنې لکه څنګه چې دې هغه مصری وواژه؟» موسی د دې خبرې په اورېدلو ووېرېده او د ځان سره یې وویل: «خلک پوه شوي دي چې ما څه کړي دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_014.mp3', NULL, 1761758917, 1761758917),
(41583, 'Exodus 2:15', 'Exodus', 2, 15, 'کله چې فرعون د موسی د دې کار څخه خبر شو، هغه د موسی د وژلو هڅه وکړه. خو هغه د مدیان خاورې ته وتښتېده. یوه ورځ موسی د څاه په غاړه ناست ؤ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_015.mp3', NULL, 1761758917, 1761758917),
(41584, 'Exodus 2:16', 'Exodus', 2, 16, 'چې د مدیان کاهن یترون اووه لورګانې راغلې چې اوبه راوباسي او د خپلې رمې دپاره اخورونه ډک کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_016.mp3', NULL, 1761758917, 1761758917),
(41585, 'Exodus 2:17', 'Exodus', 2, 17, 'خو څو شپنو د یترون لورګانې وشړلې. بیا موسی د هغوی سره د مرستې کولو دپاره ورغی او رمې ته یې اوبه ورکړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_017.mp3', NULL, 1761758917, 1761758917),
(41586, 'Exodus 2:18', 'Exodus', 2, 18, 'کله چې د یترون لورګانې خپل کور ته راستنې شوې، نو پلار یې پوښتنه ورڅخه وکړه: «تاسو نن دومره وختي ولې راغلئ؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_018.mp3', NULL, 1761758917, 1761758917),
(41587, 'Exodus 2:19', 'Exodus', 2, 19, 'هغوی په ځواب کې وویل: «یو مصري د شپنو څخه وژغورلو او زمونږ دپاره یې اوبه راوویستلې او رمې ته یې ورکړې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_019.mp3', NULL, 1761758917, 1761758917),
(41588, 'Exodus 2:20', 'Exodus', 2, 20, 'یترون پوښتنه وکړه: «هغه چېرته دی؟ تاسو ولې هغه هلته پرېښود؟ هغه ته بلنه ورکړئ چې زمونږ سره ډوډۍ وخوري.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_020.mp3', NULL, 1761758917, 1761758917),
(41589, 'Exodus 2:21', 'Exodus', 2, 21, 'نو موسی راضي شو چې د یترون سره پاتې شي او هغه خپله لور صفوره موسی ته په نکاح ورکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_021.mp3', NULL, 1761758917, 1761758917),
(41590, 'Exodus 2:22', 'Exodus', 2, 22, 'کله چې د هغې زوی پیدا شو، موسی وویل: «زه به د هغه نوم جرشون کېږدم، ځکه چې زه په دې خاوره کې پردی یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_022.mp3', NULL, 1761758917, 1761758917),
(41591, 'Exodus 2:23', 'Exodus', 2, 23, 'وروسته له ډېرو کلونو د مصر پاچا مړ شو. اسراییلیانو لا هم د غلامۍ له امله فریادونه کول او د خدای څخه یې مرسته غوښتله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_023.mp3', NULL, 1761758917, 1761758917),
(41592, 'Exodus 2:24', 'Exodus', 2, 24, 'خدای د دوی فریاد واورېده او هغه لوظ یې را په یاد کړ چې د ابراهیم، اسحاق او یعقوب سره یې کړی ؤ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_024.mp3', NULL, 1761758917, 1761758917),
(41593, 'Exodus 2:25', 'Exodus', 2, 25, 'ځکه چې خدای ولیدل چې د هغه په قوم باندې څه تېریږي. نو هغه ورباندې ډېر اندېښمن شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus2_verse_025.mp3', NULL, 1761758917, 1761758917),
(41594, 'Job 18:1', 'Job', 18, 1, 'بيا شوحى بِلداد جواب ورکړو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_001.mp3', NULL, 1761758917, 1761758917),
(41595, 'Job 18:2', 'Job', 18, 2, '”تر کومې پورې به تۀ خبرې کوې؟ د مطلب خبره کوه، نو بيا به مونږ خبرې وکړُو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_002.mp3', NULL, 1761758917, 1761758917),
(41596, 'Job 18:3', 'Job', 18, 3, 'مونږ په ځناورو کښې ولې شمېرلے شُو؟ مونږ ستاسو په نظر کښې ولې کم عقلان يُو؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_003.mp3', NULL, 1761758917, 1761758917),
(41597, 'Job 18:4', 'Job', 18, 4, 'تۀ په غصه کښې هسې خپل ځان سوزوې، ستا دپاره دې دُنيا پرېښودلے شى څۀ، يا غرونه دې ستا دپاره د خپل ځائ نه لرې کړے شى څۀ؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_004.mp3', NULL, 1761758917, 1761758917),
(41598, 'Job 18:5', 'Job', 18, 5, 'په حقيقت کښې د بدعمله خلقو ډيوه ختمه کړے شوې ده، او بيا به د هغې شُغلې بلې نۀ شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_005.mp3', NULL, 1761758917, 1761758917),
(41599, 'Job 18:6', 'Job', 18, 6, 'د هغوئ په خېمه کښې رڼا په تيارۀ بدله شوې ده، او د هغوئ دپاسه ډيوه مړه کړے شوې ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_006.mp3', NULL, 1761758917, 1761758917),
(41600, 'Job 18:7', 'Job', 18, 7, 'د هغوئ مضبوط قدمونه خطا شوى دى، او د هغوئ خپلو منصوبو هغوئ ناکامه کړى دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_007.mp3', NULL, 1761758917, 1761758917),
(41601, 'Job 18:8', 'Job', 18, 8, 'ځکه چې هغوئ په يو جال کښې انښتى دى، او هغوئ په يوه کنده کښې پرېوځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_008.mp3', NULL, 1761758917, 1761758917),
(41602, 'Job 18:9', 'Job', 18, 9, 'د هغوئ پونده په دام کښې ګېريږى، او هغه يې کلک ونيسى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_009.mp3', NULL, 1761758917, 1761758917),
(41603, 'Job 18:10', 'Job', 18, 10, 'يو جال په زمکه کښې پټ دے، او د هغوئ په لاره کښې يو دام پټ دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_010.mp3', NULL, 1761758917, 1761758917),
(41604, 'Job 18:11', 'Job', 18, 11, 'هغوئ د هر طرف نه يريږى، او چې چرته هم ځى نو يره ورپسې وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_011.mp3', NULL, 1761758917, 1761758917),
(41605, 'Job 18:12', 'Job', 18, 12, 'د هغوئ طاقت د لوږې په وجه ختم شوے دے، او تباهى د هغوئ د غلطۍ په انتظار کښې ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_012.mp3', NULL, 1761758917, 1761758917),
(41606, 'Job 18:13', 'Job', 18, 13, 'بيمارى د هغوئ څرمن خورى، او مرګ د هغوئ اندامونه خورى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_013.mp3', NULL, 1761758917, 1761758917),
(41607, 'Job 18:14', 'Job', 18, 14, 'چې په کومو خېمو کښې هغوئ په حِفاظت کښې وُو نو هغوئ ويستلے شوى دى، او هغوئ د دهشت بادشاه ته راوستلے شوى دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_014.mp3', NULL, 1761758917, 1761758917),
(41608, 'Job 18:15', 'Job', 18, 15, 'د هغوئ په خېمو کښې هيڅ څوک هم پاتې نۀ دى، او د هغوئ د کورونو دپاسه د ګوګړو باران دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_015.mp3', NULL, 1761758917, 1761758917),
(41609, 'Job 18:16', 'Job', 18, 16, 'د هغوئ جرړې لاندې اوچې شوې دى، او د هغوئ څانګې پاس مړاوې شوې دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_016.mp3', NULL, 1761758917, 1761758917),
(41610, 'Job 18:17', 'Job', 18, 17, 'د هغوئ نوم به د زمکې نه ختم شى، او په لارو کوڅو کښې به د هغوئ ذکر نۀ کيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_017.mp3', NULL, 1761758917, 1761758917),
(41611, 'Job 18:18', 'Job', 18, 18, 'هغوئ د رڼا نه تيارې ته ديکه کړے شوى دى، او د دُنيا نه شړلے شوى دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_018.mp3', NULL, 1761758917, 1761758917),
(41612, 'Job 18:19', 'Job', 18, 19, 'د هغوئ اولاد نشته، او د هغوئ د خاندان يو کس هم ژوندے پاتې شوے نۀ دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_019.mp3', NULL, 1761758917, 1761758917),
(41613, 'Job 18:20', 'Job', 18, 20, 'د نمرخاتۀ طرف نه واخله تر نمرپرېواتۀ پورې چې څوک هم د هغوئ د اَنجام نه خبريږى، نو د يرې نه لړزيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_020.mp3', NULL, 1761758917, 1761758917),
(41614, 'Job 18:21', 'Job', 18, 21, 'دوئ به وائى چې دا د بدعمله خلقو کور دے، د هغه چا څوک چې د خُدائ پاک نه منکر وى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job18_verse_021.mp3', NULL, 1761758917, 1761758917),
(41615, 'Psalms 80:1', 'Psalms', 80, 1, 'ای د اسراییلو شپونه ته مونږ ته غوږ ونیسه ای چې د یوسف د قبیلې کړې لارښوونه د رمې په څېر ته په خپل تخت ناست یې پاس په سر د اسماني مخلوق خپل جلال دې راښکاره کړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_001.mp3', NULL, 1761758917, 1761758917),
(41616, 'Psalms 80:2', 'Psalms', 80, 2, 'ځان دې ښکاره خپل قبیلو ته کړه یعنې د افرایم، بنیامین او منسي قبیلې ته قدرت دې خپل مونږ ته راوښایه ته راشه او خلاص کړه مونږه!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_002.mp3', NULL, 1761758917, 1761758917),
(41617, 'Psalms 80:3', 'Psalms', 80, 3, 'مونږ بېرته راوله خپل حال ته خدایه! په ورین تندي وګوره مونږ ته چې خلاص شو مونږه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_003.mp3', NULL, 1761758917, 1761758917),
(41618, 'Psalms 80:4', 'Psalms', 80, 4, 'ای مطلق قادر څښتنه خدایه ته به ترڅو پورې په قهر یې خپل قوم باندې او نه به اورې دعاګانې دې د خپلو خلکو؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_004.mp3', NULL, 1761758917, 1761758917),
(41619, 'Psalms 80:5', 'Psalms', 80, 5, 'د ډوډۍ په ځای خوراک دې کړلو اوښکې د دوی په دوی دې وڅښلو د اوښکو ډک جام', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_005.mp3', NULL, 1761758917, 1761758917),
(41620, 'Psalms 80:6', 'Psalms', 80, 6, 'تا مونږ د خپلو ګاونډیانو د خندا کړلو وهي ملنډې دښمنان زمونږ په مونږ باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_006.mp3', NULL, 1761758917, 1761758917),
(41621, 'Psalms 80:7', 'Psalms', 80, 7, 'مونږ بېرته راوله خپل حال ته ای مطلق قادره خدایه! په ورین تندي وګوره مونږ ته چې خلاص شو مونږه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_007.mp3', NULL, 1761758917, 1761758917),
(41622, 'Psalms 80:8', 'Psalms', 80, 8, 'د تاک په شان دې خپل قوم وویسته د مصر څخه تا وشړل نور اقوام وکرل دوی دې د هغوی په ځای کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_008.mp3', NULL, 1761758917, 1761758917),
(41623, 'Psalms 80:9', 'Psalms', 80, 9, 'تا هغه ځمکه کړله پاکه ورته وځغلولې هغه ځای کې یې ریښې ژورې ورباندې ډکه شوله ټوله ځمکه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_009.mp3', NULL, 1761758917, 1761758917),
(41624, 'Psalms 80:10', 'Psalms', 80, 10, 'شول غرونه ټول یې پټ په سیوري باندې د سبر غټې ونې راوستې شاخونو یې تر سیوري لاندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_010.mp3', NULL, 1761758917, 1761758917),
(41625, 'Psalms 80:11', 'Psalms', 80, 11, 'مدیترانې تر بحیرې پورې یې لاړې څانګې او شولې خپرې د فرات تر سینده', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_011.mp3', NULL, 1761758917, 1761758917),
(41626, 'Psalms 80:12', 'Psalms', 80, 12, 'ولې دې وران کړل دېوالونه شاوخوا د هغه؟ اوس چې هرڅوک ورنه تېریږي نو راشکوي ترې انګور', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_012.mp3', NULL, 1761758917, 1761758917),
(41627, 'Psalms 80:13', 'Psalms', 80, 13, 'وحشي خوګان لاندې کوي یې تر‌پښو په کې څریږي ټول وحشي ځناور', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_013.mp3', NULL, 1761758917, 1761758917),
(41628, 'Psalms 80:14', 'Psalms', 80, 14, 'مطلق قادر خدایه راواړوه مخ! ته له اسمانه مونږ ته ښکته وګوره راشه او وساته خپل قوم دې خدایه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_014.mp3', NULL, 1761758917, 1761758917),
(41629, 'Psalms 80:15', 'Psalms', 80, 15, 'راشه او وساته نیالګی کوم چې کرلی دی تا دغه ځوان تاک چې قوي کړی دی تا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_015.mp3', NULL, 1761758917, 1761758917),
(41630, 'Psalms 80:16', 'Psalms', 80, 16, 'هغه ته اور دی اچولی دښمنانو زمونږ او راچپه کړی یې دی هغوی ته وګوره په قهر او برباد کړه هغوی!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_016.mp3', NULL, 1761758917, 1761758917),
(41631, 'Psalms 80:17', 'Psalms', 80, 17, 'نو ته قوي کړه هغه کس چې ورسره مینه کوې هغه څوک چې غوره کړی دی تا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_017.mp3', NULL, 1761758917, 1761758917),
(41632, 'Psalms 80:18', 'Psalms', 80, 18, 'بیا به هېڅکله تا نه مونږه خپل مخ نه اړوو ته مونږ ژوندي وساته چې ستا ستاینه وکړو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_018.mp3', NULL, 1761758917, 1761758917),
(41633, 'Psalms 80:19', 'Psalms', 80, 19, 'مونږ بېرته راوله خپل حال ته ای مطلق قادر څښتنه خدایه! په ورین تندي وګوره مونږ ته چې خلاص شو مونږه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms80_verse_019.mp3', NULL, 1761758917, 1761758917),
(41634, 'Ezekiel 46:1', 'Ezekiel', 46, 1, 'څښتن تعالی داسې وایي: «دنننۍ حوېلۍ ته د ختیځې خوا د ننوتلو دروازه باید د هفتې په شپږو کاري ورځو کې بنده وساتل شي، خو د سبت په ورځ او د نوې میاشتې په اختر کې باید خلاصه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_001.mp3', NULL, 1761758917, 1761758917),
(41635, 'Ezekiel 46:2', 'Ezekiel', 46, 2, 'مشر به د باندینۍ حوېلۍ نه د دروازې په لاره دنننۍ کوټې ته ننوځي او په داسې حال کې چې کاهنان د هغه سوځېدونکې نذرانه او د هغه د سلامتۍ نذرانې وړاندې کوي، هغه به د دروازې د چوکاټ سره ودریږي. هغه باید هلته د دروازې د خولې سره عبادت وکړي او بیا دباندې ووځي. دروازه باید تر ماښامه پورې ونه تړل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_002.mp3', NULL, 1761758917, 1761758917),
(41636, 'Ezekiel 46:3', 'Ezekiel', 46, 3, 'د سبت په ورځ او د هرې نوې میاشتې په اختر کې باید د هېواد ټول خلک د هغې دروازې مخې ته څښتن ته سجده وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_003.mp3', NULL, 1761758917, 1761758917),
(41637, 'Ezekiel 46:4', 'Ezekiel', 46, 4, 'د سبت په ورځ به مشر څښتن ته شپږ وري او یو پسه چې په هغو کې کوم عیب نه وي د سوځېدونکو نذرانو په توګه وړاندې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_004.mp3', NULL, 1761758917, 1761758917),
(41638, 'Ezekiel 46:5', 'Ezekiel', 46, 5, 'هغه به د هر پسه سره لس کیلو‌ګرامه غلې دانې او د هر وري سره به دومره نذرانه چې څومره یې زړه غواړي، وړاندې کړي. د غلو دانو د نذرانو د هرې لس کیلو‌ګرامه نذرانې دپاره به څلور څلور لیتره د زیتونو تېل وړاندې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_005.mp3', NULL, 1761758917, 1761758917),
(41639, 'Ezekiel 46:6', 'Ezekiel', 46, 6, 'د نوې میاشتې په اختر کې به هغه یو خوسی، شپږ وري او یو پسه چې په ټولو کې کوم عیب نه وي، وړاندې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_006.mp3', NULL, 1761758917, 1761758917),
(41640, 'Ezekiel 46:7', 'Ezekiel', 46, 7, 'د هر غویي او هر پسه سره به لس کیلو‌ګرامه غلې دانې او د هر وري سره به دومره نذرانه چې مشر یې ورکولی شي، وړاندې کړي. د غلو دانو د نذرانو د هرې لس کیلو‌ګرامه نذرانې دپاره به څلور څلور لیتره د زیتونو تېل وړاندې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_007.mp3', NULL, 1761758917, 1761758917),
(41641, 'Ezekiel 46:8', 'Ezekiel', 46, 8, 'مشر باید د دروازې د دهلېز د لارې ننوځي او په همدې لاره باید ووځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_008.mp3', NULL, 1761758917, 1761758917),
(41642, 'Ezekiel 46:9', 'Ezekiel', 46, 9, 'کله چې خلک په کوم اختر کې د څښتن د عبادت دپاره راځي، نو څوک چې په شمالي دروازه باندې راننوځي، د عبادت کولو نه وروسته به په جنوبي دروازه باندې وځي او څوک چې په جنوبي دروازه راننوځي، په شمالي دروازه به وځي. په کومه لاره چې څوک ننوتلی وي، په هماغه لاره به نه وځي، بلکې په مخامخ لاره به وځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_009.mp3', NULL, 1761758917, 1761758917),
(41643, 'Ezekiel 46:10', 'Ezekiel', 46, 10, 'کله چې خلک راننوځي، نو مشر به راننوځي او کله چې هغوی لاړ شي، نو مشر به هم ځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_010.mp3', NULL, 1761758917, 1761758917),
(41644, 'Ezekiel 46:11', 'Ezekiel', 46, 11, 'په اخترونو او مذهبي جشنونو کې به د هر خوسي او د هر پسه سره لس کیلو‌ګرامه د غلو دانو نذرانه وړاندې کیږي او د هر وري سره چې عبادت کوونکی څومره غواړي، نو هغومره نذرانه به وړاندې کوي. د غلو دانو د نذرانو د هرې لس کیلو‌ګرامه نذرانې دپاره به څلور څلور لیتره د زیتونو تېل وړاندې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_011.mp3', NULL, 1761758917, 1761758917),
(41645, 'Ezekiel 46:12', 'Ezekiel', 46, 12, 'کله چې مشر وغواړي چې څښتن ته د خپلې خوښې نذرانه وړاندې کړي، که هغه سوځېدونکې نذرانه وي یا د سلامتۍ نذرانه وي، نو د هغه دپاره دې د دنننۍ حوېلۍ ختیځه دروازه خلاصه شي. بیا به هغه وکولای شي خپلې نذرانې وړاندې کړي، لکه څنګه چې یې د سبت په ورځ وړاندې کوي او کله چې هغه وځي، نو دروازه دې بېرته وتړل شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_012.mp3', NULL, 1761758917, 1761758917),
(41646, 'Ezekiel 46:13', 'Ezekiel', 46, 13, 'څښتن وایي: «هر سهار باید یو وری چې یو کلن وي او کوم عیب په کې نه وي، د سوځېدونکې نذرانې په توګه دې څښتن ته وړاندې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_013.mp3', NULL, 1761758917, 1761758917),
(41647, 'Ezekiel 46:14', 'Ezekiel', 46, 14, 'همدارنګه هره ورځ سهار دې د دوه کیلو‌ګرامه اوړو نذرانه چې یو لیتر د زیتونو تېل ورسره ګډ وي، وړاندې شي. څښتن ته د دې نذرانې وړاندې کولو قوانین به تلپاتې قوانین وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_014.mp3', NULL, 1761758917, 1761758917),
(41648, 'Ezekiel 46:15', 'Ezekiel', 46, 15, 'وری، اوړه او د زیتونو تېل باید د تل دپاره هره ورځ سهار څښتن ته د سوځېدونکې نذرانې په توګه وړاندې شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_015.mp3', NULL, 1761758917, 1761758917),
(41649, 'Ezekiel 46:16', 'Ezekiel', 46, 16, 'څښتن تعالی داسې وایي: «که چېرې مشر د خپلې ځمکې نه یو څه ځمکه په خپلو زامنو کې یو زوی ته د سوغات په توګه ورکړي، نو دا ځمکه به د هغه د کورنۍ په جایداد کې د همدې زوی برخه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_016.mp3', NULL, 1761758917, 1761758917),
(41650, 'Ezekiel 46:17', 'Ezekiel', 46, 17, 'خو که چېرې مشر د خپلې ځمکې نه څه ځمکه د خپلو خدمتګارانو څخه کوم یو ته ورکړي، نو دا ځمکه به د ازادۍ د ورکولو تر کاله پورې د هغه سره وي او بیا به دا ځمکه بېرته مشر ته ورکول کیږي. یوازې هغه او د هغه زامن کولای شي چې د هغې ځمکې تلپاتې خاوندان اوسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_017.mp3', NULL, 1761758917, 1761758917),
(41651, 'Ezekiel 46:18', 'Ezekiel', 46, 18, 'مشر باید د خلکو نه د هغوی جایداد په زور وانخلي. هغه چې خپلو زامنو ته کومه ځمکه ورکوي، نو باید د خپلې ځمکې نه یې ورکړي، ترڅو زما د قوم څخه هیڅوک هم د خپلې ځمکې څخه ونه ویستل شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_018.mp3', NULL, 1761758917, 1761758917),
(41652, 'Ezekiel 46:19', 'Ezekiel', 46, 19, 'بیا هغه سړي زه د ننوتلو د لارې نه چې د شمالي دروازې په څنګ کې وه، د کاهنانو هغو سپېڅلو کوټو ته چې شمال خواته مخامخ وې، بوتلم. هلته یې ماته د دې کوټو د لوېدیځې برخې په پای کې یو ځای وښود', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_019.mp3', NULL, 1761758917, 1761758917),
(41653, 'Ezekiel 46:20', 'Ezekiel', 46, 20, 'او هغه ماته وویل: «دا هغه ځای دی چې کاهنان دې په کې د تاوان او د ګناه د نذرانو غوښه وایشوي او د اوړو نذرانې دې پخې کړي، ترڅو هېڅ کوم سپېڅلی شی باندینۍ حوېلۍ ته یونه وړل شي چې خلکو ته زیان ورسوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_020.mp3', NULL, 1761758917, 1761758917),
(41654, 'Ezekiel 46:23', 'Ezekiel', 46, 23, 'دننه د هر یو ګردچاپېره د تیږو دېوال ؤ، د دې دېوال څنګ ته نغري جوړ شوي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_023.mp3', NULL, 1761758917, 1761758917),
(41655, 'Ezekiel 46:24', 'Ezekiel', 46, 24, 'هغه سړي ماته وویل: «دا هغه پخلنځایونه دي چې د څښتن د کور خدمتګاران دې په کې د قربانیو غوښې چې خلک یې راوړي، وایشوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel46_verse_024.mp3', NULL, 1761758917, 1761758917),
(41656, 'Ecclesiastes 7:1', 'Ecclesiastes', 7, 1, 'له قیمتي عطرو نه نېک نامي غوره ده او د زېږېدو له ورځې نه د مړینې ورځ بهتره ده', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_001.mp3', NULL, 1761758917, 1761758917),
(41657, 'Ecclesiastes 7:2', 'Ecclesiastes', 7, 2, 'محفلونو ته له تګ نه جنازو ته تګ غوره دی ځکه د هر انسان د ژوند پای مرګ دی او ژوندي خلک باید دا په زړه کې وساتي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_002.mp3', NULL, 1761758917, 1761758917),
(41658, 'Ecclesiastes 7:3', 'Ecclesiastes', 7, 3, 'له خندا نه ژړا ښه ده ځکه د مخ په خفګان سره زړه صفا کیږي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_003.mp3', NULL, 1761758917, 1761758917),
(41659, 'Ecclesiastes 7:4', 'Ecclesiastes', 7, 4, 'د هوښیارانو زړه د جنازو په لور ځي خو د کم‌عقلانو زړه د خوشحالیو په لور ځي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_004.mp3', NULL, 1761758917, 1761758917),
(41660, 'Ecclesiastes 7:5', 'Ecclesiastes', 7, 5, 'ښه ده چې سړی د هوښیارانو د ملامتۍ خبرې واوري له دې نه چې د کم‌عقلانو د خوشحالۍ سندرې واوري', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_005.mp3', NULL, 1761758917, 1761758917),
(41661, 'Ecclesiastes 7:6', 'Ecclesiastes', 7, 6, 'ځکه چې د کم‌عقلانو خندا د اغزو د کړسهار په څېر دی چې د دېګي لاندې سوځي نو دا حالت هم لوګی او پوکی دی.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_006.mp3', NULL, 1761758917, 1761758917),
(41662, 'Ecclesiastes 7:7', 'Ecclesiastes', 7, 7, 'په حقیقت کې ظلم له هوښیار سړي نه جاهل جوړوي او رشوت د سړي زړه خرابوي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_007.mp3', NULL, 1761758917, 1761758917),
(41663, 'Ecclesiastes 7:8', 'Ecclesiastes', 7, 8, 'د یو کار له پیل نه د هغه پای غوره دی له غرور نه صبر غوره دی', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_008.mp3', NULL, 1761758917, 1761758917),
(41664, 'Ecclesiastes 7:9', 'Ecclesiastes', 7, 9, 'زر مه په غوسه کېږه ځکه غوسه د کم‌عقل په زړه کې ځای نیسي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_009.mp3', NULL, 1761758917, 1761758917),
(41665, 'Ecclesiastes 7:10', 'Ecclesiastes', 7, 10, 'داسې مه وایه: «ولې پخواني وختونه له اوسني وختونو ښه وو؟» ځکه داسې ویل د هوښیارۍ خبره نه ده', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_010.mp3', NULL, 1761758917, 1761758917),
(41666, 'Ecclesiastes 7:11', 'Ecclesiastes', 7, 11, 'حکمت انسان ته چې د لمر د روښنایۍ لاندې اوسیږي د یو میراث په شان ښه او ګټور دی', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_011.mp3', NULL, 1761758917, 1761758917),
(41667, 'Ecclesiastes 7:12', 'Ecclesiastes', 7, 12, 'ځکه حکمت د انسان پر سر سیوری دی لکه څنګه چې پیسې د هغه پر سر سیوری دی خو د حکمت د پېژندلو ګټه دا ده چې د خپل خاوند د ژوند ساتنه کوي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_012.mp3', NULL, 1761758917, 1761758917),
(41668, 'Ecclesiastes 7:13', 'Ecclesiastes', 7, 13, 'د خدای کار ته په غور سره پام وکړه: څوک هغه شی سمولی شي چې خدای کوږ کړی دی؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_013.mp3', NULL, 1761758917, 1761758917),
(41669, 'Ecclesiastes 7:14', 'Ecclesiastes', 7, 14, 'د نېکمرغۍ په وخت کې خوشحالي وکړه خو د بدمرغۍ په وخت کې دې ته پام وکړه: چې نېکمرغي او بدمرغي دواړه د خدای له خوا دي ترڅو راتلونکې پېښې له انسان نه پټې وساتي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_014.mp3', NULL, 1761758917, 1761758917),
(41670, 'Ecclesiastes 7:15', 'Ecclesiastes', 7, 15, 'ما دا دوه شیان د خپل لوګي او پوکي په شان ژوند په موده کې لیدلي دي: هغه نېکان چې د خپل صداقت سره سره بیاهم له وخت نه وړاندې مړه کیږي او هغه بدکاران چې د خپل شرارت سره سره بیاهم اوږد ژوند کوي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_015.mp3', NULL, 1761758917, 1761758917),
(41671, 'Ecclesiastes 7:16', 'Ecclesiastes', 7, 16, 'نه ډېر نېک او صادق اوسه او نه هم ځان ډېر پوه او هوښیار وښایه هسې نه چې ځان برباد کړې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_016.mp3', NULL, 1761758917, 1761758917),
(41672, 'Ecclesiastes 7:17', 'Ecclesiastes', 7, 17, 'نه ځان بدکارۍ ته تسلیم کړه او نه هم کم عقل اوسه هسې نه چې د خپل ټاکلي وخت نه وړاندې مړ شې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_017.mp3', NULL, 1761758917, 1761758917),
(41673, 'Ecclesiastes 7:18', 'Ecclesiastes', 7, 18, 'څومره ښه ده چې له هغو دواړو نه یو خبرداری په پام کې ونیسې خو هغه بل هم له پامه ونه غورځوې ځکه څوک چې له خدایه وېریږي نو هغه دواړه له پامه نه غورځوي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_018.mp3', NULL, 1761758917, 1761758917),
(41674, 'Ecclesiastes 7:19', 'Ecclesiastes', 7, 19, 'حکمت یو پوه او هوښیار سړي ته د ښار له لسو مشرانو څخه زیات واک او اختیار ورکوي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_019.mp3', NULL, 1761758917, 1761758917),
(41675, 'Ecclesiastes 7:20', 'Ecclesiastes', 7, 20, 'په حقیقت کې، هېڅوک په نړۍ کې داسې صادق نه دی چې تل نېک کار وکړي او هېڅکله بدي ونه کړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_020.mp3', NULL, 1761758917, 1761758917),
(41676, 'Ecclesiastes 7:21', 'Ecclesiastes', 7, 21, 'نو خلک چې څه وایي هغه په زړه کې مه نیسه، هسې نه چې ته د خپل غلام هغه ښکنځلې واورې چې تا پسې یې کوي،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_021.mp3', NULL, 1761758917, 1761758917),
(41677, 'Ecclesiastes 7:22', 'Ecclesiastes', 7, 22, 'ځکه ته په خپل زړه کې ښه پوهېږې چې تا هم ډېر ځلې نورو ته ښکنځلې کړي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_022.mp3', NULL, 1761758917, 1761758917),
(41678, 'Ecclesiastes 7:23', 'Ecclesiastes', 7, 23, 'دا ټول شیان ما په خپل حکمت سره وازمایل. نو له ځان سره مې وویل: «راځه په دې شیانو باندې هم ځان پوه کړم،» خو دا زما له پوهې نه بهر ؤ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_023.mp3', NULL, 1761758917, 1761758917),
(41679, 'Ecclesiastes 7:24', 'Ecclesiastes', 7, 24, 'هرڅه چې اوس موجود دي هغه د انسان له پوهې نه بهر او د هغې پوهېدل ډېر ژور دی. انسان د ژوند دا پټ راز څنګه پیدا کولای شي؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_024.mp3', NULL, 1761758917, 1761758917),
(41680, 'Ecclesiastes 7:25', 'Ecclesiastes', 7, 25, 'نو بیا ما په دې اړه فکر وکړ ترڅو په هرڅه باندې ځان پوه کړم، هغه وڅېړم او حکمت او د ژوند پټ راز پیدا کړم. همدا شان ما دا هڅه هم وکړه چې په دې ځان پوه کړم چې بدکاري څومره کم‌عقلتوب او حماقت څومره جهالت دی.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_025.mp3', NULL, 1761758917, 1761758917),
(41681, 'Ecclesiastes 7:26', 'Ecclesiastes', 7, 26, 'نو یو وار بیا پوه شوم چې هغه ښځه له مرګ څخه ډېره ترخه ده کومه چې د زړه نیت یې د ښکاري د دام او لاسونه یې د زندان د زنځیرونو په څېر دي. هرڅوک چې خدای راضي او خوشحاله کړي، نو له هغې څخه ځان ژغوري، خو ګناهکار د هغې په دام کې رانښلي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_026.mp3', NULL, 1761758917, 1761758917),
(41682, 'Ecclesiastes 7:27', 'Ecclesiastes', 7, 27, 'نو څېړونکي وویل: «وګوره، زه د ژوند د پټ راز د څېړنو په موده کې ورو ورو دې نتیجې ته ورسېدم،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_027.mp3', NULL, 1761758917, 1761758917),
(41683, 'Ecclesiastes 7:28', 'Ecclesiastes', 7, 28, 'چې دغه پټ راز چې زما زړه په وار وار غوښتل هغه پیدا کړي، تر‌اوسه نه دی پیدا شوی. ما د زرو کسانو په منځ کې یوازې یو نېک سړی پیدا کړی دی او د دې ټولو په منځ کې مې حتی یوه نېکه ښځه هم پیدا نه کړه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_028.mp3', NULL, 1761758917, 1761758917),
(41684, 'Ecclesiastes 7:29', 'Ecclesiastes', 7, 29, 'نو ما یوازې دا حقیقت پیدا کړ چې خدای انسان نېک پیدا کړی دی خو هغه د ډېرو نورو نقشو په لټه کې دی.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes7_verse_029.mp3', NULL, 1761758917, 1761758917),
(41685, 'Isaiah 28:1', 'Isaiah', 28, 1, 'افسوس د سامرې د ښار په حال! ځکه چې د اسراییلو د نشه یي مشرانو د پرتمین تاج په شان دی. هغه د یوې حاصلخېزې درې په سر پروت دی، خو ښایست به یې لکه د ګلانو په شان مړاوی شي. دا د هغو خلکو دپاره ویاړ دی چې په شرابو نشه کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_001.mp3', NULL, 1761758917, 1761758917),
(41686, 'Isaiah 28:2', 'Isaiah', 28, 2, 'ګورئ، څښتن داسې زورور کسان لري چې حملې ته تیار دي، دا کسان به د یو زورور توفان، ږلۍ، باران او سېلاب په شان راشي او ښار به تباه او له منځه لاړ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_002.mp3', NULL, 1761758917, 1761758917),
(41687, 'Isaiah 28:3', 'Isaiah', 28, 3, 'بیا به سامره چې د نشه یي مشرانو غرور او د یو پرتمین تاج په شان دی، تر پښو لاندې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_003.mp3', NULL, 1761758917, 1761758917),
(41688, 'Isaiah 28:4', 'Isaiah', 28, 4, 'بیا د دې مړاوي کېدونکي ګل ښکلا به چې د یوې حاصلخېزې درې په سر کې دی، داسې له منځه لاړه شي لکه د انځرو د لومړنۍ مېوې په شان چې څنګه پخه شي، وشکول شي او وخوړل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_004.mp3', NULL, 1761758917, 1761758917),
(41689, 'Isaiah 28:5', 'Isaiah', 28, 5, 'په هغه ورځ به مطلق قادر څښتن د خپلو ژوندي پاتې شویو خلکو دپاره لکه د یو پرتمین تاج په شان وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_005.mp3', NULL, 1761758917, 1761758917),
(41690, 'Isaiah 28:6', 'Isaiah', 28, 6, 'څښتن به هغو کسانو ته چې د قاضیانو په توګه دنده لري د عدالت او انصاف وس او توان ورکړي او هغو کسانو ته چې د حملې په وخت کې د ښار له دروازو ساتنه کوي، زړورتیا ورکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_006.mp3', NULL, 1761758917, 1761758917),
(41691, 'Isaiah 28:7', 'Isaiah', 28, 7, 'حتی تر دې پورې چې کاهنان او نبیان هم دومره نشه دي او دومره ډېر شراب یې څښلي چې په لاره کاږه واږه روان دي. نبیان په هغه رویاګانو نه پوهیږي چې څښتن ورته رالېږلي او هم کاهنان د قضاوت کولو په وخت کې زنګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_007.mp3', NULL, 1761758917, 1761758917),
(41692, 'Isaiah 28:8', 'Isaiah', 28, 8, 'د هغوی دسترخوان د کانګو او چټلیو څخه ډک دي او هېڅ یو پاک ځای په کې نه لیدل کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_008.mp3', NULL, 1761758917, 1761758917),
(41693, 'Isaiah 28:9', 'Isaiah', 28, 9, 'هغوی زما نه شکایت کوي او وایي: «دا سړی چې مونږ ته زده کړه راکوي، څوک دی؟ د هغه پیغام ته څوک اړ دی؟ د هغه تعلیم او پیغام یوازې د هغو ماشومانو دپاره ښه دي چې همدا اوس له تي نه بېل شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_009.mp3', NULL, 1761758917, 1761758917),
(41694, 'Isaiah 28:10', 'Isaiah', 28, 10, 'په رښتیا هغه تش د بې معنی لغتونو اواز وباسي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_010.mp3', NULL, 1761758917, 1761758917),
(41695, 'Isaiah 28:11', 'Isaiah', 28, 11, 'ګورئ، که تاسو زما خبرو ته غوږ ونه نیسئ، نو څښتن به د پردیو خلکو په وسیله په عجیبه ژبه له تاسو سره خبرې وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_011.mp3', NULL, 1761758917, 1761758917),
(41696, 'Isaiah 28:12', 'Isaiah', 28, 12, 'څښتن غوښتل چې تاسو ستړو ته ارامي درکړي، خو تاسو د هغه د منلو څخه ډډه وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_012.mp3', NULL, 1761758917, 1761758917),
(41697, 'Isaiah 28:13', 'Isaiah', 28, 13, 'نو له دې امله به تاسو ته د څښتن کلام لکه د بې معنی لغتونو د اواز په شان وي. نو هغه وخت چې هر قدم اخلئ، وبه ښويېږئ. تاسو به ټپیان شئ، په دام کې به راګېر شئ او اسیران به شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_013.mp3', NULL, 1761758917, 1761758917),
(41698, 'Isaiah 28:14', 'Isaiah', 28, 14, 'ای د اورشلیم ملنډې وهونکو حاکمانو، د څښتن کلام ته پاملرنه وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_014.mp3', NULL, 1761758917, 1761758917),
(41699, 'Isaiah 28:15', 'Isaiah', 28, 15, 'تاسو وایئ چې له مرګ سره مو تړون کړی دی او د مړو له دنیا سره مو لاس یو کړی دی. تاسو ډاډه یئ چې کله په تاسو باندې د سیلاب په شان مصیبت راشي نو تاسو به بچ شئ، ځکه چې تاسو فکر کوئ چې کولای شئ په ټګۍ او دروغو ځان خوندي وساتئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_015.mp3', NULL, 1761758917, 1761758917),
(41700, 'Isaiah 28:16', 'Isaiah', 28, 16, 'نو په دې خاطر دا هغه څه دي چې څښتن تعالی یې وایي: «زه د صهیون بنیاد په یوې غوره، ازمایل شوې او قیمتي تیږه ږدم. نو په هغه باندې به دا ټکي لیکل شوي وي: ‹هرڅوک چې ایمان راوړي، هغه نه وارخطا کیږي.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_016.mp3', NULL, 1761758917, 1761758917),
(41701, 'Isaiah 28:17', 'Isaiah', 28, 17, 'انصاف به د هغه بنیاد دپاره د اندازه کولو رسۍ وي او صداقت به د هغه شاقول وي.» توفان او ږلۍ به ستاسو د پناه ځایونه چې د دروغو په بنیاد ایښودل شوي دي، وران کړي او سېلابونه به هغه له منځه یوسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_017.mp3', NULL, 1761758917, 1761758917),
(41702, 'Isaiah 28:18', 'Isaiah', 28, 18, 'هغه تړون چې تاسو له مرګ سره کړی ؤ هغه به ړنګ شي او د مړو له دنیا سره مو چې لاس یو کړی دی هغه به باطل شي. کله چې په تاسو باندې د سیلاب په شان مصیبت راشي، نو تاسو به د پښو لاندې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_018.mp3', NULL, 1761758917, 1761758917),
(41703, 'Isaiah 28:19', 'Isaiah', 28, 19, 'هغه مصیبت به په ورځ یا شپه او یا هرکله چې راشي، هغه به ونه شئ زغملای. که چېرې په دې پیغام باندې پوه شئ، تاسو ته به ډېره وېره پیدا شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_019.mp3', NULL, 1761758917, 1761758917),
(41704, 'Isaiah 28:20', 'Isaiah', 28, 20, 'تاسو به د هغه کس په شان یئ چې په دې متل کې یاد شوی دی: «د هغه کټ دومره لنډ ؤ چې پښې یې په کې نه شواې غزولی او کمپله یې هم دومره لنډه وه چې ځان یې په کې نه شو پټولی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_020.mp3', NULL, 1761758917, 1761758917),
(41705, 'Isaiah 28:21', 'Isaiah', 28, 21, 'څښتن به په قهر راپاڅیږي او جګړه به وکړي، لکه څنګه چې یې د فراسیم په غره او د جبعون په دره کې کړې وه. نو هغه به عجیبه او غیر عادي کارونه سرته ورسوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_021.mp3', NULL, 1761758917, 1761758917),
(41706, 'Isaiah 28:22', 'Isaiah', 28, 22, 'نو بیا زه چې تاسو ته کوم خبرداری درکوم په هغه باندې ملنډې مه وهئ. که ملنډې مو ووهلې، نو خلاصېدل به درته ډېر ګران شي. ځکه ما د مطلق قادر څښتن خدای پرېکړه واورېدله چې هغه به ټول وطن وران کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_022.mp3', NULL, 1761758917, 1761758917),
(41707, 'Isaiah 28:23', 'Isaiah', 28, 23, 'واورئ، ماته غوږ ونیسئ او زما خبرو ته پام وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_023.mp3', NULL, 1761758917, 1761758917),
(41708, 'Isaiah 28:24', 'Isaiah', 28, 24, 'هېڅ بزګر په خپلو پټیو کې په پرله پسې توګه قلبه نه کوي او نه یې د کرلو دپاره هواروي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_024.mp3', NULL, 1761758917, 1761758917),
(41709, 'Isaiah 28:25', 'Isaiah', 28, 25, 'خو کله چې هغه ځمکه د کرلو دپاره تیاره شوه، په دې وخت کې په ځمکه کې تخمونه کري. هغه پوهیږي چې د بوټو تخمونه لکه شبت او ځيره چېرته وشیندل شي، د غنمو او اوربشو تخمونه په قطارونو کې او د غلو دانو نور تخمونه د پټیو په څنډه کې وکرل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_025.mp3', NULL, 1761758917, 1761758917),
(41710, 'Isaiah 28:26', 'Isaiah', 28, 26, 'بزګر په خپله دنده پوهیږي، ځکه چې د هغه خدای ورته سمه لارښودنه کړې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_026.mp3', NULL, 1761758917, 1761758917),
(41711, 'Isaiah 28:27', 'Isaiah', 28, 27, 'هغه د شبت او ځيرې د تخمونو د ټکولو دپاره د درمند ټکولو څپر نه کار نه اخلي بلکې د لرګیو نه کار اخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_027.mp3', NULL, 1761758917, 1761758917),
(41712, 'Isaiah 28:28', 'Isaiah', 28, 28, 'هغه د غنمو د درمند په غوبل کولو پوهیږي چې تر کومه وخته هغه غوبل شي چې غنمو ته زیان ونه رسیږي. هغه د اسونو د ګاډۍ څخه کار اخلي ترڅو وکولای شي د ګاډۍ په ارابو باندې د غنمو درمند ښه غوبل کړي چې غلې دانې خرابې نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_028.mp3', NULL, 1761758917, 1761758917),
(41713, 'Isaiah 28:29', 'Isaiah', 28, 29, 'دا هرڅه مطلق قادر څښتن هغه ته ورزده کوي، ځکه چې د هغه نقشې ډېرې لوړې او د حکمت څخه ډکې دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah28_verse_029.mp3', NULL, 1761758917, 1761758917),
(41714, 'Ezekiel 5:1', 'Ezekiel', 5, 1, 'څښتن وویل: «ای فاني انسانه، یوه تېره توره راواخله او د هغې نه د دلاکۍ د چاړې په ځای کار واخله او خپل سر او ږیره ورباندې وخرایه. بیا هغه ویښتان په ترازو کې وتله او په درېو برخو یې ووېشه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_001.mp3', NULL, 1761758917, 1761758917),
(41715, 'Ezekiel 5:2', 'Ezekiel', 5, 2, 'کله چې د هغې کلابندۍ وخت چې ته یې وړاندې کوې پای ته ورسېدله، نو د هغو ویښتانو یوه برخه په ښار کې وسوځوه. بله برخه یې راواخله او په خپله توره يې ټوټې ټوټې کړه او د ښار ګردچاپېره يې وشینده. درېمه برخه یې د باد مخې ته وشینده او زه به هغه په خپلې تورې سره تعقیب کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_002.mp3', NULL, 1761758917, 1761758917),
(41716, 'Ezekiel 5:3', 'Ezekiel', 5, 3, 'بیا لږ ویښتان راواخله او د خپلو کالیو په لمنه کې یې پټ کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_003.mp3', NULL, 1761758917, 1761758917),
(41717, 'Ezekiel 5:4', 'Ezekiel', 5, 4, 'له هغو ویښتانو نه بیا لږ څه واخله، په اور کې یې واچوه او ویې سوځوه. دا اور به د اسراییلو ټول قوم ته خپور شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_004.mp3', NULL, 1761758917, 1761758917),
(41718, 'Ezekiel 5:5', 'Ezekiel', 5, 5, '«زه څښتن تعالی داسې وایم: ‹دا اورشلیم دی. ما هغه د قومونو په منځ کې ځای په ځای کړی او نور هېوادونه ورڅخه ګردچاپېره پراته دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_005.mp3', NULL, 1761758917, 1761758917),
(41719, 'Ezekiel 5:6', 'Ezekiel', 5, 6, 'خو د اورشلیم خلکو زما د حکمونو نه سرکښي وکړه او دا یې وښودله چې هغوی د نورو قومونو نه ډېر بدکاره دي او د خپل شاوخوا هېوادونو نه ډېر نافرمانه دي. هغوی زما حکمونه رد کړي دي او زما د قوانینو څخه یې اطاعت نه دی کړی.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_006.mp3', NULL, 1761758917, 1761758917),
(41720, 'Ezekiel 5:7', 'Ezekiel', 5, 7, 'نو له دې امله څښتن تعالی داسې وایي: ‹تاسو خلکو د نورو قومونو څخه زیاته سرکښي کړې ده او زما د حکمونو او قوانینو څخه مو انکار کړی دی. تاسو حتی د خپل شاوخوا هېوادونو د معیارونو سره سم ژوند نه دی کړی.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_007.mp3', NULL, 1761758917, 1761758917),
(41721, 'Ezekiel 5:8', 'Ezekiel', 5, 8, 'نو ځکه زه څښتن تعالی تاته داسې وایم چې ګوره ای اورشلیمه، زه په خپله ستا دښمن یم. زه به د ټولو قومونو په حضور کې تاته سزا درکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_008.mp3', NULL, 1761758917, 1761758917),
(41722, 'Ezekiel 5:9', 'Ezekiel', 5, 9, 'نو د هغو بدو کارونو له امله چې ستا خلکو کړي دي او زه ورڅخه کرکه کوم، زه به تا ته داسې سزا درکړم چې له دې نه مخکې مې چاته نه ده ورکړې او نه به یې له دې وروسته ورکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_009.mp3', NULL, 1761758917, 1761758917),
(41723, 'Ezekiel 5:10', 'Ezekiel', 5, 10, 'نو نتیجه به یې دا شي چې په اورشلیم کې به میندې او پلرونه خپل اولادونه او اولادونه به خپل میندې او پلرونه وخوري. زه به ستا خلکو ته سزا ورکړم او څوک چې ژوندي پاتې شي هغوی به هرې خواته خواره واره کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_010.mp3', NULL, 1761758917, 1761758917),
(41724, 'Ezekiel 5:11', 'Ezekiel', 5, 11, 'نو له دې امله زه څښتن تعالی داسې وایم: ‹زه په خپل ذات باندې قسم خورم، څرنګه چې تاسو په خپلو د کرکې وړ بتانو او کارونو سره زما د عبادت ځای ناپاک کړی دی، نو زه به هم تاسو په بې‌رحمۍ سره له منځه یوسم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_011.mp3', NULL, 1761758917, 1761758917),
(41725, 'Ezekiel 5:12', 'Ezekiel', 5, 12, 'ستا د خلکو یوه برخه به په ښار کې د وبا او قحطۍ له لاسه مړه شي، بله برخه به دې د ښار څخه دباندې په تورو باندې ووژل شي او درېمه برخه به دې هرې خواته خواره واره کړم او زه به هغه په خپلې تورې سره تعقیب کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_012.mp3', NULL, 1761758917, 1761758917),
(41726, 'Ezekiel 5:13', 'Ezekiel', 5, 13, 'داسې به زما د غضب اور مړ شي او ستا د خلکو په وړاندې به زما قهر سوړ شي. کله چې دا پېښې رامنځته شي، نو ستا خلک به پوه شي چې ما څښتن د هغوی سره خبرې کړې وې او زه د خپل غیرت له امله په قهر شوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_013.mp3', NULL, 1761758917, 1761758917),
(41727, 'Ezekiel 5:14', 'Ezekiel', 5, 14, 'پرته له دې به تا د شاوخوا قومونو په منځ کې او د هرچا په سترګو کې چې له دې ځای څخه تېریږي، وران او رسوا کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_014.mp3', NULL, 1761758917, 1761758917),
(41728, 'Ezekiel 5:15', 'Ezekiel', 5, 15, 'کله چې زه په قهر او غضب کې تاته سزا درکړم، نو له دې امله به ستا شاوخوا ټول قومونه ووېریږي او هغوی ته به عبرت وي. هغوی به تاته په سپکه سترګه ګوري او ملنډې به درباندې وهي.› دا ما څښتن ویلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_015.mp3', NULL, 1761758917, 1761758917),
(41729, 'Ezekiel 5:16', 'Ezekiel', 5, 16, 'زه به په تاسو باندې د قحطۍ وژونکي تیرونه درګوزار کړم چې تاسو تباه کړي. قحطي به دومره سخته شي چې ستا خلک به د خوړو د نشتوالي سره مخ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_016.mp3', NULL, 1761758917, 1761758917),
(41730, 'Ezekiel 5:17', 'Ezekiel', 5, 17, 'زه به ستا په خلکو باندې قحطي نازله کړم او وحشي حیوانات به درولېږم، ترڅو تا او ستا اولادونه له منځه یوسي. وبا او وینه تویول به په تا باندې راشي او خلک به د دښمن په توره ووژل شي. دا زما یعنې د څښتن وینا ده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel5_verse_017.mp3', NULL, 1761758917, 1761758917),
(41731, 'Nehemiah 10:1', 'Nehemiah', 10, 1, 'لومړنی کس چې مهر یې ولګاوه هغه والي یعنې نحمیا د حکلیا زوی ؤ او بیا صدقیا مهر ولګاوه. لاندې خلکو هم مهرونه ولګول:', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_001.mp3', NULL, 1761758917, 1761758917),
(41732, 'Nehemiah 10:28', 'Nehemiah', 10, 28, 'مونږ د اسراییلو نورو خلکو، کاهنانو، لاویانو، د خدای د کور ساتونکو، سندرغاړو، خدمتګارانو او نورو ټولو هغو خلکو چې د خدای د شریعت څخه اطاعت کوي، خپل ځانونه د هغو پردیو قومونو څخه چې زمونږ په خاوره کې اوسیږي، بېل کړل. مونږ د خپلو ښځو او خپلو ټولو هغو زامنو او لورګانو سره چې په دې لوظ پوهیږي،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_028.mp3', NULL, 1761758917, 1761758917),
(41733, 'Nehemiah 10:29', 'Nehemiah', 10, 29, 'د خپلو مشرانو سره په دې قسم کې یوځای کېږو چې مونږ به د خدای د شریعت سره سم چې خدای د خپل خدمتګار موسی په وسیله راکړی دی خپل ژوند تېروو. مونږ به د خپل څښتن په ټولو حکمونو، قوانینو او شرطونو باندې عمل او د هغو اطاعت به کوو. که چېرې مونږ هغه مات کړو، نو د خدای لعنت دې په مونږ باندې وي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_029.mp3', NULL, 1761758917, 1761758917),
(41734, 'Nehemiah 10:30', 'Nehemiah', 10, 30, 'مونږ دا لوظ کوو چې مونږ به خپلې لورګانې د غیریهودیانو زامنو ته نه ورکوو او نه به پرېږدو چې زمونږ زامن د غیریهودیانو د لورګانو سره ودونه وکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_030.mp3', NULL, 1761758917, 1761758917),
(41735, 'Nehemiah 10:31', 'Nehemiah', 10, 31, 'که چېرې پردي خلک غلې دانې یا کوم بل شی راوړي چې په مونږ باندې یې د سبت یا په کومه بله سپېڅلې ورځ خرڅ کړي، مونږ به یې ورڅخه وانخلو. په هر اووم کال به په ځمکه کې کرنه نه کوو او خپل ټول پورونه به وبخښو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_031.mp3', NULL, 1761758917, 1761758917),
(41736, 'Nehemiah 10:32', 'Nehemiah', 10, 32, 'مونږ مسوولیت لرو چې هر کال به د مثقال درېمه برخه سپین زر د خپل خدای د کور د لګښت دپاره ورکړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_032.mp3', NULL, 1761758917, 1761758917),
(41737, 'Nehemiah 10:33', 'Nehemiah', 10, 33, 'مونږ به د خدای په کور کې د عبادت دپاره دا شیان تیار کړو: سپېڅلې ډوډۍ، د غلو دانو ورځنۍ نذرانه، هغه څاروي چې د قربانیو په توګه هره ورځ سوځول کیږي، د سبت، د نوې میاشتې د اخترونو او نورو اخترونو دپاره سپېڅلې نذرانې، نورې سپېڅلې نذرانې، د اسراییلو د ګناهونو د کفارې نذرانې او نور شیان چې د خدای د کور دپاره ورته اړتیا ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_033.mp3', NULL, 1761758917, 1761758917),
(41738, 'Nehemiah 10:34', 'Nehemiah', 10, 34, 'مونږ یعنې کاهنان او لاویان او زمونږ خلک به هر کال پچه اچوو چې دا څرګنده شي چې کومې طایفې به په ټاکلي وخت زمونږ د خدای کور ته لرګي راوړي، ترڅو د شریعت د شرطونو سره سم هغه سوځېدونکې قربانۍ ورباندې وسوځول شي چې زمونږ څښتن خدای ته وړاندې کیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_034.mp3', NULL, 1761758917, 1761758917),
(41739, 'Nehemiah 10:35', 'Nehemiah', 10, 35, 'مونږ مسوولیت لرو چې هر کال د څښتن کور ته د لومړنیو غلو دانو او د هرې ونې لومړنۍ مېوې د نذرانې په توګه راوړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_035.mp3', NULL, 1761758917, 1761758917),
(41740, 'Nehemiah 10:36', 'Nehemiah', 10, 36, 'لکه څنګه چې په شریعت کې لیکل شوي دي، مونږ به د خپلو زامنو، غواګانو، وزو او مېږو څخه هر لومړنی زېږول شوی هغه کاهنانو ته راولو چې د خدای په کور کې خدمت کوي او هغه به خدای ته وقف کوو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_036.mp3', NULL, 1761758917, 1761758917),
(41741, 'Nehemiah 10:37', 'Nehemiah', 10, 37, 'مونږ به د اوړو هغه پېړه چې هر کال د لومړنیو راټولو شویو غلو دانو حاصل څخه تیاره شوې وي او د شرابو، د زیتونو د تېلو او د هر ډول مېوو د حاصل نورې نذرانې هغو کاهنانو ته راوړو چې د خدای په کور کې د ګودامونو مسوولان دي. مونږ به د خپلو ځمکو د حاصلاتو لسمه برخه هغو لاویانو ته چې زمونږ په ښارګوټو کې هغه راټولوي، ورکړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_037.mp3', NULL, 1761758917, 1761758917),
(41742, 'Nehemiah 10:38', 'Nehemiah', 10, 38, 'د لسمې برخې د راټولولو په وخت کې باید هغه کاهنان چې د هارون د اولادې څخه دي د لاویانو سره وي او لاویان دې د راټول شوي عشر، لسمه برخه د خدای د کور ګودامونو ته یوسي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_038.mp3', NULL, 1761758917, 1761758917),
(41743, 'Nehemiah 10:39', 'Nehemiah', 10, 39, 'د اسراییلو خلک او لاویان باید د غلو دانو، شرابو او د زیتونو د تېلو اعانې هغو ګودامونو ته راوړي په کومو کې چې د خدای د کور لوښي ساتل کیږي او کاهنان چې خدمت کوي، د خدای د کور ساتونکي او سندرغاړي هلته اوسیږي. مونږ به د خدای د کور په اړه بې پروایي ونه کړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah10_verse_039.mp3', NULL, 1761758917, 1761758917),
(41744, 'Numbers 4:1', 'Numbers', 4, 1, 'څښتن موسی او هارون ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_001.mp3', NULL, 1761758917, 1761758917),
(41745, 'Numbers 4:2', 'Numbers', 4, 2, '«د قهاتیانو سرشمېرنه چې د لاویانو د قبیلې یوه برخه ده، طایفه په طایفه او کورنۍ په کورنۍ وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_002.mp3', NULL, 1761758917, 1761758917),
(41746, 'Numbers 4:3', 'Numbers', 4, 3, 'هغه ټول کسان وشمېرئ چې عمر یې د دېرشو کالو څخه تر پنځوسو کالو پورې وي او په سپېڅلې خېمه کې د کار کولو توان ولري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_003.mp3', NULL, 1761758917, 1761758917),
(41747, 'Numbers 4:4', 'Numbers', 4, 4, 'په سپېڅلې خېمه کې د قهاتیانو کار دا دی چې په سپېڅلو شیانو باندې پام وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_004.mp3', NULL, 1761758917, 1761758917),
(41748, 'Numbers 4:5', 'Numbers', 4, 5, 'کله چې د دې وخت راشي چې کمپ ته حرکت ورکړای شي، نو هارون او د هغه زامن به خېمې ته ورننوځي، هغه پرده به راښکته کړي چې د لوظ د صندوق په مخکې ده او صندوق به ورباندې پټ کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_005.mp3', NULL, 1761758917, 1761758917),
(41749, 'Numbers 4:6', 'Numbers', 4, 6, 'په هغه باندې به د ښې څرمنې پوښ واچوي او په سر باندې به یې یو داسې ټوکر خپور کړي چې پوخ ابي رنګ ولري او بیا به وړونکې میلې په کې ورننباسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_006.mp3', NULL, 1761758917, 1761758917),
(41750, 'Numbers 4:7', 'Numbers', 4, 7, 'هغوی به په هغه مېز باندې چې خدای ته ورباندې ډوډۍ وړاندې کیږي یو ابي ټوکر خپور کړي او په هغه باندې به قابونه، د خوشبویۍ کاسې، د نذرانې دپاره کاسې او هغه منګي کېږدي چې د څښلو د نذرانو دپاره دي. په مېز باندې به تل ډوډۍ پرته وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_007.mp3', NULL, 1761758917, 1761758917),
(41751, 'Numbers 4:8', 'Numbers', 4, 8, 'هغوی به په دې ټولو باندې یو سور ټوکر خپور کړي، د یوې ښې څرمنې پوښ به ورباندې واچوي او بیا به وړونکې میلې په کې ورننباسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_008.mp3', NULL, 1761758917, 1761758917),
(41752, 'Numbers 4:9', 'Numbers', 4, 9, 'هغوی دې یو ابي ټوکر واخلي او دغه شیان دې ورباندې پټ کړي: څراغدان د څراغونو سره، د هغه پلته پاکوونکي، پتنوسونه او د زیتونو د تېلو ټول لوښي چې د څراغونو دپاره کارول کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_009.mp3', NULL, 1761758917, 1761758917),
(41753, 'Numbers 4:10', 'Numbers', 4, 10, 'هغوی به څراغدان او د هغه ټول سامان د ښې څرمنې په پوښ کې راتاو کړي او په یو وړونکي چوکاټ باندې به یې کېږدي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_010.mp3', NULL, 1761758917, 1761758917),
(41754, 'Numbers 4:11', 'Numbers', 4, 11, 'بیا به د سرو زرو د قربانۍ په ځای باندې یو ابي ټوکر خپور کړي، د ښې څرمنې یو پوښ به ورباندې واچوي او بیا به وړونکې میلې په کې ورننباسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_011.mp3', NULL, 1761758917, 1761758917),
(41755, 'Numbers 4:12', 'Numbers', 4, 12, 'هغوی به هغه ټول لوښي چې په سپېڅلي ځای کې ورڅخه کار اخیستل کیږي واخلي او په یو ابي ټوکر کې به یې تاو کړي، د ښې څرمنې یو پوښ به ورباندې واچوي او په یو وړونکي چوکاټ باندې به یې کېږدي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_012.mp3', NULL, 1761758917, 1761758917),
(41756, 'Numbers 4:13', 'Numbers', 4, 13, 'د قربانۍ د ځای څخه به ایرې لېرې کړي او په هغه باندې به یو بانجاني ټوکر خپور کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_013.mp3', NULL, 1761758917, 1761758917),
(41757, 'Numbers 4:14', 'Numbers', 4, 14, 'په هغه ټوکر باندې دې هغه ټول سامان کېږدي چې د قربانۍ په ځای کې ورڅخه کار اخیستل کیږي: لکه د اور لوښي، د غوښې قاشق پنجې، بېلچې او د وینې د شیندلو کاسې. بیا به هغوی ورباندې د ښې څرمنې یو پوښ واچوي او وړونکې میلې به په کې ورننباسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_014.mp3', NULL, 1761758917, 1761758917),
(41758, 'Numbers 4:15', 'Numbers', 4, 15, 'کله چې هارون او د هغه زامن د سپېڅلي سامان او ټولو سپېڅلو موادو د پټولو څخه وزګار شي او کمپ د وړلو دپاره تیار شي، نو قهاتیان دې د دغو شیانو د وړلو دپاره راشي. خو هغوی باید سپېڅلو شیانو ته لاس ورنه وړي که نه، نو مړه به شي. قهاتیان دې هغه شیان انتقال کړي چې په سپېڅلې خېمه کې دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_015.mp3', NULL, 1761758917, 1761758917),
(41759, 'Numbers 4:16', 'Numbers', 4, 16, 'د هارون کاهن زوی العازار دې د دغو شیانو مسوولیت په غاړه واخلي: د څراغونو دپاره د زیتونو تېل، خوشبویي، د عادي غلې دانې نذرانه او د مسح کولو تېل. هغه دې د ټولې سپېڅلې خېمې او هرڅه چې په کې دي، د سپېڅلي سامان او لوښو په شمول د هغو مسوولیت په غاړه واخلي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_016.mp3', NULL, 1761758917, 1761758917),
(41760, 'Numbers 4:17', 'Numbers', 4, 17, 'څښتن موسی او هارون ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_017.mp3', NULL, 1761758917, 1761758917),
(41761, 'Numbers 4:20', 'Numbers', 4, 20, 'خو قهاتیان باید دننه لاړ نه شي چې سپېڅلي شیان وګوري، حتی د یوې شېبې دپاره هم. که نه، نو مړه به شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_020.mp3', NULL, 1761758917, 1761758917),
(41762, 'Numbers 4:21', 'Numbers', 4, 21, 'څښتن موسی ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_021.mp3', NULL, 1761758917, 1761758917),
(41763, 'Numbers 4:22', 'Numbers', 4, 22, '«د جرشونیانو سرشمېرنه چې د لاویانو د قبیلې یوه برخه ده، کورنۍ په کورنۍ او طایفه په طایفه وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_022.mp3', NULL, 1761758917, 1761758917),
(41764, 'Numbers 4:23', 'Numbers', 4, 23, 'هغه ټول کسان چې عمر یې د دېرشو کالو څخه تر پنځوسو کالو پورې وي او په سپېڅلې خېمه کې د کار کولو توان ولري وشمېره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_023.mp3', NULL, 1761758917, 1761758917),
(41765, 'Numbers 4:24', 'Numbers', 4, 24, 'هغوی به د لاندېنیو شیانو د وړلو مسوولیت په غاړه لري:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_024.mp3', NULL, 1761758917, 1761758917),
(41766, 'Numbers 4:25', 'Numbers', 4, 25, 'خېمه، د هغې داخلي او باندینی پوښ، د هغې په سر باندې د ښې څرمنې پوښ، د دروازې پرده،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_025.mp3', NULL, 1761758917, 1761758917),
(41767, 'Numbers 4:26', 'Numbers', 4, 26, 'د خېمې او د قربانۍ د ځای د ګردچاپېره حوېلۍ دپاره پردې، د حوېلۍ د دروازې پرده، رسۍ ګانې او هرڅه چې د دې شیانو په ودرولو کې په کاریږي. جرشونیان د دې ټولو شیانو د ساتنې او ترتیبولو مسوولیت په غاړه لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_026.mp3', NULL, 1761758917, 1761758917),
(41768, 'Numbers 4:27', 'Numbers', 4, 27, 'ته او هارون به وګورئ چې جرشونیان دا ټول کارونه تر سره کوي او هر هغه شی چې هارون او د هغه زامنو هغوی ته ورسپارلی دی، وړي که نه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_027.mp3', NULL, 1761758917, 1761758917),
(41769, 'Numbers 4:28', 'Numbers', 4, 28, 'دا د سپېڅلې خېمې په کار کې د جرشونیانو دندې دي. هغوی به دا کار د هارون کاهن د زوی یعنې ایتامار تر لارښوونې لاندې تر سره کوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_028.mp3', NULL, 1761758917, 1761758917),
(41770, 'Numbers 4:29', 'Numbers', 4, 29, 'څښتن موسی ته وویل: «مراریان چې د لاویانو د قبیلې یوه برخه ده طایفه په طایفه او کورنۍ په کورنۍ وشمېره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_029.mp3', NULL, 1761758917, 1761758917),
(41771, 'Numbers 4:30', 'Numbers', 4, 30, 'هغه ټول کسان چې عمر یې د دېرشو کالو څخه تر پنځوسو کالو پورې وي او په سپېڅلې خېمه کې د کار کولو توان ولري وشمېره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_030.mp3', NULL, 1761758917, 1761758917),
(41772, 'Numbers 4:31', 'Numbers', 4, 31, 'هغوی به د چوکاټونو، اړمونو، ستنو او خېمې د پایو د وړلو مسوولیت ولري', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_031.mp3', NULL, 1761758917, 1761758917),
(41773, 'Numbers 4:32', 'Numbers', 4, 32, 'او همدارنګه د خېمې د ګردچاپېره حوېلۍ د ستنو، پایو، مېخونو، رسۍ ګانو او هغو ټولو شیانو چې د هغو په ودرولو کې په کاریږي. هر سړی به د ځانګړو شیانو د وړلو مسوولیت په غاړه ولري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_032.mp3', NULL, 1761758917, 1761758917),
(41774, 'Numbers 4:33', 'Numbers', 4, 33, 'دا د سپېڅلې خېمې په کار کې د مراریانو دندې دي. هغوی به دا کار د هارون کاهن د زوی یعنې ایتامار تر لارښوونې لاندې تر سره کوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_033.mp3', NULL, 1761758917, 1761758917),
(41775, 'Numbers 4:49', 'Numbers', 4, 49, 'څنګه چې څښتن موسی ته حکم کړې ؤ، هر سړی وشمېرل شو او هر یو ته د خدمت کولو یا د وړلو د دندې مسوولیت وسپارل شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers4_verse_049.mp3', NULL, 1761758917, 1761758917),
(41776, 'Ezekiel 24:1', 'Ezekiel', 24, 1, 'زمونږ د جلاوطنۍ د نهم کال د لسمې میاشتې په لسمه ورځ څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_001.mp3', NULL, 1761758917, 1761758917),
(41777, 'Ezekiel 24:2', 'Ezekiel', 24, 2, '«ای فاني انسانه، نننۍ نېټه ولیکه. هو همدا ورځ، ځکه چې د بابل پاچا نن ورځ د اورشلیم په کلابند کولو باندې پیل کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_002.mp3', NULL, 1761758917, 1761758917),
(41778, 'Ezekiel 24:3', 'Ezekiel', 24, 3, 'دې سرکښه قوم ته دا مثال ووایه چې زه څښتن تعالی یې هغوی ته بیانوم: ‹دېګی کېږدئ په اور باندې او په کې واچوئ اوبه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_003.mp3', NULL, 1761758917, 1761758917),
(41779, 'Ezekiel 24:4', 'Ezekiel', 24, 4, 'په کې واچوئ د غوښې ښې ټوټې د ورانه او د اوږو غوښه هغه کړئ ډک د ډېرو ښو غوښو نه چې لري هډوکي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_004.mp3', NULL, 1761758917, 1761758917),
(41780, 'Ezekiel 24:5', 'Ezekiel', 24, 5, 'واخلئ رمې نه ډېر ښه پسه کېږدئ لرګي د دېګي لاندې پرېږدئ چې ښه جوش شي اوبه کړئ پاخه غوښه او هډوکي›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_005.mp3', NULL, 1761758917, 1761758917),
(41781, 'Ezekiel 24:6', 'Ezekiel', 24, 6, 'څښتن تعالی داسې وایي: ‹افسوس د خونړي ښار په حال! دا د داسې زنګ وهلي دېګي په شان دی چې هېڅکله نه پاکیږي. ټوټه ټوټه غوښه ورڅخه وباسئ چې یوه ټوټه هم په کې پاتې نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_006.mp3', NULL, 1761758917, 1761758917),
(41782, 'Ezekiel 24:7', 'Ezekiel', 24, 7, 'ځکه د اورشلیم خلکو په ښار کې بې‌ګناه خلک ووژل، خو وینه یې په ځمکې باندې تویه نه شوه چې په خاورو کې پټه شوې وای، هغه په ګټ باندې تویه شوه چې ټول یې وویني.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_007.mp3', NULL, 1761758917, 1761758917),
(41783, 'Ezekiel 24:8', 'Ezekiel', 24, 8, 'د دې دپاره چې زه په قهر شم او بدل واخلم، نو هغه وینه مې په هغه ګټ باندې پرېښودله چې پټه نه شي.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_008.mp3', NULL, 1761758917, 1761758917),
(41784, 'Ezekiel 24:9', 'Ezekiel', 24, 9, 'نو څښتن تعالی داسې وایي: «افسوس د خونړي ښار په حال! زه به هم د هغه لاندې د سوځولو دپاره د لرګيو ډېرۍ جوړه کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_009.mp3', NULL, 1761758917, 1761758917),
(41785, 'Ezekiel 24:10', 'Ezekiel', 24, 10, 'نو ډېر لرګي راوړئ او اور بل کړئ! غوښه ښه پخه کړئ، مساله په کې واچوئ او تر هغې پورې يې وخوټوئ چې اوبه یې وچې شي او هډوکي وسوځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_010.mp3', NULL, 1761758917, 1761758917),
(41786, 'Ezekiel 24:11', 'Ezekiel', 24, 11, 'بیا هغه د برنجو خالي دېګی د سکارو په اور باندې کېږدئ او هغه پرېږدئ چې تک سور شي. بیا به د هغه زنګ وسوځي او هغه به بېرته پاک شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_011.mp3', NULL, 1761758917, 1761758917),
(41787, 'Ezekiel 24:12', 'Ezekiel', 24, 12, 'خو ما بې‌ګټې ځان ستړی کړ، ځکه دېګی لا پاک شوی نه دی. هغه چټلي په اور کې بیا واچوئ چې پاکه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_012.mp3', NULL, 1761758917, 1761758917),
(41788, 'Ezekiel 24:13', 'Ezekiel', 24, 13, 'ای اورشلیمه، ته خپلې شهوت پرستۍ ناپاکه کړی یې. سره له دې ما هڅه وکړه چې تا پاک کړم، خو ته هماغسې ناپاکه پاتې شوې. ترڅو پورې چې تا زما د قهر زور نه وي لیدلی، ته به بېرته پاک نه شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_013.mp3', NULL, 1761758917, 1761758917),
(41789, 'Ezekiel 24:14', 'Ezekiel', 24, 14, 'ما څښتن داسې وویل. د عمل وخت رارسېدلی دی. زه به د سزا ورکولو څخه ډډه ونه کړم، نه به درباندې زړه وسوځوم او نه به درباندې رحم وکړم. بلکې تاسو چې کوم کارونه کړي دي، د هغو له امله به تاسو محاکمه کړم. زه څښتن داسې وایم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_014.mp3', NULL, 1761758917, 1761758917),
(41790, 'Ezekiel 24:15', 'Ezekiel', 24, 15, 'څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_015.mp3', NULL, 1761758917, 1761758917),
(41791, 'Ezekiel 24:16', 'Ezekiel', 24, 16, '«ای فاني انسانه، زه به د سترګو په رپ کې ستا ښځه چې په تا باندې ډېره ګرانه او د سترګو تور دی، ستا نه واخلم. خو ته ویر مه کوه، مه ژاړه او اوښکې مه تویوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_016.mp3', NULL, 1761758917, 1761758917),
(41792, 'Ezekiel 24:17', 'Ezekiel', 24, 17, 'ستا اسوېلي باید ونه اورېدل شي. له غمه سرتور سر او لوڅې پښې مه ګرځه. له غمه خپل مخ مه پټوه او د مړي د کور ډوډۍ مه خوره.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_017.mp3', NULL, 1761758917, 1761758917),
(41793, 'Ezekiel 24:18', 'Ezekiel', 24, 18, 'نو بیا مې د سهار په وخت د خلکو سره خبرې وکړې او ماښام زما ښځه مړه شوه. بله ورځ مې هماغسې وکړل لکه څنګه چې څښتن راته ویلي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_018.mp3', NULL, 1761758917, 1761758917),
(41794, 'Ezekiel 24:19', 'Ezekiel', 24, 19, 'خلکو زما نه پوښتنه وکړه: «دا کارونه مونږ ته څه معنی لري او ولې مونږ ته نه وایې؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_019.mp3', NULL, 1761758917, 1761758917),
(41795, 'Ezekiel 24:20', 'Ezekiel', 24, 20, 'نو ما هغوی ته وویل: «څښتن زما سره خبرې وکړې او راته ویې ویل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_020.mp3', NULL, 1761758917, 1761758917),
(41796, 'Ezekiel 24:21', 'Ezekiel', 24, 21, 'چې څښتن تعالی تاسو اسراییلیانو ته دا پیغام لري: ‹زه اوس د خپل سپېڅلي عبادت ځای سپکاوی کوم او هغه د قوت مقام چې تاسو ورباندې ویاړ کاوه، ورانوم. ستاسو د سترګو تور او د مینې د پام وړ ځای تباه کوم. ستاسو زامن او لورګانې چې په اورشلیم کې پاتې شوي دي، هغوی ټول به په جنګ کې ووژل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_021.mp3', NULL, 1761758917, 1761758917),
(41797, 'Ezekiel 24:22', 'Ezekiel', 24, 22, 'بیا به تاسو زما په شان هماغسې وکړئ. له غمه به خپل مخ نه پټوئ او نه به د مړي د کور ډوډۍ خورئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_022.mp3', NULL, 1761758917, 1761758917),
(41798, 'Ezekiel 24:23', 'Ezekiel', 24, 23, 'تاسو به سرتور سر او لوڅې پښې نه ګرځئ او نه به ویر او ژړا کوئ. تاسو به یو بل ته فریادونه کوئ او د خپلو ګناهونو له امله به کمزوري کېږئ، ترڅو له منځه لاړ شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_023.mp3', NULL, 1761758917, 1761758917),
(41799, 'Ezekiel 24:24', 'Ezekiel', 24, 24, 'بیا به حزقیال ستاسو دپاره یو مثال وي چې پیروي ورڅخه وکړئ، هغه چې څه کوي تاسو به هم هماغسې کوئ. څښتن وایي چې کله داسې وشي، نو تاسو به پوه شئ چې زه څښتن تعالی یم.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_024.mp3', NULL, 1761758917, 1761758917),
(41800, 'Ezekiel 24:25', 'Ezekiel', 24, 25, 'څښتن وویل: «ای فاني انسانه، زه به د هغوی نه هغه قوي کلا چې هغوی ورباندې ویاړ او خوشحالي کوي او د هغه په لیدلو خوند اخلي، واخلم او د هغوی نه به زامن او لورګانې هم واخلم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_025.mp3', NULL, 1761758917, 1761758917),
(41801, 'Ezekiel 24:26', 'Ezekiel', 24, 26, 'په هغه ورځ چې زه دا کار کوم، نو څوک چې د دې تباهۍ نه تښتېدلی وي، هغه به راشي او په دې هکله به خبر ورکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_026.mp3', NULL, 1761758917, 1761758917),
(41802, 'Ezekiel 24:27', 'Ezekiel', 24, 27, 'په هماغه ورځ به ته بیا خبرې وکولای شې او نور به ګونګی پاتې نه شې. نو کوم څه چې ستا سره پېښیږي، هغه به د خلکو دپاره یوه نښه شې او هغوی به په دې پوه شي چې زه څښتن یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel24_verse_027.mp3', NULL, 1761758917, 1761758917),
(41803, 'Ezekiel 13:1', 'Ezekiel', 13, 1, 'څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_001.mp3', NULL, 1761758917, 1761758917),
(41804, 'Ezekiel 13:2', 'Ezekiel', 13, 2, '«ای فاني انسانه، د اسراییلو د هغو پیغمبرانو په ضد نبوت وکړه چې د خپل ځان نه نبوت کوي. هغوی ته ووایه چې د څښتن کلام ته غوږ ونیسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_002.mp3', NULL, 1761758917, 1761758917),
(41805, 'Ezekiel 13:3', 'Ezekiel', 13, 3, 'څښتن تعالی داسې وایي: ‹افسوس د دې کم‌عقلو پیغمبرانو په حال! هغوی د خپلو ځانونو نه الهام ورکوي او هغه رویاګانې یې چې نه دي لیدلې، بیانوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_003.mp3', NULL, 1761758917, 1761758917),
(41806, 'Ezekiel 13:4', 'Ezekiel', 13, 4, 'ای د اسراییلو خلکو، ستاسو پیغمبران د هغو ګیدړانو په شان دي چې د ښار په کنډوالو کې اوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_004.mp3', NULL, 1761758917, 1761758917),
(41807, 'Ezekiel 13:5', 'Ezekiel', 13, 5, 'هغو پیغمبرانو تاسو اسراییلیانو سره مرسته ونه کړه چې د ښار هغه دېوالونه بېرته جوړ کړي چې غورځېدلي دي. دا کار باید ترسره شي، ترڅو په هغه وخت کې چې زه څښتن ستاسو دښمنان پرېږدم چې په تاسو باندې حمله وکړي، ستاسو دېوالونه قوي وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_005.mp3', NULL, 1761758917, 1761758917),
(41808, 'Ezekiel 13:6', 'Ezekiel', 13, 6, 'د هغوی رویاګانې غلطې دي او د هغوی پېشګویانې دروغ دي. هغوی دا دعوه کوي چې زما د پیغام په هکله خبرې کوي، خو هغوی ما نه دي لېږلي. خو بیاهم هغوی په دې تمه دي چې خبرې به یې رښتیا شي!›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_006.mp3', NULL, 1761758917, 1761758917),
(41809, 'Ezekiel 13:7', 'Ezekiel', 13, 7, 'زه هغوی ته وایم: ‹تاسو چې کومې رویاګانې وینئ هغه بې‌ارزښته دي او تاسو چې کومې پېشګویانې کوئ هغه دروغ دي. تاسو وایئ چې دا زما خبرې دي، خو ما تاسو سره خبرې نه دي کړي!›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_007.mp3', NULL, 1761758917, 1761758917),
(41810, 'Ezekiel 13:8', 'Ezekiel', 13, 8, 'نو څښتن تعالی هغوی ته داسې وایي: ‹ستاسو خبرې بې‌ارزښته دي او ستاسو رویاګانې دروغ دي. نو له دې امله زه څښتن تعالی ستاسو په ضد یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_008.mp3', NULL, 1761758917, 1761758917),
(41811, 'Ezekiel 13:9', 'Ezekiel', 13, 9, 'زه به خپل لاس د هغو ټولو پیغمبرانو په خلاف پورته کړم چې بې‌ارزښته رویاګانې ویني او دروغجنې پېشګویانې کوي. هغوی به زما د قوم د ټولنې څخه وشړل شي. زه به د هغوی نومونه د اسرایيلو د لست نه لېرې کړم او هغوی به بيا هيڅکله په خپل وطن کې پښې کښېنږدي. نو بیا به په دې پوه شئ چې زه څښتن تعالی یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_009.mp3', NULL, 1761758917, 1761758917),
(41812, 'Ezekiel 13:10', 'Ezekiel', 13, 10, 'پیغمبران زما قوم بې‌لارې کوي او وایي چې خیر خیریت دی. خو په رښتیا سره خیریت نه دی! زما قوم یو کمزوری دېوال جوړ کړی دی او پیغمبران راغلي دي او هغه یې په چونه او ګچو باندې سپین کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_010.mp3', NULL, 1761758917, 1761758917),
(41813, 'Ezekiel 13:11', 'Ezekiel', 13, 11, 'دې پیغمبرانو ته ووایه چې دېوال به راوغورځیږي. سخت باران به ووریږي، ږلۍ به ووریږي او یو توفان به ورباندې راشي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_011.mp3', NULL, 1761758917, 1761758917),
(41814, 'Ezekiel 13:12', 'Ezekiel', 13, 12, 'کله چې دېوال راوغورځیږي، نو هرڅوک به ستاسو نه پوښتنه کوي چې د دېوال د سپینولو څه ګټه وه؟›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_012.mp3', NULL, 1761758917, 1761758917),
(41815, 'Ezekiel 13:13', 'Ezekiel', 13, 13, 'په دې خاطر څښتن تعالی داسې وایي: ‹زه به په خپل قهر سره یو توفان، سخت باران او ږلۍ نازل کړم چې هغه دېوال وران کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_013.mp3', NULL, 1761758917, 1761758917),
(41816, 'Ezekiel 13:14', 'Ezekiel', 13, 14, 'زه غواړم چې هغه چونه شوی دېوال راوغورځوم او هغه به د ځمکې سره هوار کړم او د بنیاد تیږې به یې راښکاره شي. هغه به راولویږي او تاسو ټول به مړه کړي. بیا به ټول په دې پوه شي چې زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_014.mp3', NULL, 1761758917, 1761758917),
(41817, 'Ezekiel 13:15', 'Ezekiel', 13, 15, 'نو زما قهر به په دېوال او په هغه چا چې هغه یې رنګ کړی دی، سوړ شي. بیا به تاسو ته ووایم چې هغه دېوال او د هغه رنګ کوونکي نور نشته.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_015.mp3', NULL, 1761758917, 1761758917),
(41818, 'Ezekiel 13:16', 'Ezekiel', 13, 16, 'دا هغه پیغمبران وو چې په ډاډه زړه سره به یې ویل چې په اورشلیم کې خیر خیریت دی، خو حال دا چې هلته خیریت نه ؤ.› څښتن تعالی داسې ویلي دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_016.mp3', NULL, 1761758917, 1761758917),
(41819, 'Ezekiel 13:17', 'Ezekiel', 13, 17, 'څښتن وویل: «ای فاني انسانه، د اسراییلو هغه ښځې محکومې کړه چې له خپله ځانه پېشګویي کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_017.mp3', NULL, 1761758917, 1761758917),
(41820, 'Ezekiel 13:18', 'Ezekiel', 13, 18, 'هغوی ته ووایه چې څښتن تعالی ورته داسې وایي: ‹افسوس ستاسو په حال! تاسو هرچا ته د کوډو تعویذونه جوړوئ چې په خپلو مړوندونو باندې یې وتړي او هرچا ته د هغه د قد په اندازه د کوډو دستمالونه جوړوئ چې خپل سرونه ورباندې وتړي، ترڅو وکولای شئ د نورو خلکو د ژوند واک ولرئ. ایا تاسو غواړئ چې زما د خلکو د ژوند او مرګ اختیار تر‌لاسه کړئ او د هغه څخه د خپل ځان په ګټه کار واخلئ؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_018.mp3', NULL, 1761758917, 1761758917),
(41821, 'Ezekiel 13:19', 'Ezekiel', 13, 19, 'تاسو د څو موټو اوربشو او د څو ټوټو ډوډیو په خاطر زما د قوم په مخکې زما سپکاوی وکړ. تاسو هغه خلک وژنئ کوم چې د مرګ لایق نه دي او هغه خلک ژوندي پرېږدئ کوم چې د ژوندي پرېښودلو لایق نه دي. تاسو زما خلکو ته دروغ وایئ او هغوی په تاسو باندې یقین کوي.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_019.mp3', NULL, 1761758917, 1761758917),
(41822, 'Ezekiel 13:20', 'Ezekiel', 13, 20, 'نو څښتن تعالی داسې وایي: ‹ګورئ، زه د کوډو د تعویذونو په ضد یم چې تاسو یې په مرګ او ژوند باندې د قدرت ترلاسه کولو په خاطر د خلکو په مټو باندې تړئ. زه به هغه ستاسو د مټو څخه وشکوم او هغه خلک به خلاص کړم چې تاسو د مرغیو په شان په دام کې راګېر کړي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_020.mp3', NULL, 1761758917, 1761758917),
(41823, 'Ezekiel 13:21', 'Ezekiel', 13, 21, 'زه به ستاسو د سرونو دستمالونه وشکوم او خپل قوم به خلاص کړم او نور به ونه شئ کولائ په خپل دام کې هغوی راګېر کړئ. نو بیا به تاسو پوه شئ چې زه څښتن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_021.mp3', NULL, 1761758917, 1761758917),
(41824, 'Ezekiel 13:22', 'Ezekiel', 13, 22, 'دا ځکه چې تاسو په خپلو دروغو باندې د هغو نېکو خلکو زړونه تور کړي دي چې زه نه غواړم هغوی خفه کړم. تاسو بدعمله خلک دې ته هڅولي دي چې د خپلو بدو کارونو نه لاس وانخلي او خپل ژوند وژغوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_022.mp3', NULL, 1761758917, 1761758917),
(41825, 'Ezekiel 13:23', 'Ezekiel', 13, 23, 'نو اوس به تاسو بې‌ارزښته رویاګانې ونه وینئ او بې‌لارې کوونکې پېشګویانې به نه کوئ. زه به خپل قوم ستاسو د منګولو نه خلاص کړم، نو هغه وخت به په دې پوه شئ چې زه څښتن یم.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel13_verse_023.mp3', NULL, 1761758917, 1761758917),
(41826, 'Zechariah 13:1', 'Zechariah', 13, 1, '”په هغه ورځ به چينه د داؤد د خاندان او د يروشلم اوسېدونکو دپاره کولاو شى چې دوئ د ګناه او ناپاکۍ نه پاک کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_001.mp3', NULL, 1761758917, 1761758917),
(41827, 'Zechariah 13:2', 'Zechariah', 13, 2, 'په هغه ورځ به زۀ د بُتانو نومونه د مُلک نه ختم کړم، هغوئ به نور نۀ ياديږى،“ مالِک خُدائ ربُ الافواج فرمائى. ”زۀ به دروغژن پېغمبران او ناپاکه روحونه دواړه د مُلک نه ختم کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_002.mp3', NULL, 1761758917, 1761758917),
(41828, 'Zechariah 13:3', 'Zechariah', 13, 3, 'او کۀ اوس هم څوک پېشګوئې کوى، د هغۀ پلار او مور، چا نه چې هغه پېدا دے، به هغۀ ته وائى، تۀ به ضرور مړ شې، ځکه چې تا د مالِک خُدائ په نوم دروغ ووئيل. کله چې هغه پېشګوئې کوى د هغۀ خپل پلار مور به يې وڅيرى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_003.mp3', NULL, 1761758917, 1761758917),
(41829, 'Zechariah 13:4', 'Zechariah', 13, 4, 'په هغه ورځ به پېغمبران په پېشګوئې کولو او په رويا بيانولو شرميږى. د پېغمبرانو په ببره چُوغه اچولو به څوک هم نۀ دوکه کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_004.mp3', NULL, 1761758917, 1761758917),
(41830, 'Zechariah 13:5', 'Zechariah', 13, 5, 'هغه به وائى، زۀ پېغمبر نۀ يم. زۀ زميندار يم، زمکه د ځوانۍ نه زما روزګار دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_005.mp3', NULL, 1761758917, 1761758917),
(41831, 'Zechariah 13:6', 'Zechariah', 13, 6, 'کۀ څوک ترې نه تپوس وکړى، دا زخمونه ستا په بدن باندې د څۀ دى؟ هغه به جواب ورکړى، دا زخمونه په ما باندې زما د ملګرى کور کښې لګېدلى دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_006.mp3', NULL, 1761758917, 1761758917),
(41832, 'Zechariah 13:7', 'Zechariah', 13, 7, 'اے تُورې، زما د شپونکى خلاف راپاڅه، د هغه سړى خلاف چې زما ملګرے دے.“ مالِک خُدائ ربُ الافواج فرمائى. ”زۀ به شپون ووهم، او ګډې به يې خورې ورې شى، او زۀ به خپل لاس د هغوئ خلاف اوږد کړم چې واړۀ دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_007.mp3', NULL, 1761758917, 1761758917),
(41833, 'Zechariah 13:8', 'Zechariah', 13, 8, 'په ټول مُلک کښې،“ مالِک خُدائ فرمائى، ”په درېو کښې به دوه مړۀ او تباه شى، درېو کښې به يو پاتې شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_008.mp3', NULL, 1761758917, 1761758917),
(41834, 'Zechariah 13:9', 'Zechariah', 13, 9, 'دا درېمه برخه به زۀ اور کښې واچوم، زۀ به دوئ لکه د سپينو زرو په شان صفا کړم او لکه د سرو زرو به يې وآزمائيم. هغوئ به زما په نوم آواز وکړى او زۀ به هغوئ له جواب ورکړم، او زۀ به ووايم چې، دوئ زما خلق دى، او هغوئ به وائى، مالِک خُدائ زمونږ خُدائ پاک دے.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah13_verse_009.mp3', NULL, 1761758917, 1761758917),
(41835, 'Genesis 48:1', 'Genesis', 48, 1, 'څه موده وروسته یوسف ته خبر ورسېده چې پلار یې ناروغ دی. نو هغه خپل دواړه زامن منسي او افرایم د ځان سره واخیستل او د خپل پلار لیدلو ته ورغی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_001.mp3', NULL, 1761758917, 1761758917),
(41836, 'Genesis 48:2', 'Genesis', 48, 2, 'کله چې یعقوب خبر شو چې د هغه زوی یوسف د هغه د لیدلو دپاره راغلی دی، نو هغه د خپل ټول قوت څخه کار واخیست، ترڅو په خپل کټ باندې کښېناست.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_002.mp3', NULL, 1761758917, 1761758917),
(41837, 'Genesis 48:3', 'Genesis', 48, 3, 'یعقوب یوسف ته وویل: «مطلق قادر خدای ماته د کنعان په وطن کې په لوز کې راښکاره شو او برکت یې راته راکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_003.mp3', NULL, 1761758917, 1761758917),
(41838, 'Genesis 48:4', 'Genesis', 48, 4, 'ماته یې وویل: ‹تاته به زیات اولادونه درکړم. ستا د نسل څخه به زیات قومونه جوړ کړم او دغه ځمکه به ستا څخه وروسته ستا اولادې ته د هغوی د تلپاتې ملکیت په توګه ورکړم.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_004.mp3', NULL, 1761758917, 1761758917),
(41839, 'Genesis 48:5', 'Genesis', 48, 5, 'نو اوس ستا دوه زامن چې زما د راتللو څخه مخکې په مصر کې زېږېدلي وو، هغوی زما دي. افرایم او منسي د روبین او شمعون په شان زما زامن دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_005.mp3', NULL, 1761758917, 1761758917),
(41840, 'Genesis 48:6', 'Genesis', 48, 6, 'له دوی څخه وروسته چې ستا کوم اولادونه پیدا کیږي هغه به ستا وي او د هغوی میراث به د افرایم او منسي څخه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_006.mp3', NULL, 1761758917, 1761758917),
(41841, 'Genesis 48:7', 'Genesis', 48, 7, 'کله چې زه د بین‌النهرین څخه راتللم، نو په خواشینۍ سره راحیل د کنعان په خاوره کې افراتې ته نژدې په لاره کې مړه شوه. نو هغه مې د افراتې د لارې تر‌څنګه ښخه کړه.» (هغه ځای اوس د بیت‌لحم په نوم یادیږي.)', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_007.mp3', NULL, 1761758917, 1761758917),
(41842, 'Genesis 48:8', 'Genesis', 48, 8, 'کله چې یعقوب د یوسف زامن ولیدل، هغه پوښتنه وکړه: «دا څوک دي؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_008.mp3', NULL, 1761758917, 1761758917),
(41843, 'Genesis 48:9', 'Genesis', 48, 9, 'یوسف خپل پلار ته وویل: «دا زما زامن دي چې خدای ماته دلته په مصر کې راکړي دي.» بیا یعقوب وویل: «هغوی ماته راوله چې زه ورته برکت ورکړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_009.mp3', NULL, 1761758917, 1761758917),
(41844, 'Genesis 48:10', 'Genesis', 48, 10, 'د یعقوب سترګې د زوړوالي له امله دومره کمزورې شوې وې چې څه شی ورته سم نه ښکاره کېده. نو یوسف خپل زامن هغه ته ورنژدې کړل او د هغه پلار هغوی ښکل کړل او په خپل غېږ کې یې ونیول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_010.mp3', NULL, 1761758917, 1761758917),
(41845, 'Genesis 48:11', 'Genesis', 48, 11, 'یعقوب یوسف ته وویل: «ما هېڅکله دا هیله نه درلودله چې ستا مخ به بیا ووینم او اوس خدای زه دې ته پرېښودم چې ستا اولادونه هم ووینم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_011.mp3', NULL, 1761758917, 1761758917),
(41846, 'Genesis 48:12', 'Genesis', 48, 12, 'بیا یوسف هغوی د خپل پلار د زنګنونو څخه لېرې کړل او د درناوي په خاطر یې هغه ته خپل سر ټیټ کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_012.mp3', NULL, 1761758917, 1761758917),
(41847, 'Genesis 48:13', 'Genesis', 48, 13, 'یوسف افرایم د یعقوب چپ لاس ته او منسي یې د هغه ښي لاس ته نژدې راوستل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_013.mp3', NULL, 1761758917, 1761758917),
(41848, 'Genesis 48:14', 'Genesis', 48, 14, 'خو یعقوب خپل ښي لاس اوږد کړ او هغه یې د افرایم په سر باندې کېښود، که څه هم هغه کشر ؤ او خپل چپ لاس یې د منسي په سر باندې چې مشر ؤ، کېښود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_014.mp3', NULL, 1761758917, 1761758917),
(41849, 'Genesis 48:15', 'Genesis', 48, 15, 'بیا هغه یوسف ته برکت ورکړ او ویې ویل: «هغه خدای چې زما پلرونو ابراهیم او اسحاق یې خدمت کړی دی، هغه دې دغو هلکانو ته برکت ورکړي! هغه خدای چې تر دې ورځې پورې یې زما لارښوونه کړې، هغوی ته دې برکت ورکړي!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_015.mp3', NULL, 1761758917, 1761758917),
(41850, 'Genesis 48:16', 'Genesis', 48, 16, 'هغه فرښته دې هغوی ته برکت ورکړي چې زه یې د ټولو بدیو څخه ژغورلی یم! زما او زما د نیکونو ابراهیم او اسحاق نومونه دې د دوی په وسیله ژوندي وساتل شي او هغوی دې ډېره اولاده ولري.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_016.mp3', NULL, 1761758917, 1761758917),
(41851, 'Genesis 48:17', 'Genesis', 48, 17, 'کله چې یوسف ولیدل چې پلار یې خپل ښي لاس د افرایم په سر باندې کېښود هغه خفه شو. نو د خپل پلار لاس یې ونیوه چې د افرایم له سر څخه یې د منسي سرته راواړوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_017.mp3', NULL, 1761758917, 1761758917),
(41852, 'Genesis 48:18', 'Genesis', 48, 18, 'یوسف هغه ته وویل: «نه پلاره، دغه مشر دی. خپل ښي لاس دې د هغه په سر باندې کېږده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_018.mp3', NULL, 1761758917, 1761758917),
(41853, 'Genesis 48:19', 'Genesis', 48, 19, 'د هغه پلار انکار وکړ او ویې ویل: «ای زویه، زه پوهېږم! زه پوهېږم چې د منسي څخه به هم یو لوی قوم جوړ شي. خو د هغه کشر ورور به د هغه څخه لوی سړی شي، ځکه چې د هغه د اولادې څخه به لوی قومونه پیدا شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_019.mp3', NULL, 1761758917, 1761758917),
(41854, 'Genesis 48:20', 'Genesis', 48, 20, 'په هغه ورځ یعقوب هغوی ته برکت ورکړ او ویې ویل: «د اسراییلو قوم به یو بل ته ستاسو په نوم برکت غواړي او داسې به وایي چې خدای دې تا د افرایم او منسي په شان کړي.» په دې ډول یعقوب افرایم ته په منسي باندې د لومړي‌توب حق ورکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_020.mp3', NULL, 1761758917, 1761758917),
(41855, 'Genesis 48:21', 'Genesis', 48, 21, 'بیا یعقوب یوسف ته وویل: «ګوره، زه مرګ ته نژدې یم، خو خدای به تاسو سره مل وي او تاسو به بېرته د خپلو نیکونو وطن ته بوځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_021.mp3', NULL, 1761758917, 1761758917),
(41856, 'Genesis 48:22', 'Genesis', 48, 22, 'د شکیم هغه حاصلخېزه سیمه چې ما د اموریانو څخه د خپلې تورې او لیندې په زور نیولې ده، ستا ورونو ته نه، بلکې تاته درکوم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis48_verse_022.mp3', NULL, 1761758917, 1761758917),
(41857, 'Psalms 36:1', 'Psalms', 36, 1, 'د زړه په تل کې د بدکاره خلکو کوي ګناه خبرې هغوی هېڅ وېریږي نه له خدایه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_001.mp3', NULL, 1761758917, 1761758917),
(41858, 'Psalms 36:2', 'Psalms', 36, 2, 'دا چې دوی ځان ته ډېر اوچت فکر کړي فکر کوي چې خدای به نه کړي پیدا د دوی ګناه او نه به یې وغندي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_002.mp3', NULL, 1761758917, 1761758917),
(41859, 'Psalms 36:3', 'Psalms', 36, 3, 'د دوی د خولې خبرې بدې، له دروغو ډکې دوی نور نه کړي عقلمن کار او نېکي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_003.mp3', NULL, 1761758917, 1761758917),
(41860, 'Psalms 36:4', 'Psalms', 36, 4, 'کله چې پروت وي بستره کې پلانونه د بدۍ جوړوي هغه خپل ځان په بده لار بوځي نه اخلي لاس له بده کاره ځینې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_004.mp3', NULL, 1761758917, 1761758917),
