(41863, 'Psalms 36:7', 'Psalms', 36, 7, 'دا ستا تلپاتې مینه څومره قیمتي ده خدایه! ستا د وزرو لاندې پناه اخلي ټول خلک', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_007.mp3', NULL, 1761758917, 1761758917),
(41864, 'Psalms 36:8', 'Psalms', 36, 8, 'کړي د پرېمانه خوړو ستا نه خوراکونه هغوی خپل د خوښۍ د سیند نه دوی ته، ته اوبه ورکوې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_008.mp3', NULL, 1761758917, 1761758917),
(41865, 'Psalms 36:9', 'Psalms', 36, 9, 'یې د ژوندون سرچینه ستا د نور په سبب وینو مونږ رڼا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_009.mp3', NULL, 1761758917, 1761758917),
(41866, 'Psalms 36:10', 'Psalms', 36, 10, 'څوک چې تا پېژني هغو سره کوه مینه تلپاتې مینه څوک چې نېکان دي د هغوی سره نېکي کوه ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_010.mp3', NULL, 1761758917, 1761758917),
(41867, 'Psalms 36:11', 'Psalms', 36, 11, 'مه پرېږده مغروره خلک چې مې تر پښو لاندې کړي یا بدکاران خلک چې ما وشړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms36_verse_011.mp3', NULL, 1761758917, 1761758917),
