(41874, 'Psalms 149:6', 'Psalms', 149, 6, 'په لوړ اواز دې د څښتن ثنا او صفت وکړي او دوه‌مخیزه تورې دې وي د دوی لاسونو کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms149_verse_006.mp3', NULL, 1761758917, 1761758917),
(41875, 'Psalms 149:7', 'Psalms', 149, 7, 'چې د قومونو نه بدل واخلي او سزا ورکړي هغو خلکو ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms149_verse_007.mp3', NULL, 1761758917, 1761758917),
(41876, 'Psalms 149:8', 'Psalms', 149, 8, 'او زولانه کړي د هغوی پاچاهان او په زنځیرونو یې مشران وتړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms149_verse_008.mp3', NULL, 1761758917, 1761758917),
(41877, 'Psalms 149:9', 'Psalms', 149, 9, 'او لکه څنګه چې خدای حکم کړی چې نورو قومونو ته سزا ورکړي دا کامیابي به وي د خدای د وفادارو خلکو د څښتن ثنا او صفت وکړئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms149_verse_009.mp3', NULL, 1761758917, 1761758917),
(41878, 'Psalms 54:1', 'Psalms', 54, 1, 'ته په خپل واک باندې ما خلاص کړه خدایه وکړه قضاوت د عدالت په خپل قوت زما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms54_verse_001.mp3', NULL, 1761758917, 1761758917),
(41879, 'Psalms 54:2', 'Psalms', 54, 2, 'خدایه زما دعا قبوله کړه ته زما خبرو ته ته غوږ ونیسه!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms54_verse_002.mp3', NULL, 1761758917, 1761758917),
(41880, 'Psalms 54:3', 'Psalms', 54, 3, 'پردي خلک کړي په ما باندې حمله ظالمان کوي کوښښ چې ومې وژني هغه دي چې نه لري پروا د خدای', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms54_verse_003.mp3', NULL, 1761758917, 1761758917),
(41881, 'Psalms 54:4', 'Psalms', 54, 4, 'خو خدای زما دی مددګار څښتن ساتونکی دی زما د ژوند', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms54_verse_004.mp3', NULL, 1761758917, 1761758917),
(41882, 'Psalms 54:5', 'Psalms', 54, 5, 'خدای دې راوګرځوي خپل بد عملونه په دښمن زما ای خدایه زما د حفاظت وعده په ځای کړه او ته ختم یې کړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms54_verse_005.mp3', NULL, 1761758917, 1761758917),
(41883, 'Psalms 54:6', 'Psalms', 54, 6, 'د رضاکاره نذرانې سره به تاته قرباني کومه ای څښتنه زه به شکر ستا کومه ځکه ته یې مهربانه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms54_verse_006.mp3', NULL, 1761758917, 1761758917),
(41884, 'Psalms 54:7', 'Psalms', 54, 7, 'زه دې د ټولو تکلیفونو نه خلاص کړی یمه په خپلو سترګو د دښمن ماتې لیدلې ده ما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms54_verse_007.mp3', NULL, 1761758917, 1761758917),
(41885, 'Proverbs 9:1', 'Proverbs', 9, 1, 'حکمت د یوې ښځې په څېر خپل کور ودان کړی دی او اووه ستنې یې توږلې او بیا یې ودرولې دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_001.mp3', NULL, 1761758917, 1761758917),
(41886, 'Proverbs 9:2', 'Proverbs', 9, 2, 'هغې د مېلمستیا دپاره غوښه تیاره کړې او د انګورو شیره یې جوړه کړې ده او دسترخوان یې هوار کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_002.mp3', NULL, 1761758917, 1761758917),
(41887, 'Proverbs 9:3', 'Proverbs', 9, 3, 'هغې خپلې وینځې ورولېږلې چې د ښار له لوړو ځایونو نه خپل غږ پورته کړي:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_003.mp3', NULL, 1761758917, 1761758917),
(41888, 'Proverbs 9:4', 'Proverbs', 9, 4, '«هرڅوک چې ساده وي، دلته دې راشي!» او بیا ناپوهه خلکو ته وایي:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_004.mp3', NULL, 1761758917, 1761758917),
(41889, 'Proverbs 9:5', 'Proverbs', 9, 5, '«راشئ! زما ډوډۍ وخورئ او لږه د انګورو شیره وڅښئ کوم چې ما جوړه کړې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_005.mp3', NULL, 1761758917, 1761758917),
(41890, 'Proverbs 9:6', 'Proverbs', 9, 6, 'خپله د ناپوهۍ لار پرېږدئ نو تاسو به نېکمرغه ژوند ولرئ او د عقل په لاره به روان شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_006.mp3', NULL, 1761758917, 1761758917),
(41891, 'Proverbs 9:7', 'Proverbs', 9, 7, 'څوک چې ملنډې وهونکی اصلاح کوي نو ځان شرموي او څوک چې بدکار رټي نو ځان ته زیان رسوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_007.mp3', NULL, 1761758917, 1761758917),
(41892, 'Proverbs 9:8', 'Proverbs', 9, 8, 'د ملنډې وهونکی رټنه مه کوه هسې نه چې ستا نه کرکه وکړي د حکمت د خاوند رټنه کوه نو ستا سره به مینه وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_008.mp3', NULL, 1761758917, 1761758917),
(41893, 'Proverbs 9:9', 'Proverbs', 9, 9, 'د حکمت خاوند ته لارښوونه وکړه نو نور به هم خپل حکمت ډېر کړي نېک سړي ته تعلیم ورکړه چې خپله پوهه نوره هم زیاته کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_009.mp3', NULL, 1761758917, 1761758917),
(41894, 'Proverbs 9:10', 'Proverbs', 9, 10, 'له څښتن څخه وېره د حکمت شروع ده او عقل د سپېڅلي ذات د پېژندلو علم دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_010.mp3', NULL, 1761758917, 1761758917),
(41895, 'Proverbs 9:11', 'Proverbs', 9, 11, 'ځکه زما په مرسته به ستا د ژوند ورځې ډېرې شي او ستا د عمر کلونه به نور هم زیات شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_011.mp3', NULL, 1761758917, 1761758917),
(41896, 'Proverbs 9:12', 'Proverbs', 9, 12, 'که د حکمت خاوند یې نو دا به دې په ګټه وي او که ته ملنډې وهونکی یې نو یوازې زیان به زغمې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_012.mp3', NULL, 1761758917, 1761758917),
(41897, 'Proverbs 9:13', 'Proverbs', 9, 13, 'کم‌عقلتوب د یوې بې‌حیا ښځې په څېر دی چې ډېره ساده او په هېڅ نه پوهیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_013.mp3', NULL, 1761758917, 1761758917),
(41898, 'Proverbs 9:14', 'Proverbs', 9, 14, 'هغه د خپل کور د دروازې تر‌څنګ ناسته ده او بیا د ښار په لوړو ځایونو کې په تخت کښېني.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_014.mp3', NULL, 1761758917, 1761758917),
(41899, 'Proverbs 9:15', 'Proverbs', 9, 15, 'څوک چې په خپله لار سم ځي نو هغوی ته نارې وهي:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_015.mp3', NULL, 1761758917, 1761758917),
(41900, 'Proverbs 9:16', 'Proverbs', 9, 16, '«هرڅوک چې ساده وي، دلته دې راشي!» او بیا ناپوهه انسان ته وایي:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_016.mp3', NULL, 1761758917, 1761758917),
(41901, 'Proverbs 9:17', 'Proverbs', 9, 17, '«د غلا اوبه خوږې وي او په پټه تر‌لاسه شوې ډوډۍ خوندوره وي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_017.mp3', NULL, 1761758917, 1761758917),
(41902, 'Proverbs 9:18', 'Proverbs', 9, 18, 'هغوی نه پوهیږي چې د هغې په کور کې ټول وژل شوي دي او مېلمانه یې د قبر په ژوره کنده کې پراته دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs9_verse_018.mp3', NULL, 1761758917, 1761758917),
(41903, 'Zechariah 6:1', 'Zechariah', 6, 1, 'ما بيا بره وکتل، او هلته زما په وړاندې څلور جنګى ګاډۍ د پيتلو د دوو غرونو د مينځ نه راروانې وې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_001.mp3', NULL, 1761758917, 1761758917),
(41904, 'Zechariah 6:2', 'Zechariah', 6, 2, 'وړومبۍ ګاډۍ کښې سرۀ آسونه، دوېمه کښې تور آسونه وُو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_002.mp3', NULL, 1761758917, 1761758917),
(41905, 'Zechariah 6:3', 'Zechariah', 6, 3, 'درېمه کښې سپين آسونه او څلورمه کښې برَګ آسونه وُو، ټول ډېر مضبوط وُو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_003.mp3', NULL, 1761758917, 1761758917),
(41906, 'Zechariah 6:4', 'Zechariah', 6, 4, 'ما د هغه فرښتې نه تپوس وکړو چا چې ما سره خبرې کولې، ”دا څۀ دى زما مالِکه؟“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_004.mp3', NULL, 1761758917, 1761758917),
(41907, 'Zechariah 6:5', 'Zechariah', 6, 5, 'فرښتې راله جواب راکړو، ”دا د آسمان څلور روحونه دى، دا د ټولې دُنيا د مالِک خُدائ د حضور نه بهر راوتل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_005.mp3', NULL, 1761758917, 1761758917),
(41908, 'Zechariah 6:6', 'Zechariah', 6, 6, 'هغه ګاډۍ چې تور آسونه يې دى د شمال مُلک طرف ته، د سپينو آسونو والا د مغرب طرف ته، او د برَګو آسونو والا د جنوب طرف ته روانه ده.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_006.mp3', NULL, 1761758917, 1761758917),
(41909, 'Zechariah 6:7', 'Zechariah', 6, 7, 'کله چې هغه طاقتور آسونه بهر ووتل، نو هغوئ د دُنيا د ګشت لګولو دپاره بې‌صبره وُو. او هغې وفرمائيل، ”لاړ شئ او په دُنيا کښې ګشت ولګوئ.“ نو هغوئ د دُنيا د ګشت لګولو دپاره لاړل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_007.mp3', NULL, 1761758917, 1761758917),
(41910, 'Zechariah 6:8', 'Zechariah', 6, 8, 'بيا هغې ما ته آواز وکړو چې، ”ګوره، کوم آسونه چې د شمال طرف ته روان دى هغوئ زما غصه په شمال مُلک کښې سړه کړه.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_008.mp3', NULL, 1761758917, 1761758917),
(41911, 'Zechariah 6:9', 'Zechariah', 6, 9, 'بيا د مالِک خُدائ کلام په ما نازل شو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_009.mp3', NULL, 1761758917, 1761758917),
(41912, 'Zechariah 6:10', 'Zechariah', 6, 10, '”د جلاوطن کړے شوى خلدى، طوبياه او يدعياه نه سپين زر او سرۀ زر واخله، څوک چې د بابل نه راغلى دى. هم په هغه ورځ د يوسياه د صفنياه د زوئ کور ته لاړ شه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_010.mp3', NULL, 1761758917, 1761758917),
(41913, 'Zechariah 6:11', 'Zechariah', 6, 11, 'د هغوئ د سپينو زرو او سرو زرو تحفه واخله او تاج ترې جوړ کړه، او دا د مشر اِمام د يهوصدق د زوئ يشوَع په سر کړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_011.mp3', NULL, 1761758917, 1761758917),
(41914, 'Zechariah 6:12', 'Zechariah', 6, 12, 'هغۀ ته ووايه چې، مالِک خُدائ ربُ الافواج دا فرمائى، ”دا هغه سړے دے د چا نوم چې څانګه ده، او دے به د خپل ځان نه څانګې خورې کړى او د مالِک خُدائ کور به جوړ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_012.mp3', NULL, 1761758917, 1761758917),
(41915, 'Zechariah 6:13', 'Zechariah', 6, 13, 'دا هغه څوک دے چې د مالِک خُدائ کور به جوړ کړى او دۀ ته به د بادشاهۍ جامې ورواغوستے شى او په تخت به کښېنى او بادشاهى به کوى. او په خوا کښې به اِمام د دۀ تخت سره ولاړ وى. او د دواړو په مينځ کښې به جوړ توړ وى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_013.mp3', NULL, 1761758917, 1761758917),
(41916, 'Zechariah 6:14', 'Zechariah', 6, 14, 'د خلدى، طوبياه، يدعياه او حين د صفنياه زوئ ته به تاج د مالِک خُدائ په کور کښې د يادګار په توګه ورکړے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_014.mp3', NULL, 1761758917, 1761758917),
(41917, 'Zechariah 6:15', 'Zechariah', 6, 15, 'هغه څوک چې لرې دى هغوئ به راشى او د مالِک خُدائ د کور په جوړولو کښې به مدد وکړى. او تاسو ته به پته ولګى چې مالِک خُدائ ربُ الافواج زۀ تاسو ته رالېږلے يم. دا به وشى خو چې تاسو د مالِک خُدائ د خپل خُدائ پاک پوره تابعدارى وکړئ.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zechariah6_verse_015.mp3', NULL, 1761758917, 1761758917),
(41918, 'Psalms 63:1', 'Psalms', 63, 1, 'ای خدایه ته زما خدای یې زه رجوع کومه تاته خدایه زه په خپل زړه کې ستا لېوال یمه لکه د وچې او بېکاره للمې ځمکې په شان زما روح تږی دی د ستا دپاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_001.mp3', NULL, 1761758917, 1761758917),
(41919, 'Psalms 63:2', 'Psalms', 63, 2, 'ما یې لیدلی په سپېڅلي ځای کې د ستا قدرت او ستا جلال مې په ځیر ځیر کتلی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_002.mp3', NULL, 1761758917, 1761758917),
(41920, 'Psalms 63:3', 'Psalms', 63, 3, 'دا ستا مینه تلپاتې ده بهتره له ژوندونه نو زما شونډې به تا ستایي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_003.mp3', NULL, 1761758917, 1761758917),
(41921, 'Psalms 63:4', 'Psalms', 63, 4, 'ترڅو ژوندی یم ستا ثنا به وایم پورته کوم به خپل لاسونه په دعا کې زه د ستا په نامه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_004.mp3', NULL, 1761758917, 1761758917),
(41922, 'Psalms 63:5', 'Psalms', 63, 5, 'داسې به موړ شم لکه څوک چې په مېله کې غوړ خوراک وکړي په خوشحالۍ سره به وایم ستا ثنا او صفت', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_005.mp3', NULL, 1761758917, 1761758917),
(41923, 'Psalms 63:6', 'Psalms', 63, 6, 'کله زه پروت چې په بستر کې یمه تا یادوم ټوله شپه ستا په اړه فکر کوم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_006.mp3', NULL, 1761758917, 1761758917),
(41924, 'Psalms 63:7', 'Psalms', 63, 7, 'ځکه چې ته مې مددګار وې همېش د سیوري لاندې د وزرونو د ستا د خوشحالۍ سندرې وایمه زه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_007.mp3', NULL, 1761758917, 1761758917),
(41925, 'Psalms 63:8', 'Psalms', 63, 8, 'ما خپل روح تا پورې تړلی دی ستا ځواکمن لاس کوي ملاتړ زما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_008.mp3', NULL, 1761758917, 1761758917),
(41926, 'Psalms 63:9', 'Psalms', 63, 9, 'خو څوک چې هڅه کړي چې ما ووژني هغوی به لاړ شي د مړو دنیا ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_009.mp3', NULL, 1761758917, 1761758917),
(41927, 'Psalms 63:10', 'Psalms', 63, 10, 'په جنګ کې مړه به شي په تورو هغوی شي به یې مړي د سورلنډیانو خوراک', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_010.mp3', NULL, 1761758917, 1761758917),
(41928, 'Psalms 63:11', 'Psalms', 63, 11, 'خو پاچا به خوشحالي کوي د خدای په خاطر څوک چې قسم خوري د خدای په نوم د هغه ثنا او صفت به کوي خو د دروغجنو خولې به بندې شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms63_verse_011.mp3', NULL, 1761758917, 1761758917),
(41929, 'Zephaniah 3:1', 'Zephaniah', 3, 1, 'افسوس د ظالمانو په ښار چې سرکشه او ناپاکه دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_001.mp3', NULL, 1761758917, 1761758917),
(41930, 'Zephaniah 3:2', 'Zephaniah', 3, 2, 'هغه د هيچا تابعدارى نۀ کوى، هغه تربيت نۀ قبلوى. هغه په مالِک خُدائ يقين نۀ کوى، هغه خپل خُدائ پاک ته نزدې نۀ راځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_002.mp3', NULL, 1761758917, 1761758917),
(41931, 'Zephaniah 3:3', 'Zephaniah', 3, 3, 'د دې آفسران غړمبېدونکى زمرى دى، د دې حکمرانان د ماښام ليوانو په شان دى، څوک چې تر سحر پورې خپل ټول ښکار خورى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_003.mp3', NULL, 1761758917, 1761758917),
(41932, 'Zephaniah 3:4', 'Zephaniah', 3, 4, 'د دې پېغمبران کبرژن دى، هغوئ غداران دى، د هغې اِمامان د مقدسو ځايونو بې‌حرمتى کوى او د شريعت نافرمانى کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_004.mp3', NULL, 1761758917, 1761758917),
(41933, 'Zephaniah 3:5', 'Zephaniah', 3, 5, 'مالِک خُدائ په هغه ښار کښې دے هغه صادق دے، هغه هيڅ بې‌اِنصافى نۀ کوى. هغه هر سحر اِنصاف کوى او هره ورځ خپل اِنصاف قائم ساتى. خو بدعمله خلق هيڅ په شرم نۀ پوهيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_005.mp3', NULL, 1761758917, 1761758917),
(41934, 'Zephaniah 3:6', 'Zephaniah', 3, 6, '”ما قومونه ختم کړل، د هغوئ قلعه ګانې مې تباه کړې، ما د هغوئ کوڅې ويجاړې کړې، په هغې کښې څوک تګ راتګ نۀ کوى. د هغوئ ښارونه خالى شوى دى، هيڅ څوک به په کښې پاتې نۀ شى، يو هم نه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_006.mp3', NULL, 1761758917, 1761758917),
(41935, 'Zephaniah 3:7', 'Zephaniah', 3, 7, 'ما ښار ته ووئيل، يقيناً به تۀ زما نه وويرېږې او زما تربيت به قبول کړې. بيا به د هغۀ د اوسېدو ځائ تباه نۀ شى، لکه څنګه چې زما د هغۀ خلاف منصوبه وه. خو د هغوئ اوس هم دا شوق دے چې هغه ټولې بدعملۍ چې کومې يې مخکښې کولې وکړى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_007.mp3', NULL, 1761758917, 1761758917),
(41936, 'Zephaniah 3:8', 'Zephaniah', 3, 8, 'مالِک خُدائ فرمائى چې، ”په دې وجه ما ته انتظار وکړئ، په کومه ورځ چې زۀ به ښکار ونيسم. ما فېصله کړې ده چې قومونه راغونډ کړم، بادشاهۍ رايوځائ کړم، او خپل قهر او سخته غصه پرې نازله کړم. زما د غېرتى قهر په اور به ټوله دُنيا وسوزى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_008.mp3', NULL, 1761758917, 1761758917),
(41937, 'Zephaniah 3:9', 'Zephaniah', 3, 9, 'بيا به زۀ د خلقو خبرې پاکې کړم، چې هغوئ ټول د مالِک خُدائ نوم واخلى او اوږه په اوږه د هغۀ خِدمت وکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_009.mp3', NULL, 1761758917, 1761758917),
(41938, 'Zephaniah 3:10', 'Zephaniah', 3, 10, 'د ايتهوپيا د سيندونو بل طرف نه به زما عبادت کوونکى، زما خوارۀ وارۀ خلق، ما له نذرانې راوړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_010.mp3', NULL, 1761758917, 1761758917),
(41939, 'Zephaniah 3:11', 'Zephaniah', 3, 11, 'په هغه ورځ به تاسو د هغه ټولو خراب کارونو په وجه چې تاسو ما سره کړى دى ونۀ شرمېږئ، ځکه چې زۀ به د دې ښار نه هغه خلق لرې کړم چې په خپل غرور خوشحالۍ کوى. تۀ به بيا کله زما په مقدس غر غرور ونۀ کړې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_011.mp3', NULL, 1761758917, 1761758917),
(41940, 'Zephaniah 3:12', 'Zephaniah', 3, 12, 'خو زۀ به په تا کښې خاکساره او عاجز خويه خلق پرېږدم، څوک چې د مالِک خُدائ په نوم يقين کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_012.mp3', NULL, 1761758917, 1761758917),
(41941, 'Zephaniah 3:13', 'Zephaniah', 3, 13, 'د بنى اِسرائيلو ژوندى پاتې خلق به غلط کار نۀ کوى، هغوئ به دروغ نۀ وائى، او نۀ به د هغوئ په ژبه دوکه وى. هغوئ به خورى څښى او آرام به کوى او هيڅ څوک به هغوئ نۀ يروى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_013.mp3', NULL, 1761758917, 1761758917),
(41942, 'Zephaniah 3:14', 'Zephaniah', 3, 14, 'سندرې ووايه، اے د صيون لورې، په زوره چغې ووهه، اے بنى اِسرائيله. خوشحاله شه او په خپل پوره زړۀ سره خوشحالى وکړه، اے صيون لورې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_014.mp3', NULL, 1761758917, 1761758917),
(41943, 'Zephaniah 3:15', 'Zephaniah', 3, 15, 'مالِک خُدائ ستاسو سزا ختمه کړې ده، هغۀ ستاسو دشمنان واپس کړل. مالِک خُدائ، د اِسرائيل بادشاه، ستاسو مل دے، تاسو به بيا هيڅکله د څۀ نقصان نه نۀ يرېږئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_015.mp3', NULL, 1761758917, 1761758917),
(41944, 'Zephaniah 3:16', 'Zephaniah', 3, 16, 'په هغه ورځ به هغوئ يروشلم ته ووائى چې، ”يرېږه مه، اے صيونه، پرى نۀ ږدئ چې ستا لاسونه کمزورى پاتې شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_016.mp3', NULL, 1761758917, 1761758917),
(41945, 'Zephaniah 3:17', 'Zephaniah', 3, 17, 'مالِک خُدائ ستاسو خُدائ پاک ستاسو مل دے، هغه طاقتور دے او تاسو به بچ کړى. هغه به تاسو نه ډېر خوشحاله وى، هغه به تا په خپلې مينې خاموش کړى، هغه به په تا په سندرو سره خوشحالى وکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_017.mp3', NULL, 1761758917, 1761758917),
(41946, 'Zephaniah 3:18', 'Zephaniah', 3, 18, 'زۀ به هغوئ ستاسو نه لرې کړم څوک چې د مقرر شوى اخترونو په وجه غمژن وُو نو دا به نور ستاسو دپاره د شرم سبب نۀ وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_018.mp3', NULL, 1761758917, 1761758917),
(41947, 'Zephaniah 3:19', 'Zephaniah', 3, 19, 'په هغه وخت به زۀ معامله وکړم هغوئ ټولو سره چې په تا يې ظلم زياتے کړے دے، زۀ به ګوډيان بچ کړم او هغوئ به راغونډ کړم چې څوک خوارۀ وارۀ شوى دى. زۀ به هغوئ له عزت او جلال ورکړم، په هر مُلک کښې چرته چې دوئ رسوا شوى وُو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_019.mp3', NULL, 1761758917, 1761758917),
(41948, 'Zephaniah 3:20', 'Zephaniah', 3, 20, 'په هغه وخت به زۀ تاسو راغونډ کړم، په هغه وخت به زۀ تاسو خپلو کورونو ته راولم. زۀ به تاسو ته د دُنيا په ټولو خلقو کښې عزت او جلال درکړم، زۀ به تاسو ستاسو د خپلو سترګو د وړاندې بيا آباد کړم،“ مالِک خُدائ فرمائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/zephaniah3_verse_020.mp3', NULL, 1761758917, 1761758917),
(41949, 'Jeremiah 36:1', 'Jeremiah', 36, 1, 'په يهوداه کښې د يهويقيم د يوسياه د زوئ د بادشاهۍ په څلورم کال، مالِک خُدائ يرمياه ته پېغام ورکړو چې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_001.mp3', NULL, 1761758917, 1761758917),
(41950, 'Jeremiah 36:2', 'Jeremiah', 36, 2, '”يو طومار راواخله او په هغې زما ټول کلام کوم چې ما درته د يهوداه، د اِسرائيل او د ټولو قومونو په خلاف د يوسياه د بادشاهۍ د وخت نه تر اوسه پورې نازل کړے دے وليکه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_002.mp3', NULL, 1761758917, 1761758917),
(41951, 'Jeremiah 36:3', 'Jeremiah', 36, 3, 'شايد چې د يهوداه خلق د هغه ټولو افتونو په حقله واورى کوم چې زما په هغوئ د راوستلو نيت دے، نو کۀ هر يو د خپلې بدعملۍ نه راوګرځى نو بيا به زۀ د هغوئ ګناهونه او بدعملونه معاف کړم.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_003.mp3', NULL, 1761758917, 1761758917),
(41952, 'Jeremiah 36:4', 'Jeremiah', 36, 4, 'نو بيا يرمياه باروک د نيرياه زوئ راوغوښتلو، او کله چې يرمياه هغۀ ته هغه هر څۀ ووئيل کوم چې مالِک خُدائ هغۀ ته فرمائيلى وُو، نو باروک هغه په يو طومار کښې وليکل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_004.mp3', NULL, 1761758917, 1761758917),
(41953, 'Jeremiah 36:5', 'Jeremiah', 36, 5, 'نو بيا يرمياه باروک ته وفرمائيل چې، ”زۀ دلته نظر بند يم نو د مالِک خُدائ کور ته دننه تلے نۀ شم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_005.mp3', NULL, 1761758917, 1761758917),
(41954, 'Jeremiah 36:6', 'Jeremiah', 36, 6, 'نو بيا تاسو د مالِک خُدائ کور ته کله چې روژه وى لاړ شئ او خلقو ته هغه څۀ ولولئ کوم چې ما تاسو ته وفرمائيل او تاسو هغه په يو طومار کښې وليکل. دا د يهوداه ټولو هغه خلقو ته ولوله کوم چې د خپلو ښارونو نه د عبادت دپاره دلته راغلى وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_006.mp3', NULL, 1761758917, 1761758917),
(41955, 'Jeremiah 36:7', 'Jeremiah', 36, 7, 'شايد چې هغوئ مالِک خُدائ ته عرض او مِنت زارى وکړى او ټول د خپلو بدو لارو نه راوګرځى، ځکه چې د مالِک خُدائ قهر او غضب ډېر لوئ دے کوم چې يې د دې خلقو خلاف اعلان کړے دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_007.mp3', NULL, 1761758917, 1761758917),
(41956, 'Jeremiah 36:8', 'Jeremiah', 36, 8, 'باروک د نيرياه زوئ هم هغه شان وکړل څنګه چې ورته يرمياه نبى حکم کړے وو، نو د هغه طومار نه يې د مالِک خُدائ کلام د مالِک خُدائ په کور کښې ولوستلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_008.mp3', NULL, 1761758917, 1761758917),
(41957, 'Jeremiah 36:9', 'Jeremiah', 36, 9, 'يهويقيم د يوسياه زوئ د يهوداه بادشاه د بادشاهۍ د پينځم کال په نهمه مياشت د يروشلم ټولو خلقو ته او د هغوئ دپاره څوک چې د يهوداه د ښارونو نه راغلى وُو، د روژې اعلان وکړو او هغوئ د مالِک خُدائ دپاره روژه ونيوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_009.mp3', NULL, 1761758917, 1761758917),
(41958, 'Jeremiah 36:10', 'Jeremiah', 36, 10, 'د مالِک خُدائ په کور کښې د ګمرياه د سافن زوئ منشى د کوټې نه، کومه چې د دربار په بره حِصه کښې وه او د مالِک خُدائ د کور د داخلېدو د نوې دروازې سره نزدې وه، باروک ټولو خلقو ته چې هلته موجود وُو د يرمياه کلام د طومار نه تلاوت کړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_010.mp3', NULL, 1761758917, 1761758917),
(41959, 'Jeremiah 36:11', 'Jeremiah', 36, 11, 'کله چې ميکاياه د ګمرياه زوئ او د سافن نمسى د مالِک خُدائ کلام د طومار نه واورېدو،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_011.mp3', NULL, 1761758917, 1761758917),
(41960, 'Jeremiah 36:12', 'Jeremiah', 36, 12, 'نو هغه په شاهى محل کښې لاندې د منشى کوټې ته لاړو، چرته چې ټول آفسران ناست وُو. اليسمع، د دربار منشى، د سمعياه زوئ دلاياه، د عکبور زوئ الناتن، د سافن زوئ ګمرياه، د حننياه زوئ صدقياه او نور ټول آفسران هلته موجود وُو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_012.mp3', NULL, 1761758917, 1761758917),
(41961, 'Jeremiah 36:13', 'Jeremiah', 36, 13, 'نو ميکاياه هغوئ ته هغه هر څۀ ووئيل څۀ چې باروک خلقو ته د طومار نه بيانول او هغۀ ترې اورېدلى وُو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_013.mp3', NULL, 1761758917, 1761758917),
(41962, 'Jeremiah 36:14', 'Jeremiah', 36, 14, 'نو ټولو آفسرانو په مشورې سره يهودى د نتنياه زوئ، د شلمياه نمسى او د کوشى کړوسے باروک ته ورولېږلو چې ورته دا ووائى، ”آفسران وائى چې راشه، او ځان سره هغه طومار هم راوړه کوم چې تا ټولو خلقو ته ولوستلو.“ نو باروک د نيرياه زوئ د هغه طومار سره چې کوم يې په لاس کښې وو هغوئ له ورغلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_014.mp3', NULL, 1761758917, 1761758917),
(41963, 'Jeremiah 36:15', 'Jeremiah', 36, 15, 'نو هغوئ هغۀ ته ووئيل چې، ”مهربانى وکړه دلته کښېنه او مونږ ته دا طومار ولوله.“ نو باروک ورته هغه طومار ولوستلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_015.mp3', NULL, 1761758917, 1761758917),
(41964, 'Jeremiah 36:16', 'Jeremiah', 36, 16, 'نو کله چې هغوئ دا کلام واورېدو، نو بيا هغوئ يو بل ته يرې سره کتل او باروک ته يې ووئيل چې، ”مونږ به ضرور بادشاه د دې ټول کلام نه خبر کړُو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_016.mp3', NULL, 1761758917, 1761758917),
(41965, 'Jeremiah 36:17', 'Jeremiah', 36, 17, 'نو بيا هغوئ د باروک نه تپوس وکړو چې، ”تۀ مونږ ته دا ووايه چې دا هر څۀ تا څنګه وليکل؟ آيا يرمياه نبى تا ته وفرمائيل او تا وليکل؟“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_017.mp3', NULL, 1761758917, 1761758917),
(41966, 'Jeremiah 36:18', 'Jeremiah', 36, 18, 'باروک ورته جواب ورکړو چې، ”آو، هغۀ دا هر څۀ ما ته وفرمائيل او ما هغه په دې طومار کښې په سياهۍ باندې وليکل.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_018.mp3', NULL, 1761758917, 1761758917),
(41967, 'Jeremiah 36:19', 'Jeremiah', 36, 19, 'نو آفسرانو باروک ته ووئيل چې، ”تۀ او يرمياه لاړ شئ او خپل ځان پټ کړئ. او هيچا ته مۀ وايئ چې تاسو چرته يئ.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_019.mp3', NULL, 1761758917, 1761758917),
(41968, 'Jeremiah 36:20', 'Jeremiah', 36, 20, 'نو بيا آفسرانو هغه طومار د دربار د منشى اليسمع په کوټه کښې کېښودو، نو بيا هغوئ د بادشاه دربار ته لاړل او د دې ټول کلام نه يې بادشاه خبر کړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_020.mp3', NULL, 1761758917, 1761758917),
(41969, 'Jeremiah 36:21', 'Jeremiah', 36, 21, 'نو بادشاه يهودى نومې سړے ورولېږلو چې هغه طومار راوړى، نو يهودى هغه د اليسمع منشى د کوټې نه راوړو او بادشاه او هغه ټولو آفسرانو ته چې ورسره په خوا کښې ولاړ وُو ولوستلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_021.mp3', NULL, 1761758917, 1761758917),
(41970, 'Jeremiah 36:22', 'Jeremiah', 36, 22, 'نو د کال نهمه مياشت وه، د يخنۍ موسم وو نو بادشاه په شاهى محل کښې د ژمى دپاره په جوړه شوې کوټه کښې نغرى ته ناست وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_022.mp3', NULL, 1761758917, 1761758917),
(41971, 'Jeremiah 36:23', 'Jeremiah', 36, 23, 'هرکله چې يهودى درې څلور عنوانونه ولوستل، نو بادشاه دا طومار په چاقو وشلولو او هغه يې په نغرى کښې اور ته واچولو، تر دې چې هغه طومار ټول په اور کښې وسوزېدو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_023.mp3', NULL, 1761758917, 1761758917),
(41972, 'Jeremiah 36:24', 'Jeremiah', 36, 24, 'بادشاه او د هغۀ ټولو خِدمتګارانو چا چې دا کلام واورېدو هغوئ ونۀ يرېدل او نۀ يې د غم نه جامې وشلولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_024.mp3', NULL, 1761758917, 1761758917),
(41973, 'Jeremiah 36:25', 'Jeremiah', 36, 25, 'کۀ څۀ هم چې الناتن، دلاياه او ګمرياه بادشاه ته مِنتُونه کول چې طومار مۀ سوزوه خو هغۀ د هغوئ خبرې ته غوږ ونۀ نيولو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_025.mp3', NULL, 1761758917, 1761758917),
(41974, 'Jeremiah 36:26', 'Jeremiah', 36, 26, 'نو بيا د دې په ځائ بادشاه يرحمئيل شهزاده او ورسره سراياه د عزرائيل زوئ او شلمياه د عبدائيل زوئ ته حکم وکړو چې باروک منشى او يرمياه نبى ګرفتار کړى. خو مالِک خُدائ هغوئ پټ کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_026.mp3', NULL, 1761758917, 1761758917),
(41975, 'Jeremiah 36:27', 'Jeremiah', 36, 27, 'کله چې يهويقيم هغه طومار وسوزولو چې په کښې هغه الفاظ وُو کوم چې باروک ته يرمياه فرمائيلى وُو او هغۀ ليکلى وُو، نو د مالِک خُدائ کلام په يرمياه نازل شو او ورته يې وفرمائيل چې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_027.mp3', NULL, 1761758917, 1761758917),
(41976, 'Jeremiah 36:28', 'Jeremiah', 36, 28, '”يو بل طومار راواخله او په هغې کښې هغه هر څۀ وليکه څۀ چې په اول طومار کښې ليکلے شوى وُو کوم چې يهويقيم د يهوداه بادشاه وسوزولو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_028.mp3', NULL, 1761758917, 1761758917),
(41977, 'Jeremiah 36:29', 'Jeremiah', 36, 29, 'نو همدارنګه يهويقيم د يهوداه بادشاه ته ووايه، مالِک خُدائ داسې فرمائى چې، تا دا طومار وسوزولو او يرمياه ته دې وئيل چې، تا ولې په دې کښې دا ليکلى دى چې په يقين سره به د بابل بادشاه راشى او په حقيقت کښې به دا مُلک تباه کړى او انسان او ځناور داوړه به په کښې جارُو کړى؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_029.mp3', NULL, 1761758917, 1761758917),
(41978, 'Jeremiah 36:30', 'Jeremiah', 36, 30, 'نو په دې وجه مالِک خُدائ د يهويقيم د يهوداه بادشاه په حقله فرمائى چې، د هغۀ په اولاد کښې به څوک هم د داؤد په تخت بادشاهى ونۀ کړى، او د هغۀ لاش به په خوشى مېدان وغورزولے شى چرته چې په ورځ کښې به نمر او په شپه کښې به سختې يخنۍ او پرخې ته پروت وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_030.mp3', NULL, 1761758917, 1761758917),
(41979, 'Jeremiah 36:31', 'Jeremiah', 36, 31, 'زۀ به هغۀ ته او د هغۀ اولاد او د هغۀ نوکرانو ته د هغوئ د غلطو کارونو په وجه سزا ورکړم، زۀ به په دوئ او په هغه چا باندې چې په يروشلم کښې اوسيږى او د يهوداه په ټولو خلقو به هغه افتونه راولم کوم چې ما د هغوئ خلاف اعلان کړى دى، ځکه چې هغوئ ما ته غوږ ونۀ نيولو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_031.mp3', NULL, 1761758917, 1761758917),
(41980, 'Jeremiah 36:32', 'Jeremiah', 36, 32, 'بيا يرمياه يو بل تش طومار راواخستلو او باروک ليکوال د نيرياه زوئ له يې ورکړو، نو څنګه به چې يرمياه فرمائيل نو هغه ټول الفاظ يې په کښې دوباره وليکل کوم چې په هغه طومار کښې ليکلے شوى وُو چې يهويقيم د يهوداه بادشاه په اور کښې اچولے او سوزولے وو. او د هغې نه علاوه يې نوره هم په دې موضوع رڼا واچوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah36_verse_032.mp3', NULL, 1761758917, 1761758917),
(41981, 'Daniel 2:1', 'Daniel', 2, 1, 'د خپلې بادشاهۍ په دوېم کال، نبوکدنضر داسې خوبونه وليدل چې د هغۀ سوچ يې ګډ‌وډ کړو، او هغۀ ته بيا خوب نۀ ورتلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_001.mp3', NULL, 1761758917, 1761758917),
(41982, 'Daniel 2:2', 'Daniel', 2, 2, 'نو بيا بادشاه جادوګر، فالګر، کوډګر او نجوميان راوغوښتل چې هغۀ ته ووائى چې هغۀ څۀ خوب ليدلے دے. هر کله چې هغوئ راغلل او د بادشاه په وړاندې ودرېدل،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_002.mp3', NULL, 1761758917, 1761758917),
(41983, 'Daniel 2:3', 'Daniel', 2, 3, 'هغۀ دوئ ته ووئيل، ”ما يو خوب ليدلے دے کوم چې زۀ ډېر پرېشانه کړے يم او زۀ غواړم چې په دې پوهه شم چې د دې خوب څۀ مطلب دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_003.mp3', NULL, 1761758917, 1761758917),
(41984, 'Daniel 2:4', 'Daniel', 2, 4, 'نو بيا نجوميانو هغۀ ته په آرامى ژبه کښې ووئيل چې، ”بادشاه سلامت دې تر ابده ژوندے وى. خپلو خادِمانو ته دې خپل خوب بيان کړه، نو مونږ به د هغې تعبير تاسو ته ووايو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_004.mp3', NULL, 1761758917, 1761758917),
(41985, 'Daniel 2:5', 'Daniel', 2, 5, 'خو بادشاه نجوميانو ته ووئيل، ”ما دا پخه فېصله کړې ده، کۀ چرې تاسو ما ته دا ونۀ وايئ چې زما خوب څنګه وو او تعبير يې نۀ کړئ، نو زۀ به تاسو ټوټه ټوټه کړم او ستاسو کورونه به د خاورو په ډېرو بدل کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_005.mp3', NULL, 1761758917, 1761758917),
(41986, 'Daniel 2:6', 'Daniel', 2, 6, 'خو کۀ تاسو ما ته زما خوب ووايئ او بيا د هغې تعبير راته ووايئ، نو زۀ به تاسو ته تحفې، انعامونه او لوئ عزت درکړم. اوس تاسو ما ته زما خوب ووايئ او هغه راته تعبير کړئ.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_006.mp3', NULL, 1761758917, 1761758917),
(41987, 'Daniel 2:7', 'Daniel', 2, 7, 'نو يو ځل بيا هغوئ هغۀ ته ووئيل، ”بادشاه دې خپلو خادِمانو ته خپل خوب بيان کړى، او مونږ به يې تعبير کړُو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_007.mp3', NULL, 1761758917, 1761758917),
(41988, 'Daniel 2:8', 'Daniel', 2, 8, 'نو بيا بادشاه هغوئ ته په جواب کښې ووئيل، ”زۀ په دې يقين لرم چې تاسو د وخت نه فائده اخلئ، ځکه چې تاسو په دې پوهه شئ چې دا زما پخه فېصله ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_008.mp3', NULL, 1761758917, 1761758917),
(41989, 'Daniel 2:9', 'Daniel', 2, 9, 'کۀ چرې تاسو ما ته زما خوب ونۀ وايئ، نو بيا تاسو دپاره صرف يوه سزا ده. تاسو دا صلاح کړې ده چې ما ګمراه کړئ او راته دروغ ووايئ او ما دوکه کړئ، او تاسو دا اُميد ساتئ چې زما سوچ به بدل شى. نو بيا تاسو ما ته زما خوب ووايئ، او بيا زۀ به په دې پوهه شم چې تاسو يې ما ته تعبير هم راکولے شئ.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_009.mp3', NULL, 1761758917, 1761758917),
(41990, 'Daniel 2:10', 'Daniel', 2, 10, 'نجوميانو بادشاه ته په جواب کښې ووئيل، ”په زمکه داسې هيڅ څوک نشته چې د بادشاه په دې خبره عمل وکړى. تر اوسه پورې داسې نۀ دى شوى چې يو بادشاه د خپل فالګر، جادوګر يا نجومى نه داسې تپوس کړے وى، کۀ هغه بادشاه هر څومره لوئ او طاقتور وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_010.mp3', NULL, 1761758917, 1761758917),
(41991, 'Daniel 2:11', 'Daniel', 2, 11, 'بادشاه سلامت تاسو چې څۀ غواړئ هغه يو ناممکن کار دے. دا بادشاه ته د هغۀ د معبودانو نه بغېر هيڅ څوک نۀ شى څرګندولے، او هغوئ د انسانانو سره نۀ اوسيږى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_011.mp3', NULL, 1761758917, 1761758917),
(41992, 'Daniel 2:12', 'Daniel', 2, 12, 'بادشاه چې کله دا واورېدل نو په دې هغه ډېر زيات په قهر شو او حکم يې وکړو چې د بابل ټول هوښياران او پوهان دې قتل کړے شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_012.mp3', NULL, 1761758917, 1761758917),
(41993, 'Daniel 2:13', 'Daniel', 2, 13, 'نو بيا د هوښيارانو د قتلولو حکم جارى شو، او د دانيال او د هغۀ ملګرو پسې يې هم کسان ورولېږل چې هغوئ قتل کړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_013.mp3', NULL, 1761758917, 1761758917),
(41994, 'Daniel 2:14', 'Daniel', 2, 14, 'هرکله چې اريوک د بادشاه د محافظانو مشر، د بابل د هوښيارانو قتلولو پسې ووتو نو دانيال په ډېر هوښيارتيا او تميز د هغۀ سره خبرې وکړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_014.mp3', NULL, 1761758917, 1761758917),
(41995, 'Daniel 2:15', 'Daniel', 2, 15, 'هغۀ د بادشاه د آفسر نه تپوس وکړو چې، ”بادشاه دومره سخت فرمان ولې جارى کړے دے؟“ بيا د بادشاه آفسر اريوک دانيال ته ټوله قيصه بيان کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_015.mp3', NULL, 1761758917, 1761758917),
(41996, 'Daniel 2:16', 'Daniel', 2, 16, 'نو په دې اورېدو سره دانيال سمدستى بادشاه له ورغلو او د هغۀ نه يې وخت وغوښتلو، چې دے به ورته د خوب تعبير ورکړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_016.mp3', NULL, 1761758917, 1761758917),
(41997, 'Daniel 2:17', 'Daniel', 2, 17, 'نو بيا دانيال خپل کور ته واپس لاړو او ټوله قيصه يې خپلو ملګرو حننياه، ميشائيل، او عزرياه ته بيان کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_017.mp3', NULL, 1761758917, 1761758917),
(41998, 'Daniel 2:18', 'Daniel', 2, 18, 'هغۀ دوئ ته خواست وکړو چې آسمانى خُدائ پاک ته د دې راز د څرګندولو په حقله د رحم سوال وکړئ، نو چې دے، د دۀ دوستان او د بابل نور هوښياران قتل نۀ شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_018.mp3', NULL, 1761758917, 1761758917),
(41999, 'Daniel 2:19', 'Daniel', 2, 19, 'په هم هغه شپه دا راز په رويا کښې دانيال ته څرګند شو. نو بيا دانيال د آسمانى خُدائ پاک ثناء صِفت بيان کړو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_019.mp3', NULL, 1761758917, 1761758917),
(42000, 'Daniel 2:20', 'Daniel', 2, 20, 'او هغۀ وفرمائيل چې، ”د خُدائ پاک نوم ته دې د تل دپاره ثناء صِفت وى، حکمت او قدرت د هغۀ دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_020.mp3', NULL, 1761758917, 1761758917),
(42001, 'Daniel 2:21', 'Daniel', 2, 21, 'هغه وختونه او حالات بدلوى، هغه بادشاهان په تخت کښېنوى او هغوئ اخوا کوى. هغه پوهانو له پوهه او عالمانو له عِلم ورکوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_021.mp3', NULL, 1761758917, 1761758917),
(42002, 'Daniel 2:22', 'Daniel', 2, 22, 'هغه ژور او پټ د راز څيزونه څرګندوى، هغه ترې خبر دے څۀ چې په تيارۀ کښې پراتۀ دى، او د هغۀ نه ګېرچاپېره نُور دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_022.mp3', NULL, 1761758917, 1761758917),
(42003, 'Daniel 2:23', 'Daniel', 2, 23, 'زۀ ستا ثناء صِفت او شُکر ګزارى کوم، اے زما د پلار نيکۀ پاکه خُدايه. ځکه چې تا ما له پوهه او قدرت راکړے دے. تا ما ته هغه څۀ وښودل د څۀ چې مونږ ستا نه غوښتنه وکړه، تا ما ته د بادشاه خوب او د هغۀ مسئله څرګنده کړه.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_023.mp3', NULL, 1761758917, 1761758917),
(42004, 'Daniel 2:24', 'Daniel', 2, 24, 'نو بيا دانيال اريوک له لاړو، څوک چې بادشاه د بابل د هوښيارانو د قتلولو دپاره مقرر کړے وو، ”د بابل هوښيار خلق مۀ قتلوه. ما بادشاه له بوځه، او زۀ به د هغۀ خوب تعبير هغۀ ته ورکړم.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_024.mp3', NULL, 1761758917, 1761758917),
(42005, 'Daniel 2:25', 'Daniel', 2, 25, 'نو اريوک سمدستى دانيال بادشاه له بوتلو او هغۀ بادشاه ته ووئيل، ”ما د يهوداه په جلاوطنو خلقو کښې يو کس پېدا کړو څوک به چې بادشاه ته د هغۀ د خوب مطلب ووائى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_025.mp3', NULL, 1761758917, 1761758917),
(42006, 'Daniel 2:26', 'Daniel', 2, 26, 'بادشاه دانيال نه تپوس وکړو، چا ته به يې چې بيلطشضر وئيل، ”آيا تۀ ما ته دا وئيلے شې چې ما څنګه خوب ليدلے دے او د هغې تعبير کولے شې؟“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_026.mp3', NULL, 1761758917, 1761758917),
(42007, 'Daniel 2:27', 'Daniel', 2, 27, 'دانيال جواب ورکړو، ”د کوم راز چې بادشاه تپوس کوى هغه هيڅ يو هوښيار، فالګر، جادوګر، او نجومى نۀ شى کولے چې هغه راز بيان کړى،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_027.mp3', NULL, 1761758917, 1761758917),
(42008, 'Daniel 2:28', 'Daniel', 2, 28, 'خو په آسمان کښې يو خُدائ پاک موجود دے څوک چې پټ رازونه څرګندوى، هغۀ چې نبوکدنضر بادشاه ته په خوب کښې ښودلى دى چې په راتلونکو ورځو کښې به څۀ پېښ شى. کله چې تۀ په خپل کټ کښې پروت وې او کوم خوب او رويا چې تا وليدله او ستا په ذهن کښې هغه تيره شوې ده هغه څۀ داسې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_028.mp3', NULL, 1761758917, 1761758917),
(42009, 'Daniel 2:29', 'Daniel', 2, 29, 'اے بادشاه سلامت کله چې تۀ هلته پروت وې، نو ستا فکر او سوچ د راتلونکو حالاتو طرف ته واوړېدو، او د رازونو ښکاره کوونکى درته دا وښودل چې په آئنده کښې به څۀ کيږى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_029.mp3', NULL, 1761758917, 1761758917),
(42010, 'Daniel 2:30', 'Daniel', 2, 30, 'دا کوم راز چې ما ته څرګند شو، د دې دا مطلب نۀ دے چې ګنې زۀ دې د نورو کسانو نه ډېر هوښيار يم، خو دا د دې دپاره چې تۀ، اے بادشاه سلامت، د دې راز په تعبير باندې کوم چې ستا په خيال کښې تير شو پوهه شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_030.mp3', NULL, 1761758917, 1761758917),
(42011, 'Daniel 2:31', 'Daniel', 2, 31, 'اے بادشاه سلامت تا په خوب کښې وليدل چې يوه لويه ځلېدونکې او حېرانوونکې مجسمه ستا په وړاندې ولاړه وه او هغه يروونکې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_031.mp3', NULL, 1761758917, 1761758917),
(42012, 'Daniel 2:32', 'Daniel', 2, 32, 'د دې مجسمې سر د خالصو سرو زرو نه جوړ شوے وو، د هغۀ سينه او لاسونه د سپينو زرو نه، د هغۀ ګېډه او پتونونه د زېړو نه جوړ وُو،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_032.mp3', NULL, 1761758917, 1761758917),
(42013, 'Daniel 2:33', 'Daniel', 2, 33, 'د دې پنډۍ د اوسپنې، او د پښو څۀ حِصه د اوسپنې او څۀ حِصه د پخې شوې خاورې نه جوړه شوې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_033.mp3', NULL, 1761758917, 1761758917),
(42014, 'Daniel 2:34', 'Daniel', 2, 34, 'هرکله چې تا دې ته کتل، نو په دې وخت کښې د غرۀ نه يو لوئ کاڼے په خپله راجدا شو، خو د انسان په لاسونو نه. هغه د هغه مجسمې په پښو راپرېوتو کومې چې د اوسپنې او خاورو نه جوړې شوې وې او هغه يې ټوټه ټوټه کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_034.mp3', NULL, 1761758917, 1761758917),
(42015, 'Daniel 2:35', 'Daniel', 2, 35, 'نو بيا اوسپنه، خاوره، زېړ، سپين زر او سرۀ زر ټول ټوټه ټوټه شو او داسې والوتل لکه څنګه چې په اوړى کښې بوس د غنمو په درمند کښې الوځى. هوا هغه ټول يوړل او هيڅ نښه يې پاتې نۀ شوه. خو هغه کاڼى کوم چې دا مجسمه وويشته هغې نه يو لوئ غر جوړ شو او ټوله زمکه يې ونيوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_035.mp3', NULL, 1761758917, 1761758917),
(42016, 'Daniel 2:36', 'Daniel', 2, 36, 'دا ستا خوب وو، او زۀ به يې اوس تعبير هم درته بيان کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_036.mp3', NULL, 1761758917, 1761758917),
(42017, 'Daniel 2:37', 'Daniel', 2, 37, 'تاسو، اے بادشاه سلامت، د ټولو بادشاهانو نه لوئ بادشاه يئ. آسمانى خُدائ پاک درته بادشاهى او قدرت، زور شان او شوکت درکړے دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_037.mp3', NULL, 1761758917, 1761758917),
(42018, 'Daniel 2:38', 'Daniel', 2, 38, 'هغۀ ستا لاسونو ته ټول انسانان او ځناور او د هوا مارغان حواله کړى دى. چرته چې هم دوئ اوسيږى، هغۀ تۀ په هغوئ ټولو حکمران مقرر کړے يې. او هغه د سرو زرو سر تۀ په خپله يې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_038.mp3', NULL, 1761758917, 1761758917),
(42019, 'Daniel 2:39', 'Daniel', 2, 39, 'ستا نه وروستو، به يوه بله بادشاهى قائمه شى چې ستا د بادشاهۍ نه به کمزورې وى، او بيا به درېمه بادشاهى راشى، د زېړو به وى، او دا به په ټوله زمکه حکمرانى وکړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_039.mp3', NULL, 1761758917, 1761758917),
(42020, 'Daniel 2:40', 'Daniel', 2, 40, 'په آخر کښې به بيا څلورمه بادشاهى راشى چې د اوسپنې په شان به مضبوطه وى ځکه چې اوسپنه هر څۀ ماتوى او ټوټه ټوټه کوى، نو بيا څنګه چې اوسپنه څيزونه ټوټه ټوټه کوى نو داسې به هغه نور ټول مات او ټوټه ټوټه کړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_040.mp3', NULL, 1761758917, 1761758917),
(42021, 'Daniel 2:41', 'Daniel', 2, 41, 'لکه څنګه چې تا وليدل چې د هغې د پښو او ګوتو څۀ حِصه د اوسپنې او څۀ حِصه د پخې خاورې نه جوړه وه نو دا به جدا شوے بادشاهت وى، خو بيا به هم په کښې څۀ نا څۀ د اوسپنې زور پاتې وى، څنګه چې تا اوسپنه خاورې سره يوځائ وليدله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_041.mp3', NULL, 1761758917, 1761758917),
(42022, 'Daniel 2:42', 'Daniel', 2, 42, 'کۀ څۀ هم چې تا وليدل چې اوسپنه د خټې سره ګډه شوې وه، نو بيا به د دې بادشاهۍ څۀ حِصه طاقتوره او څۀ حِصه کمزورى وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_042.mp3', NULL, 1761758917, 1761758917),
(42023, 'Daniel 2:43', 'Daniel', 2, 43, 'تاسو وليدل چې اوسپنه د خاورې سره يوځائ شوې وه، نو بيا به دغه شان د هغه بادشاهۍ خلق هم کوشش وکړى چې د يو بل سره په وادۀ کولو د يو بل ملاتړ جوړ شى، خو دوئ به په خپلو کښې په اتفاق نۀ شى لکه څنګه چې اوسپنه د خاورو سره يوځائ کېدلے نۀ شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_043.mp3', NULL, 1761758917, 1761758917),
(42024, 'Daniel 2:44', 'Daniel', 2, 44, 'د هغه بادشاهانو په زمانه کښې، به آسمانى خُدائ پاک داسې بادشاهى راولى چې هغه به هيڅکله نۀ ختميږى، نۀ به دا بل قوم نيولے شى. هغه به دا ټول بادشاهتونه مات کړى او ختم به يې کړى، خو دا به د تل دپاره پاتې شى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_044.mp3', NULL, 1761758917, 1761758917),
(42025, 'Daniel 2:45', 'Daniel', 2, 45, 'دا د غرۀ نه د کاڼى د راجدا کېدلو د رويا تعبير دے، خو د انسانانو په لاسونو نه، هغه کاڼى چې اوسپنه، زېړ، خاوره، سپين زر او سرۀ زر يې ټوټه کړل. لوئ خُدائ پاک بادشاه ته دا ښودلى دى چې په راتلونکى وخت کښې به څۀ کيږى. دا خوب رښتيا او تعبير يې باورى دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_045.mp3', NULL, 1761758917, 1761758917),
(42026, 'Daniel 2:46', 'Daniel', 2, 46, 'نو بيا نبوکدنضر بادشاه د دانيال په وړاندې ټيټ شو او د هغۀ عزت يې وکړو او حکم يې وکړو چې هغۀ ته د غلو دانو او د خوشبو نذرانې وړاندې کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_046.mp3', NULL, 1761758917, 1761758917),
(42027, 'Daniel 2:47', 'Daniel', 2, 47, 'بادشاه دانيال ته ووئيل، ”بې‌شکه ستا خُدائ پاک د ټولو معبودانو خُدائ پاک دے او د بادشاهانو مالِک دے او د رازونو ښکاره کوونکے دے. ځکه چې تا ته دا راز څرګند کړے شو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_047.mp3', NULL, 1761758917, 1761758917),
(42028, 'Daniel 2:48', 'Daniel', 2, 48, 'بيا بادشاه دانيال ته لوئ مقام ورکړو، او ډيرې او ښکلې تحفې يې ورکړې. بادشاه هغه د بابل په ټوله صوبه باندې حکمران او د ټولو هوښيارانو مشر مقرر کړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_048.mp3', NULL, 1761758917, 1761758917),
(42029, 'Daniel 2:49', 'Daniel', 2, 49, 'نو د دانيال په خواست سره بادشاه شدرک، ميشک، او عبدنجو د بابل د صوبې په انتظاميه کښې آفسران مقرر کړل، او په خپله دانيال په شاهى دربار کښې پاتې شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/daniel2_verse_049.mp3', NULL, 1761758917, 1761758917),
(42030, 'Deuteronomy 14:1', 'Deuteronomy', 14, 1, 'تاسو د خپل څښتن خدای اولادونه یئ. نو کله چې د مړو دپاره ژاړئ، خپل ځانونه مه غوڅوئ یا د خپل تندي ویښتان مه خرایئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_001.mp3', NULL, 1761758917, 1761758917),
(42031, 'Deuteronomy 14:2', 'Deuteronomy', 14, 2, 'تاسو د خپل څښتن خدای یئ، هغه د هغو ټولو قومونو څخه چې د ځمکې په مخ باندې ژوند کوي، تاسو د خپل قوم په توګه غوره کړي یئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_002.mp3', NULL, 1761758917, 1761758917),
(42032, 'Deuteronomy 14:3', 'Deuteronomy', 14, 3, 'هېڅ داسې شیان مه خورئ چې څښتن هغه حرام اعلان کړي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_003.mp3', NULL, 1761758917, 1761758917),
(42033, 'Deuteronomy 14:4', 'Deuteronomy', 14, 4, 'تاسو کولای شئ چې د دغو حیواناتو غوښه وخورئ: غویان، پسونه، وزې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_004.mp3', NULL, 1761758917, 1761758917),
(42034, 'Deuteronomy 14:5', 'Deuteronomy', 14, 5, 'هر ډول هوسۍ، غرني پسونه، ځنګلي وزې یا غرڅې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_005.mp3', NULL, 1761758917, 1761758917),
(42035, 'Deuteronomy 14:6', 'Deuteronomy', 14, 6, 'یعنې هر هغه حیوان چې خلاص سوم ولري او شخوند هم وهي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_006.mp3', NULL, 1761758917, 1761758917),
(42036, 'Deuteronomy 14:7', 'Deuteronomy', 14, 7, 'خو د هېڅ داسې حیوان غوښه باید ونه خوړل شي چې خلاص سومان نه لري او شخوند نه وهي. تاسو باید د اوښانو، سویو، یا د غرنیو سویو غوښه ونه خورئ. هغه باید ناپاک وګڼل شي، هغه شخوند وهي، خو خلاص سومان نه لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_007.mp3', NULL, 1761758917, 1761758917),
(42037, 'Deuteronomy 14:8', 'Deuteronomy', 14, 8, 'د خوګ غوښه مه خورئ. خوګ باید ناپاکه وګڼل شي، هغه خلاص سومان لري، خو شخوند نه وهي. د دغو حیواناتو غوښه مه خورئ او حتی د هغو مړو ته هم لاس مه وروړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_008.mp3', NULL, 1761758917, 1761758917),
(42038, 'Deuteronomy 14:9', 'Deuteronomy', 14, 9, 'تاسو کولای شئ هر ډول ماهیان چې وزرونه او پتري ولري وخورئ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_009.mp3', NULL, 1761758917, 1761758917),
(42039, 'Deuteronomy 14:10', 'Deuteronomy', 14, 10, 'خو بل داسې شی چې په اوبو کې ژوند کوي او وزرونه او پتري ونه لري خوړل یې روا نه دي، هغه باید ناپاک وګڼل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_010.mp3', NULL, 1761758917, 1761758917),
(42040, 'Deuteronomy 14:11', 'Deuteronomy', 14, 11, 'تاسو کولای شئ چې هر ډول پاک مرغان وخورئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_011.mp3', NULL, 1761758917, 1761758917),
(42041, 'Deuteronomy 14:19', 'Deuteronomy', 14, 19, 'ټول وزر لرونکي حشرات ناپاک دي، هغه مه خورئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_019.mp3', NULL, 1761758917, 1761758917),
(42042, 'Deuteronomy 14:20', 'Deuteronomy', 14, 20, 'تاسو کولای شئ چې هر ډول پاک حشرات وخورئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_020.mp3', NULL, 1761758917, 1761758917),
(42043, 'Deuteronomy 14:21', 'Deuteronomy', 14, 21, 'د داسې حیوان غوښه مه خورئ چې په خپل مرګ مړ شوی وي. تاسو کولای شئ چې دا هغو پردیو خلکو ته چې ستاسو په منځ کې اوسیږي، ورکړئ چې ویې خوري یا تاسو کولای شئ چې په نورو پردیو خلکو باندې یې خرڅه کړئ. خو تاسو د خپل څښتن خدای یئ، تاسو د هغه قوم یئ. یو سېرلی د خپلې مور په شیدو کې مه پخوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_021.mp3', NULL, 1761758917, 1761758917),
(42044, 'Deuteronomy 14:22', 'Deuteronomy', 14, 22, 'تاسو باید هر کال د خپلو پټیو د ټولو حاصلاتو لسمه برخه بېله کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_022.mp3', NULL, 1761758917, 1761758917),
(42045, 'Deuteronomy 14:23', 'Deuteronomy', 14, 23, 'بیا هغه ځای ته لاړ شئ چې ستاسو څښتن خدای به یې د خپل عبادت دپاره غوره کړي او هلته د هغه په حضور کې د خپلو غلو دانو، شرابو او زیتونو د تېلو عشر او د خپلو پادو او رمو لومړني زېږېدلي بچیان وخورئ. دا کار وکړئ ترڅو د تل دپاره خپل څښتن خدای ته درناوی کول زده کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_023.mp3', NULL, 1761758917, 1761758917),
(42046, 'Deuteronomy 14:24', 'Deuteronomy', 14, 24, 'که چېرې د عبادت ځای ستاسو د کور څخه ډېر لېرې وي چې د خپلو هغو محصولاتو عشر چې څښتن تاسو ته په کې برکت درکړی دی هلته وړلی نه شئ، بیا داسې وکړئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_024.mp3', NULL, 1761758917, 1761758917),
(42047, 'Deuteronomy 14:25', 'Deuteronomy', 14, 25, 'چې خپل حاصلات خرڅ کړئ او د هغو پیسې هغه عبادت ځای ته یوسئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_025.mp3', NULL, 1761758917, 1761758917),
(42048, 'Deuteronomy 14:26', 'Deuteronomy', 14, 26, 'په هر شي باندې چې تاسو غواړئ دا پیسې مصرف کړئ یعنې په غواګانو، پسونو، وزو، شرابو باندې او د خپلو کورنیو سره یې هلته د خپل څښتن خدای په حضور کې وخورئ او خوشحالي وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_026.mp3', NULL, 1761758917, 1761758917),
(42049, 'Deuteronomy 14:27', 'Deuteronomy', 14, 27, 'هغه لاویان مه هېروئ چې ستاسو په ښارونو کې اوسیږي، هغوی خپله ځمکه نه لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_027.mp3', NULL, 1761758917, 1761758917),
(42050, 'Deuteronomy 14:28', 'Deuteronomy', 14, 28, 'د هر درېم کال په پای کې د خپلو ټولو حاصلاتو عشر راوړئ او په خپلو ښارونو کې یې ذخیره کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_028.mp3', NULL, 1761758917, 1761758917),
(42051, 'Deuteronomy 14:29', 'Deuteronomy', 14, 29, 'هغه لاویانو ته چې ستاسو په منځ کې خپله ځمکه نه لري او همدارنګه هغو پردیو خلکو، یتیمانو او کونډو ته چې ستاسو په ښارونو کې اوسیږي ورکړئ چې ویې خوري او ورباندې ماړه شي. نو بیا به ستاسو څښتن خدای تاسو ته په ټولو کارونو کې برکت درکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy14_verse_029.mp3', NULL, 1761758917, 1761758917),
(42052, 'Deuteronomy 23:1', 'Deuteronomy', 23, 1, 'هېڅ داسې سړی چې خصي شوی وي یا د هغه تناسلي اله پرې کړل شوې وي د څښتن په قوم کې نه شي شاملېدلی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_001.mp3', NULL, 1761758917, 1761758917),
(42053, 'Deuteronomy 23:2', 'Deuteronomy', 23, 2, 'هېڅ داسې کس چې حرامي وي او د داسې کس اولاده حتی تر لسم نسله پورې د څښتن په قوم کې نه شي شاملېدلی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_002.mp3', NULL, 1761758917, 1761758917),
(42054, 'Deuteronomy 23:3', 'Deuteronomy', 23, 3, 'هېڅ عمونی یا موآبی او د هغوی اولاده حتی تر لسم نسله پورې د څښتن په قوم کې نه شي شاملېدلی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_003.mp3', NULL, 1761758917, 1761758917),
(42055, 'Deuteronomy 23:4', 'Deuteronomy', 23, 4, 'دا په دې سبب کله چې تاسو د مصر څخه راوتلئ، هغوی تاسو ته د ډوډۍ او اوبو د برابرولو څخه انکار وکړ او د بعور زوی بلعام یې چې په بین النهرین کې د فتور د ښار څخه ؤ، اجیر ونیوه چې په تاسو باندې لعنت ووایي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_004.mp3', NULL, 1761758917, 1761758917),
(42056, 'Deuteronomy 23:5', 'Deuteronomy', 23, 5, 'خو ستاسو څښتن خدای به بلعام ته غوږ نه نیوه، د هغې په ځای یې لعنت په برکت بدل کړ، ځکه چې هغه ستاسو سره مینه درلودله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_005.mp3', NULL, 1761758917, 1761758917),
(42057, 'Deuteronomy 23:6', 'Deuteronomy', 23, 6, 'تاسو او ستاسو راتلونکي نسلونه د هغو قومونو سره د هېڅ شي مرسته ونه کړئ او د هغوی نېکمرغي مه غواړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_006.mp3', NULL, 1761758917, 1761758917),
(42058, 'Deuteronomy 23:7', 'Deuteronomy', 23, 7, 'ادومیانو ته په سپکه سترګه مه ګورئ، ځکه چې هغوی ستاسو خپلوان دي. مصریانو ته هم په سپکه سترګه مه ګورئ، ځکه چې یو وخت تاسو د هغوی په خاوره کې اوسېدلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_007.mp3', NULL, 1761758917, 1761758917),
(42059, 'Deuteronomy 23:8', 'Deuteronomy', 23, 8, 'کېدای شي چې د هغوی لمسیان د څښتن په قوم کې شامل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_008.mp3', NULL, 1761758917, 1761758917),
(42060, 'Deuteronomy 23:9', 'Deuteronomy', 23, 9, 'کله چې تاسو د جنګ په وخت کې په کمپ کې یئ، باید د هر هغه شي څخه چې تاسو په مذهبي لحاظ ناپاکه کوي ځانونه وساتئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_009.mp3', NULL, 1761758917, 1761758917),
(42061, 'Deuteronomy 23:10', 'Deuteronomy', 23, 10, 'که چېرې د شپې له خوا شیطان یو سړی وغولوي او له دې امله هغه ناپاک شي، هغه دې د کمپ څخه دباندې ووځي او هلته دې پاتې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_010.mp3', NULL, 1761758917, 1761758917),
(42062, 'Deuteronomy 23:11', 'Deuteronomy', 23, 11, 'هغه دې مازدیګر غسل وکړي او ماښام کولای شي چې بېرته کمپ ته راشي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_011.mp3', NULL, 1761758917, 1761758917),
(42063, 'Deuteronomy 23:12', 'Deuteronomy', 23, 12, 'د کمپ څخه دباندې یو داسې ځای جوړ کړئ چې د تشناب په توګه ورڅخه کار واخیستل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_012.mp3', NULL, 1761758917, 1761758917),
(42064, 'Deuteronomy 23:13', 'Deuteronomy', 23, 13, 'په خپلو سامانونو کې یو داسې شی ولرئ چې ځمکه ورباندې وکیندل شي. کله چې تاسو د اړتیا د رفع کولو دپاره ځئ، په هغه باندې یوه کنده وباسئ. بیا وروسته له دې چې خپل حاجت رفع کړئ، خپل غایطه مواد په هغې کندې کې ښخوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_013.mp3', NULL, 1761758917, 1761758917),
(42065, 'Deuteronomy 23:14', 'Deuteronomy', 23, 14, 'څرنګه چې ستاسو څښتن خدای ستاسو په کمپ کې ګرځي چې ستاسو ساتنه وکړي او په خپلو دښمنانو باندې بری درکړي، نو ستاسو کمپ باید سپېڅلی وي، ترڅو هغه ستاسو په منځ کې کوم خراب شی ونه ویني او ستاسو څخه مخ ونه ګرځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_014.mp3', NULL, 1761758917, 1761758917),
(42066, 'Deuteronomy 23:15', 'Deuteronomy', 23, 15, 'که چېرې یو غلام د خپل بادار څخه وتښتي او تاسو ته د پناه اخیستلو دپاره راشي، هغه بېرته خپل بادار ته په لاس مه ورکوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_015.mp3', NULL, 1761758917, 1761758917),
(42067, 'Deuteronomy 23:16', 'Deuteronomy', 23, 16, 'هغه کولای شي ستاسو په هر ښار کې چې د هغه خوښه وي واوسیږي او تاسو باید د هغه سره بد چلند ونه کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_016.mp3', NULL, 1761758917, 1761758917),
(42068, 'Deuteronomy 23:17', 'Deuteronomy', 23, 17, 'هېڅ اسراییلی سړی یا ښځه باید د عبادتځای بدلمنه نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_017.mp3', NULL, 1761758917, 1761758917),
(42069, 'Deuteronomy 23:18', 'Deuteronomy', 23, 18, 'همدارنګه هېڅ داسې پیسې چې په دې ډول ګټل شوې وي د نذر د ورکولو دپاره دې ستاسو د څښتن خدای کور ته رانه وړل شي. څښتن د عبادتځای د لواطت کارانو او بدلمنو څخه کرکه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_018.mp3', NULL, 1761758917, 1761758917),
(42070, 'Deuteronomy 23:19', 'Deuteronomy', 23, 19, 'کله چې تاسو یو اسراییلي ورور ته پیسې یا ډوډۍ یا بل شی په پور ورکړئ، د هغه څخه سود مه اخلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_019.mp3', NULL, 1761758917, 1761758917),
(42071, 'Deuteronomy 23:20', 'Deuteronomy', 23, 20, 'تاسو کولای شئ چې د پردي کس څخه سود واخلئ، خو د اسراییلي څخه نه. دا کار وکړئ، نو ستاسو څښتن خدای به ستاسو په هر کار کې چې تاسو یې په هغه خاوره کې کوئ چې تاسو یې نیسئ، برکت واچوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_020.mp3', NULL, 1761758917, 1761758917),
(42072, 'Deuteronomy 23:21', 'Deuteronomy', 23, 21, 'کله چې تاسو خپل څښتن خدای ته نذر منئ، د خپلې وعدې په پوره کولو کې ځنډ مه کوئ، ځکه چې ستاسو څښتن خدای به ستاسو څخه وغواړي چې هغه وعده پوره کړئ. که نه، نو تاسو به ګناهکار وګڼل شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_021.mp3', NULL, 1761758917, 1761758917),
(42073, 'Deuteronomy 23:22', 'Deuteronomy', 23, 22, 'دا کومه ګناه نه ده چې تاسو څښتن ته نذر ونه منئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_022.mp3', NULL, 1761758917, 1761758917),
(42074, 'Deuteronomy 23:23', 'Deuteronomy', 23, 23, 'څه چې تاسو ویلي دي هغه باید خامخا پوره کړئ، ځکه چې تاسو په خپله خوښه او په خپلې خولې څښتن ته نذر منلی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_023.mp3', NULL, 1761758917, 1761758917),
(42075, 'Deuteronomy 23:24', 'Deuteronomy', 23, 24, 'کله چې تاسو د بل چا د انګورو باغ ته ورننوځئ، څومره انګور چې غواړئ خوړلی یې شئ، خو هغه باید په یو لوښي کې د خپل ځان سره یونسئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_024.mp3', NULL, 1761758917, 1761758917),
(42076, 'Deuteronomy 23:25', 'Deuteronomy', 23, 25, 'کله چې تاسو د بل چا د غلو دانو پټي ته ورننوځئ، کولای شئ چې په خپلو لاسونو باندې وږي راټول کړئ او هغه وخورئ، خو هغه باید په لور باندې ونه رېبئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy23_verse_025.mp3', NULL, 1761758917, 1761758917),
(42077, 'Leviticus 2:1', 'Leviticus', 2, 1, 'کله چې ستاسو څخه څوک څښتن ته د غلې دانې نذرانه وړاندې کوي، هغه نذرانه دې د ښو اوړو څخه وي. په هغې باندې دې د زیتونو تېل توی کړي، قیمتي خوشبویي دې ورباندې واچوي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_001.mp3', NULL, 1761758917, 1761758917),
(42078, 'Leviticus 2:2', 'Leviticus', 2, 2, 'او د هارون زامنو یعنې کاهنانو ته دې وروړي. کاهن دې د ټولې قیمتي خوشبویۍ سره د ښو اوړو څخه چې تېل ورسره ګډ دي، یو موټی راواخلي او هغه دې د یوې نمونې په توګه چې ټوله څښتن ته وړاندې کیږي، د قربانۍ په ځای باندې وسوځوي. دا یوه داسې نذرانه ده چې بوی یې په څښتن باندې ښه لګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_002.mp3', NULL, 1761758917, 1761758917),
(42079, 'Leviticus 2:3', 'Leviticus', 2, 3, 'د غلې دانې پاتې نذرانه د کاهنانو ده، دا د هغو نذرانو یوه ډېره سپېڅلې برخه ده چې څښتن ته په اور باندې تیاریږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_003.mp3', NULL, 1761758917, 1761758917),
(42080, 'Leviticus 2:4', 'Leviticus', 2, 4, 'که چېرې نذرانه داسې ډوډۍ وي چې په تنور کې پخه شوې وي، باید فطیره وي. هغه باید د داسې ښو اوړو څخه تیاره شوې وي چې د زیتونو تېل ورسره ګډ وي یا نرۍ ډوډۍ چې د زیتونو په تېلو باندې غوړه شوي وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_004.mp3', NULL, 1761758917, 1761758917),
(42081, 'Leviticus 2:5', 'Leviticus', 2, 5, 'که چېرې نذرانه داسې ډوډۍ وي چې په تبۍ باندې پخه شوې وي، هغه دې د داسې ښو اوړو څخه تیاره شي چې د زیتونو تېل ورسره ګډ وي، خو فطیره دې وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_005.mp3', NULL, 1761758917, 1761758917),
(42082, 'Leviticus 2:6', 'Leviticus', 2, 6, 'هغه ټوټې ټوټې کړئ او نور تېل ورباندې واچوئ، دا د غلې دانې یوه نذرانه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_006.mp3', NULL, 1761758917, 1761758917),
(42083, 'Leviticus 2:7', 'Leviticus', 2, 7, 'که چېرې نذرانه داسې ډوډۍ وي چې په ارکاره باندې پخه شوې وي، هغه دې د ښو اوړو او د زیتونو د تېلو څخه جوړه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_007.mp3', NULL, 1761758917, 1761758917),
(42084, 'Leviticus 2:8', 'Leviticus', 2, 8, 'د دې شیانو څخه چې کومه د غلې دانې نذرانه جوړه شوې وي، هغه څښتن ته راوړئ او کاهن ته یې وړاندې کړئ، هغه به یې د قربانۍ ځای ته یوسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_008.mp3', NULL, 1761758917, 1761758917),
(42085, 'Leviticus 2:9', 'Leviticus', 2, 9, 'کاهن به د هغې څخه یوه برخه واخلي او هغه به د یوې نمونې په توګه چې ټوله څښتن ته وړاندې کیږي، د قربانۍ په ځای باندې وسوځوي. دا یوه داسې نذرانه ده چې بوی یې په څښتن باندې ښه لګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_009.mp3', NULL, 1761758917, 1761758917),
(42086, 'Leviticus 2:10', 'Leviticus', 2, 10, 'د غلې دانې پاتې نذرانه د کاهنانو ده. دا ډېره سپېڅلې ده. دا د هغو نذرانو یوه ډېره سپېڅلې برخه ده چې څښتن ته په اور باندې تیاریږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_010.mp3', NULL, 1761758917, 1761758917),
(42087, 'Leviticus 2:11', 'Leviticus', 2, 11, 'د غلې دانې هغه نذرانې چې څښتن ته یې وړاندې کوئ، په هېڅ یوه کې دې خمیره نه وي. تاسو باید په هغو نذرانو کې چې څښتن ته په اور باندې تیاریږي، هېڅ خمیره یا شات ونه کاروئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_011.mp3', NULL, 1761758917, 1761758917),
(42088, 'Leviticus 2:12', 'Leviticus', 2, 12, 'باید د لومړنیو غلو دانو څخه چې هر کال یې رېبئ څښتن ته یوه نذرانه راوړئ، خو هغه باید د قربانۍ په ځای باندې ونه سوځول شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_012.mp3', NULL, 1761758917, 1761758917),
(42089, 'Leviticus 2:13', 'Leviticus', 2, 13, 'د غلې دانې په هرې نذرانې باندې مالګه واچوئ، ځکه چې مالګه د خدای او ستاسو په منځ کې د لوظ یوه نښه ده. تاسو باید په خپلو ټولو نذرانو باندې مالګه واچوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_013.mp3', NULL, 1761758917, 1761758917),
(42090, 'Leviticus 2:14', 'Leviticus', 2, 14, 'کله چې تاسو څښتن ته د لومړنیو رېبل شویو غلو دانو نذرانه راوړئ، نو نینې شوې دانې یا میده اوړه ورته وړاندې کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_014.mp3', NULL, 1761758917, 1761758917),
(42091, 'Leviticus 2:15', 'Leviticus', 2, 15, 'په هغې باندې د زیتونو تېل ورزیات کړئ او قیمتي خوشبویي ورباندې واچوئ. دا د غلې دانې یوه نذرانه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_015.mp3', NULL, 1761758917, 1761758917),
(42092, 'Leviticus 2:16', 'Leviticus', 2, 16, 'کاهن به د میده اوړو او تېلو یوه برخه د نمونې په توګه د ټولې قیمتي خوشبویۍ سره یوځای د یوې نذرانې په توګه وسوځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/leviticus2_verse_016.mp3', NULL, 1761758917, 1761758917),
(42093, 'Genesis 36:1', 'Genesis', 36, 1, 'دا د عیسو اولاده ده (عیسو د ادوم په نوم هم یادېده.)', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_001.mp3', NULL, 1761758917, 1761758917),
(42094, 'Genesis 36:2', 'Genesis', 36, 2, 'عیسو د کنعاني ښځو سره ودونه وکړل: عاده د حیتي ایلون لور، اهولیبامه چې د عنه لور او د حوي صبعون لمسۍ وه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_002.mp3', NULL, 1761758917, 1761758917),
(42095, 'Genesis 36:3', 'Genesis', 36, 3, 'او بسمه چې د اسماعیل لور او د نبایوت خور وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_003.mp3', NULL, 1761758917, 1761758917),
(42096, 'Genesis 36:4', 'Genesis', 36, 4, 'عادې الیفاز وزېږاوه او بسمې رعوییل وزېږاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_004.mp3', NULL, 1761758917, 1761758917),
(42097, 'Genesis 36:5', 'Genesis', 36, 5, 'اهولیبامه یعوش، یعلام او قورح وزېږول. دا د عیسو زامن وو چې په کنعان کې زېږېدلي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_005.mp3', NULL, 1761758917, 1761758917),
(42098, 'Genesis 36:6', 'Genesis', 36, 6, 'عیسو خپلې ښځې، زامن، لورګانې او د خپلې کورنۍ ټول غړي او همدارنګه خپلې ټولې رمې او پادې او خپله ټوله شتمني چې په کنعان کې یې لاسته راوړي وو، واخیستل او د خپل ورور یعقوب څخه لږ څه لېرې یې بلې سیمې ته کډه وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_006.mp3', NULL, 1761758917, 1761758917),
(42099, 'Genesis 36:7', 'Genesis', 36, 7, 'هغه لاړ، ځکه هغه ځمکه چې یعقوب او هغه په کې اوسېدل، دومره زیاته نه وه چې دواړه سره یوځای واوسیږي، په دې خاطر چې هغوی زیاتې رمې او پادې درلودلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_007.mp3', NULL, 1761758917, 1761758917),
(42100, 'Genesis 36:8', 'Genesis', 36, 8, 'نو عیسو د ادوم په غرنۍ سیمه کې اوسېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_008.mp3', NULL, 1761758917, 1761758917),
(42101, 'Genesis 36:9', 'Genesis', 36, 9, 'دا د ادوم په غرنۍ سیمه کې د ادومیانو د نیکه عیسو اولاده ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_009.mp3', NULL, 1761758917, 1761758917),
(42102, 'Genesis 36:10', 'Genesis', 36, 10, 'د عیسو د زامنو نومونه دا دي: الیفاز د عیسو د ښځې عاده زوی او رعوییل د عیسو د ښځې بسمې زوی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_010.mp3', NULL, 1761758917, 1761758917),
(42103, 'Genesis 36:11', 'Genesis', 36, 11, 'د الیفاز زامن: تیمان، اومار، صفو، جعتام او قناز.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_011.mp3', NULL, 1761758917, 1761758917),
(42104, 'Genesis 36:12', 'Genesis', 36, 12, 'تمناع د عیسو د زوی الیفاز وینځه وه او د هغې څخه د هغه زوی عمالیق پیدا شو. دا د عیسو د ښځې عادې لمسیان وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_012.mp3', NULL, 1761758917, 1761758917),
(42105, 'Genesis 36:13', 'Genesis', 36, 13, 'د رعوییل زامن: نحت، زارح، شمه او مزه. دا د عیسو د ښځې بسمې لمسیان وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_013.mp3', NULL, 1761758917, 1761758917),
(42106, 'Genesis 36:14', 'Genesis', 36, 14, 'اهولیبامه د عنه لور او د صبعون لمسۍ وه چې د هغې څخه د عیسو زامن یعوش، یعلام او قورح پیدا شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_014.mp3', NULL, 1761758917, 1761758917),
(42107, 'Genesis 36:15', 'Genesis', 36, 15, 'د عیسو په اولادې کې دغه قبیلوي مشران وو: د عیسو د مشر زوی الیفاز زامن: تیمان، اومار، صفو، قناز،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_015.mp3', NULL, 1761758917, 1761758917),
(42108, 'Genesis 36:16', 'Genesis', 36, 16, 'قورح، جعتام او عمالیق. دا په ادوم کې هغه قبیلوي مشران وو چې د الیفاز د اولادې څخه دي او دوی د عادې لمسیان وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_016.mp3', NULL, 1761758917, 1761758917),
(42109, 'Genesis 36:17', 'Genesis', 36, 17, 'د عیسو د زوی رعوییل زامن: نحت، زارح، شمه او مزه. دا په ادوم کې هغه قبیلوي مشران وو چې د رعوییل د اولادې څخه دي. دا د عیسو د ښځې بسمې لمسیان وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_017.mp3', NULL, 1761758917, 1761758917),
(42110, 'Genesis 36:18', 'Genesis', 36, 18, 'د عیسو د ښځې اهولیبامه زامن: یعوش، یعلام او قورح. دا هغه قبیلوي مشران وو چې د عنه د لور یعنې د عیسو د ښځې اهولیبامه د اولادې څخه دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_018.mp3', NULL, 1761758917, 1761758917),
(42111, 'Genesis 36:19', 'Genesis', 36, 19, 'دا ټولې قبیلې د عیسو د اولادې څخه وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_019.mp3', NULL, 1761758917, 1761758917),
(42112, 'Genesis 36:20', 'Genesis', 36, 20, 'دا د سعیر حوري زامن وو چې په هغې سیمه کې اوسېدل: لوتان، شوبال، صبعون، عنه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_020.mp3', NULL, 1761758917, 1761758917),
(42113, 'Genesis 36:21', 'Genesis', 36, 21, 'دیشون، ایصر او دیشان. دا په ادوم کې د سعیر زامن او د حوریانو مشران وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_021.mp3', NULL, 1761758917, 1761758917),
(42114, 'Genesis 36:22', 'Genesis', 36, 22, 'د لوتان زامن: حوري او هومام. (تمناع د لوتان خور وه.)', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_022.mp3', NULL, 1761758917, 1761758917),
(42115, 'Genesis 36:23', 'Genesis', 36, 23, 'د شوبال زامن: علوان، مناحت، عیبال، شفو او اونام.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_023.mp3', NULL, 1761758917, 1761758917),
(42116, 'Genesis 36:24', 'Genesis', 36, 24, 'د صبعون زامن: ایه او عنه. (دا هماغه عنه دی، کله چې هغه د خپل پلار صبعون خره څرول، نو په دښته کې یې د تودو اوبو چینې وموندلې.)', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_024.mp3', NULL, 1761758917, 1761758917),
(42117, 'Genesis 36:25', 'Genesis', 36, 25, 'د عنه اولادونه: دیشون او اهولیبامه د عنه لور.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_025.mp3', NULL, 1761758917, 1761758917),
(42118, 'Genesis 36:26', 'Genesis', 36, 26, 'د دیشون زامن: حمدان، اشبان، یتران او کران.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_026.mp3', NULL, 1761758917, 1761758917),
(42119, 'Genesis 36:27', 'Genesis', 36, 27, 'د ایصر زامن: بلهان، زعوان او عقان.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_027.mp3', NULL, 1761758917, 1761758917),
(42120, 'Genesis 36:28', 'Genesis', 36, 28, 'د دیشان زامن: عوص او اران.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_028.mp3', NULL, 1761758917, 1761758917),
(42121, 'Genesis 36:29', 'Genesis', 36, 29, 'دا د حوریانو مشران وو: لوتان، شوبال، صبعون، عنه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_029.mp3', NULL, 1761758917, 1761758917),
(42122, 'Genesis 36:30', 'Genesis', 36, 30, 'دیشون، ایصر او دیشان. دا د حوریانو قبیلې وې چې د ادوم په خاوره کې اوسېدلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis36_verse_030.mp3', NULL, 1761758917, 1761758917),
(42123, 'Nehemiah 2:1', 'Nehemiah', 2, 1, 'د ارتخششتا د پاچاهۍ په شلم کال د نیسان په میاشت کې یوه ورځ کله چې ارتخششتا پاچا ته شراب راوړل شول، ما هغه ته د شرابو جام وړاندې کړ. هغه هېڅکله زه خفه لیدلی نه وم،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_001.mp3', NULL, 1761758917, 1761758917),
(42124, 'Nehemiah 2:2', 'Nehemiah', 2, 2, 'نو هغه زما څخه پوښتنه وکړه: «ولې داسې خفه ښکارې؟ فکر نه کوم چې ته ناروغ یې، نو هرومرو ته خفه یې.» زه د دې پوښتنې څخه ډېر ووېرېدم', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_002.mp3', NULL, 1761758917, 1761758917),
(42125, 'Nehemiah 2:3', 'Nehemiah', 2, 3, 'او ځواب مې ورکړ: «تاسو اعلیحضرت دې تل ژوندی اوسئ! زه به څنګه خفه ښکاره نه شم؟ هغه ښار چې زما نیکونه په کې ښخ دي هغه وران شوی دی او د هغه دروازې سوځېدلې دي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_003.mp3', NULL, 1761758917, 1761758917),
(42126, 'Nehemiah 2:4', 'Nehemiah', 2, 4, 'پاچا پوښتنه وکړه: «ته څه غواړې؟» ما د اسمانونو خدای ته دعا وکړه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_004.mp3', NULL, 1761758917, 1761758917),
(42127, 'Nehemiah 2:5', 'Nehemiah', 2, 5, 'او بیا مې پاچا ته ځواب ورکړ: «که چېرې تاسو اعلیحضرت زما څخه خوشحاله او راضي یئ چې زما غوښتنه ومنئ، نو ما ولېږئ چې یهودا ته لاړ شم، یعنې هغه ښار ته چې زما نیکونه په کې ښخ دي، ترڅو هغه ښار بېرته ودان کړم.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_005.mp3', NULL, 1761758917, 1761758917),
(42128, 'Nehemiah 2:6', 'Nehemiah', 2, 6, 'پاچا چې ملکه یې په څنګ کې ناسته وه، پوښتنه وکړه: «ته د څومره وخت دپاره ځې او کله بېرته راځې؟» ما هغه ته د راستنېدلو وخت وښود او بیا هغه زما غوښتنه ومنله.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_006.mp3', NULL, 1761758917, 1761758917),
(42129, 'Nehemiah 2:7', 'Nehemiah', 2, 7, 'بیا ما پاچا ته وویل: «اعلیحضرته! که ستاسو خوښه وي، نو ماته د فرات د سیند د لوېدیځې خوا د سیمو په والیانو باندې لیکونه راکړئ، ترڅو وکولای شم چې یهودا ته په خیریت سره لاړ شم.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_007.mp3', NULL, 1761758917, 1761758917),
(42130, 'Nehemiah 2:8', 'Nehemiah', 2, 8, 'همدارنګه ما د هغه څخه وغوښتل چې د شاهي ځنګلونو ساتونکي اساف ته هم یو لیک راکړي او هغه ته لارښوونه وکړي چې ماته د هغې کلا د دروازو د جوړولو دپاره چې د خدای د کور په څنګ کې ده، د ښار د دېوالونو دپاره او د هغه کور د جوړولو دپاره چې زه به په کې اوسېږم، لرګي راکړي. هغه ټول شیان چې ما غوښتي وو پاچا هغه ماته راکړل، ځکه چې زما خدای په ما باندې مهربانه او زما سره مل ؤ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_008.mp3', NULL, 1761758917, 1761758917),
(42131, 'Nehemiah 2:9', 'Nehemiah', 2, 9, 'پاچا څو عسکري منصبداران او د سپرو عسکرو یو لښکر زما سره ولېږه او ما د فرات د سیند لوېدیځې خواته سفر وکړ. هلته مې والیانو ته د پاچا لیکونه ورکړل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_009.mp3', NULL, 1761758917, 1761758917),
(42132, 'Nehemiah 2:10', 'Nehemiah', 2, 10, 'خو کله چې سنبلط چې د بیت حورون د ښارګوټي اوسېدونکی او طوبیا چې د عمون د ولایت یو مامور ؤ دا واورېدل چې یو څوک راغلی دی، ترڅو د اسراییلو د خلکو د ښېګڼې دپاره کار وکړي، نو هغوی ډېر خفه شول.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_010.mp3', NULL, 1761758917, 1761758917),
(42133, 'Nehemiah 2:11', 'Nehemiah', 2, 11, 'زه اورشلیم ته لاړم او تر درې ورځو پورې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_011.mp3', NULL, 1761758917, 1761758917),
(42134, 'Nehemiah 2:12', 'Nehemiah', 2, 12, 'ما هېچا ته د هغه پلان په اړه ونه ویل چې زما خدای د اورشلیم په هکله زما په زړه کې جوړ کړی ؤ. بیا زه د شپې راپاڅېدم، راووتم او د خپلو ملګرو څخه مې څو تنه د ځان سره بوتلل. هلته یوازې یو خر ؤ چې زه ورباندې سپور وم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_012.mp3', NULL, 1761758917, 1761758917),
(42135, 'Nehemiah 2:13', 'Nehemiah', 2, 13, 'زه د درې د دروازې له لارې د ښار نه ووتلم، د ښامار د چینې څخه تېر شوم او د خزلو د دروازې خواته لاړم. د تګ په وخت کې مې د نژدې څخه د ښار غورځېدلي دېوالونه او سوځول شوې دروازې په غور سره ولیدلې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_013.mp3', NULL, 1761758917, 1761758917),
(42136, 'Nehemiah 2:14', 'Nehemiah', 2, 14, 'زه د فوارې دروازې او د پاچا حوض ته ورسېدم. خو وروسته بیا لاره دومره بنده وه چې زما خر ورباندې تېرېدلی نه شو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_014.mp3', NULL, 1761758917, 1761758917),
(42137, 'Nehemiah 2:15', 'Nehemiah', 2, 15, 'نو زه د قدرون درې ته ورښکته شوم او په لاره روان وم او دېوال ته مې کتل. بیا په هغه لاره باندې چې راغلی وم بېرته ستون شوم او د درې د دروازې له لارې بېرته ښار ته ورننوتلم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_015.mp3', NULL, 1761758917, 1761758917),
(42138, 'Nehemiah 2:16', 'Nehemiah', 2, 16, 'د هغه ځای د مامورینو څخه هېڅوک پوه نه شو چې زه چېرته تللی وم او څه مې وکړل. ما نورو یهودیانو ته لکه کاهنانو، مشرانو، مامورینو او نورو هغو خلکو ته چې په دې کار کې به یې برخه اخیستله، تر هغه وخته هېڅ ونه ویل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_016.mp3', NULL, 1761758917, 1761758917),
(42139, 'Nehemiah 2:17', 'Nehemiah', 2, 17, 'خو هغوی ته مې وویل: «ګورئ چې مونږ د څه ډول کړاو سره مخامخ یو، ځکه چې اورشلیم وران شوی دی او د هغه دروازې سوځېدلې دي. راځئ چې د ښار دېوال بېرته جوړ کړو او خپل ځانونه د رسوایۍ څخه خلاص کړو.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_017.mp3', NULL, 1761758917, 1761758917),
(42140, 'Nehemiah 2:18', 'Nehemiah', 2, 18, 'بیا ما هغوی ته وویل چې خدای څنګه زما سره مل ؤ او مرسته یې راسره کوله او هغه څه مې هم ورته وویل چې پاچا راته ویلي وو. هغوی په ځواب کې وویل: «راځئ چې د بیا ودانولو په کار پیل وکړو.» نو هغوی په دې توګه دې ته تیار شول چې دا نېک کار پیل کړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_018.mp3', NULL, 1761758917, 1761758917),
(42141, 'Nehemiah 2:19', 'Nehemiah', 2, 19, 'خو کله چې سنبلط، طوبیا او یو عرب چې جشم نومېده زمونږ د نقشې څخه خبر شول چې مونږ څه کوو، نو هغوی په مونږ باندې ملنډې ووهلې او زمونږ سپکاوی یې وکړ، ویې ویل: «تاسو څه کوئ؟ ایا غواړئ چې د پاچا په وړاندې سرکښي وکړئ؟»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_019.mp3', NULL, 1761758917, 1761758917),
(42142, 'Nehemiah 2:20', 'Nehemiah', 2, 20, 'ما ځواب ورکړ: «د اسمانونو خدای به مونږ ته بری راکړي. مونږ د هغه خدمتګاران یو او مونږ به د بیا ودانولو کار پیل کړو. خو تاسو نه د اورشلیم په چارو کې حق لرئ او نه د هغه په جایداد کې برخه لرئ او نه د هغه په دود او دستور او تاریخ کې شریک یئ.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah2_verse_020.mp3', NULL, 1761758917, 1761758917),
(42143, 'Judges 14:1', 'Judges', 14, 1, 'یوه ورځ شمشون تمنې ته لاړ او هلته یې یوه فلسطینۍ انجلۍ ولیدله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_001.mp3', NULL, 1761758917, 1761758917),
(42144, 'Judges 14:2', 'Judges', 14, 2, 'کله چې هغه بېرته کور ته راستون شو، نو خپل مور او پلار ته یې وویل: «ما په تمنه کې یوه فلسطینۍ انجلۍ ولیدله. هغه ماته وکړئ، زه غواړم چې د هغې سره واده وکړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_002.mp3', NULL, 1761758917, 1761758917),
(42145, 'Judges 14:3', 'Judges', 14, 3, 'خو مور او پلار یې ورڅخه پوښتنه وکړه: «ایا ستا د قوم او خپلوانو په منځ کې انجلۍ نشته چې ته غواړې په هغو ناسنته فلسطینیانو کې ښځه وکړې؟» خو شمشون خپل پلار ته وویل: «همدا انجلۍ راته وکړئ. هغه زما خوښه ده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_003.mp3', NULL, 1761758917, 1761758917),
(42146, 'Judges 14:4', 'Judges', 14, 4, 'د هغه مور او پلار نه پوهېدل چې دا کار د څښتن له خوا ؤ، ځکه چې څښتن یوه موقع کتله چې د فلسطینیانو په وړاندې کوم عمل وکړي. په هغه وخت کې فلسطینیانو په اسراییلو باندې حکومت کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_004.mp3', NULL, 1761758917, 1761758917),
(42147, 'Judges 14:5', 'Judges', 14, 5, 'نو شمشون د خپل مور او پلار سره تمنې ته روان شو. کله چې هغه د تمنې د انګورو د باغونو څخه تېرېده، نو یو ځوان زمری راغی او په شمشون باندې وغورېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_005.mp3', NULL, 1761758917, 1761758917),
(42148, 'Judges 14:6', 'Judges', 14, 6, 'ناڅاپه د څښتن روح هغه قوي کړ او هغه په تشو لاسونو زمری دوه ټوټې کړ لکه یو سېرلی چې دوه ټوټې شي. خو هغه خپل مور او پلار ته په دې هکله څه ونه ویل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_006.mp3', NULL, 1761758917, 1761758917),
(42149, 'Judges 14:7', 'Judges', 14, 7, 'بیا هغه لاړ او د هغې انجلۍ سره یې خبرې وکړې او هغه یې خوښه شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_007.mp3', NULL, 1761758917, 1761758917),
(42150, 'Judges 14:8', 'Judges', 14, 8, 'څه موده وروسته کله چې شمشون د هغې سره د واده کولو دپاره بېرته روان شو، هغه د لارې څخه راوګرځېد چې د هغه زمري مړی وویني چې وژلی یې ؤ. هغه زمري ته وکتل او حیران شو چې د هغه په بدن کې ډېرې د شاتو مچۍ او شات وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_008.mp3', NULL, 1761758917, 1761758917),
(42151, 'Judges 14:9', 'Judges', 14, 9, 'هغه په خپلو لاسونو یو څه شات راوتوږل او په لاره کې یې وخوړل. بیا هغه خپل مور او پلار ته ورغی او هغوی ته یې هم لږ ورکړل او هغوی وخوړل. خو شمشون هغوی ته ونه ویل چې دا شات یې د مړ زمري د بدن څخه راخیستي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_009.mp3', NULL, 1761758917, 1761758917),
(42152, 'Judges 14:10', 'Judges', 14, 10, 'د هغه پلار د واده دپاره تیاری نیوه چې شمشون هلته په تمنه کې یوه مېلمستیا چې په هغې زمانه کې د ځوانانو ترمنځ رواج ؤ، جوړه کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_010.mp3', NULL, 1761758917, 1761758917),
(42153, 'Judges 14:11', 'Judges', 14, 11, 'کله چې فلسطینیانو ولیدل چې شمشون څه ډول سړی دی، نو هغوی خپلو دېرشو ځوانانو ته وویل چې د هغه سره په مېلمستیا کې پاتې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_011.mp3', NULL, 1761758917, 1761758917),
(42154, 'Judges 14:12', 'Judges', 14, 12, 'شمشون هغوی ته وویل: «اجازه راکړئ چې تاسو ته یوه معما ووایم. که چېرې تاسو ماته د مېلمستیا په اووه ورځو کې د هغې ځواب راکړ، زه به تاسو ته د کتان دېرش جوړې ساده کالي او دېرش جوړې ښکلي کالي درکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_012.mp3', NULL, 1761758917, 1761758917),
(42155, 'Judges 14:13', 'Judges', 14, 13, 'خو که چېرې تاسو ځواب رانه کړ، تاسو باید ماته دېرش جوړه د کتان ساده کالي او دېرش جوړه ښکلي کالي راکړئ.» هغوی ورته وویل: «ته خپله معما مونږ ته ووایه چې مونږ یې واورو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_013.mp3', NULL, 1761758917, 1761758917),
(42156, 'Judges 14:14', 'Judges', 14, 14, 'هغه وویل: د خوړونکي څخه راووت د خوړلو شی د زورور څخه راووت یو خوږ شی درې ورځې وروسته بیاهم هغوی ونه شو کولای چې د معما ځواب پیدا کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_014.mp3', NULL, 1761758917, 1761758917),
(42157, 'Judges 14:15', 'Judges', 14, 15, 'په څلورمه ورځ هغوی د شمشون ښځې ته وویل: «ته خپل مېړه وغولوه چې مونږ ته د دې معما معنی ووایي او که نه، نو مونږ به تا او ستا د پلار کورنۍ وسوځوو. ایا تاسو مونږ دلته د دې دپاره راغوښتي یو چې لوټ مو کړئ؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_015.mp3', NULL, 1761758917, 1761758917),
(42158, 'Judges 14:16', 'Judges', 14, 16, 'بیا د شمشون ښځه خپل مېړه ته په ژړا ورغله او ویې ویل: «زه درباندې ګرانه نه یم! ته زما څخه کرکه کوې. تا زما وطندارانو ته یوه معما ویلې ده، خو د هغې معنی دې ماته نه ده ویلې!» شمشون وویل: «ما حتی خپل مور او پلار ته هم نه دي ویلي، نو تاته یې ولې ووایم؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_016.mp3', NULL, 1761758917, 1761758917),
(42159, 'Judges 14:17', 'Judges', 14, 17, 'هغې د مېلمستیا په ټولو اوو ورځو کې وژړل. خو په اوومه ورځ هغه ورته د معما معنی وویله، ځکه چې هغه یې ډېر تنګ کړ. بیا هغې د معما ځواب هغو ځوانانو ته ووایه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_017.mp3', NULL, 1761758917, 1761758917),
(42160, 'Judges 14:18', 'Judges', 14, 18, 'په اوومه ورځ د لمر پرېواته څخه مخکې د ښارګوټي خلک هغه ته راغلل او ویې ویل: څه شی به خوږ وي ډېر د شاتو څخه؟ څه شی قوي به وي ډېر د زمري څخه؟ شمشون ځواب ورکړ: زما په غوا باندې که تاسو قلبه کړې نه وای نو دا معما به مو حل کړې نه وای', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_018.mp3', NULL, 1761758917, 1761758917),
(42161, 'Judges 14:19', 'Judges', 14, 19, 'ناڅاپه د څښتن روح هغه قوي کړ او هغه د اشقلون ښار ته لاړ او د هغه ځای دېرش کسان یې ووژل. هغوی یې لوڅ کړل او د هغوی جامې یې هغو خلکو ته ورکړې چې معما یې حل کړې وه. بیا هغه ډېر په قهر سره بېرته د خپل پلار کور ته لاړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_019.mp3', NULL, 1761758917, 1761758917),
(42162, 'Judges 14:20', 'Judges', 14, 20, 'او د شمشون ښځه د هغه ملګري ته چې په واده کې یې د هغه خدمت کاوه، واده شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges14_verse_020.mp3', NULL, 1761758917, 1761758917),
(42163, 'Isaiah 61:1', 'Isaiah', 61, 1, 'نازل شوی دی په ما روح د څښتن تعالی ځکه چې زه یې مسح کړی یمه ترڅو ورسوم زېری غریبانو ته زه رالېږلی یم هغه چې ورکړم شفا مات شویو زړونو ته او اسیرانو او بندیانو ته اعلان کړم ازادي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_001.mp3', NULL, 1761758917, 1761758917),
(42164, 'Isaiah 61:2', 'Isaiah', 61, 2, 'زه یې رالېږلی یمه چې کړم اعلان د مهربانۍ کال د څښتن او دا چې رارسېدلې ده د انتقام ورځ د څښتن زه یې رالېږلی یمه چې تسلي ورکړم ټولو ویرجنو خلکو ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_002.mp3', NULL, 1761758917, 1761758917),
(42165, 'Isaiah 61:3', 'Isaiah', 61, 3, 'هغو خلکو ته چې ویر کوي صهیون کې د ایرو په ځای به ورکړمه هغوی ته ښایسته تاج د ویر په ځای به خوشحالي ورکړمه او خفګان به یې بدل شي د ستاینې په سندره هغوی به وي خپلې نېکۍ کې د څېړیو د ونو په شان چې کرلي دي څښتن د خپل جلال دپاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_003.mp3', NULL, 1761758917, 1761758917),
(42166, 'Isaiah 61:4', 'Isaiah', 61, 4, 'هغوی به بیا جوړ کړي هغه پخواني ښارونه چې د ډېر وخت دپاره وران پراته وو هغوی به بیا ودان کړي هغه وران ښارونه چې په کې ژوند نه کاوه د خلکو ډېرو نسلونو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_004.mp3', NULL, 1761758917, 1761758917),
(42167, 'Isaiah 61:5', 'Isaiah', 61, 5, 'پردي خلک به کوي پام ستاسو رمو باندې هغوی به ستاسو بزګران وي او وي باغوانان به د انګورو د باغونو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_005.mp3', NULL, 1761758917, 1761758917),
(42168, 'Isaiah 61:6', 'Isaiah', 61, 6, 'خو د څښتن د کاهنانو په نامه به مشهور شئ تاسو خلک به وایي چې یئ د خدای خادمان تاسو به شئ برخمن د نورو قومونو له شتمنیو څخه او تاسو به ویاړئ چې هغه شتمني شوه ستاسو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_006.mp3', NULL, 1761758917, 1761758917),
(42169, 'Isaiah 61:7', 'Isaiah', 61, 7, 'پای ته به ورسیږي سپکاوی او رسوایي ستاسو او وبه اوسېږئ په خپل هېواد کې شي به دوه چنده شتمني ستاسو او خوشحالي به مو په برخه شي د تل دپاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_007.mp3', NULL, 1761758917, 1761758917),
(42170, 'Isaiah 61:8', 'Isaiah', 61, 8, 'څښتن وایي: «زه انصاف خوښوم او کوم کرکه له غلا او ظلمه په وفادارۍ سره به ورکړم اجر خپلو خلکو ته او د هغوی سره به وکړم یو تلپاتې لوظ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_008.mp3', NULL, 1761758917, 1761758917),
(42171, 'Isaiah 61:9', 'Isaiah', 61, 9, 'ټولو قومونو او هېوادونو کې به شي مشهوره اولاده د هغوی هرڅوک چې وویني هغوی، نو په دې به پوه شي چې ما ورکړی برکت هغوی ته»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_009.mp3', NULL, 1761758917, 1761758917),
(42172, 'Isaiah 61:10', 'Isaiah', 61, 10, 'زه خوشحالي کومه ډېره د څښتن په خاطر زما ځان به خوشحالي کړي په ستاینه د څښتن ځکه هغه راته اغوستي د ژغورنې کالي او د عدالت چپنه لکه چې څنګه ښایسته کیږي زوم لونګۍ باندې او ناوې ګاڼو باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_010.mp3', NULL, 1761758917, 1761758917),
(42173, 'Isaiah 61:11', 'Isaiah', 61, 11, 'لکه چې څنګه راشنه کوي تخم ځمکه او راشنه کوي باغ کرل شوي نیالګي همدارنګه څښتن تعالی به کړي ښکاره خپل عدالت ټولو قومونو لره او هغوی به وکړي د هغه ستاینه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah61_verse_011.mp3', NULL, 1761758917, 1761758917),
(42174, 'Isaiah 56:1', 'Isaiah', 56, 1, 'څښتن خپل قوم ته داسې وایي: «د انصاف او عدالت په بنیاد چلند وکړئ، ځکه چې زه به زر راشم، تاسو ته به خلاصون درکړم او زما عدالت به څرګند شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_001.mp3', NULL, 1761758917, 1761758917),
(42175, 'Isaiah 56:2', 'Isaiah', 56, 2, 'بختور دی هغه څوک چې تل داسې کوي او د سبت د ورځې درناوی کوي او د هغه سپکاوی نه کوي. له بدو کړنو ځان ساتي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_002.mp3', NULL, 1761758917, 1761758917),
(42176, 'Isaiah 56:3', 'Isaiah', 56, 3, 'د پردي وطن سړی چې د څښتن د قوم سره یوځای شوی، هغه دې فکر ونه کړي چې څښتن به خامخا ما له خپلو خلکو نه بېل کړي او نه دې خصي سړی دا فکر وکړي چې زه خو د وچې ونې په شان بې حاصله یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_003.mp3', NULL, 1761758917, 1761758917),
(42177, 'Isaiah 56:4', 'Isaiah', 56, 4, 'ځکه څښتن داسې وایي: «کوم خصیان چې زما د سبت د ورځې درناوی وکړي، هغه کار وکړي چې زه ورباندې خوشحالېږم او په وفادارۍ سره زما په لوظ باندې ټینګ ولاړ وي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_004.mp3', NULL, 1761758917, 1761758917),
(42178, 'Isaiah 56:5', 'Isaiah', 56, 5, 'نو بیا هر خصي ته به د خپل کور په دېوالونو کې یو یادګار او یو نوم ورکړم. د هغه چا په پرتله چې اولادونه لري، نوم به یې لوړ وي او تل ترتله به یادیږي، هېڅکله به هغه هېر نه شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_005.mp3', NULL, 1761758917, 1761758917),
(42179, 'Isaiah 56:6', 'Isaiah', 56, 6, 'نو څښتن هغو پردیو خلکو ته چې د هغه د قوم سره یوځای کیږي، د هغه د نوم سره مینه کوي، د هغه خدمت کوي، د سبت د ورځې درناوی کوي او د دې ورځې سپکاوی نه کوي، بلکې په وفادارۍ سره د هغه په لوظ باندې ټینګ ولاړ وي، وایي:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_006.mp3', NULL, 1761758917, 1761758917),
(42180, 'Isaiah 56:7', 'Isaiah', 56, 7, '«تاسو به خپل سپېڅلي غره ته راولم او هلته به په خپل کور کې چې د دعا کولو ځای دی خوشحالي درکړم. کومې سوځېدونکې نذرانې او نورې قربانۍ چې تاسو یې زما د قربانۍ په ځای باندې کوئ، هغه به قبولې کړم. ځکه زما کور به د ټولو قومونو دپاره د دعا د کور په نوم وبلل شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_007.mp3', NULL, 1761758917, 1761758917),
(42181, 'Isaiah 56:8', 'Isaiah', 56, 8, 'څښتن تعالی چې خپل قوم اسراییل یې له جلاوطنۍ نه خپل وطن ته راوستلی دی، وعده کړې ده چې هغه به نور خلک هم راولي چې د دوی سره یوځای شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_008.mp3', NULL, 1761758917, 1761758917),
(42182, 'Isaiah 56:9', 'Isaiah', 56, 9, 'ای ټولو وحشي او د ځنګل داړونکو حیواناتو راشئ، دا خلک وداړئ او ویې خورئ!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_009.mp3', NULL, 1761758917, 1761758917),
(42183, 'Isaiah 56:10', 'Isaiah', 56, 10, 'څښتن وایي: «زما د قوم مشران د هغو پهره دارانو په شان دي چې ړانده وي او په خطر نه پوهیږي. دا مشران د هغو ساتونکو سپیو په شان دي چې نه غاپي، هسې پراته وي او خوبونه ویني. خوب یې څومره خوښ دی!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_010.mp3', NULL, 1761758917, 1761758917),
(42184, 'Isaiah 56:11', 'Isaiah', 56, 11, 'هغوی د حریصو سپیو په شان دي چې هېڅکله نه مړیږي او هم د هغو شپنو په شان دي چې په خطر نه پوهیږي. هر یو یې هغه کار کوي چې زړه یې غواړي، یوازې خپلې ګټې په پام کې نیسي او بس.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_011.mp3', NULL, 1761758917, 1761758917),
(42185, 'Isaiah 56:12', 'Isaiah', 56, 12, 'هغوی وایي: ‹راځئ چې شراب واخلو او هرڅومره چې کولای شو ویې څښو! سبا ورځ به د نن ورځې څخه هم بهتره وي.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah56_verse_012.mp3', NULL, 1761758917, 1761758917),
(42186, 'Job 33:1', 'Job', 33, 1, 'نو اے ايُوبه، زما خبرې واوره، او زۀ چې څۀ وايم نو هغې ته متوجو شه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_001.mp3', NULL, 1761758917, 1761758917),
(42187, 'Job 33:2', 'Job', 33, 2, 'نو اوس چې ما خبرې شروع کړې، نو پرېږده چې زړۀ تش کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_002.mp3', NULL, 1761758917, 1761758917),
(42188, 'Job 33:3', 'Job', 33, 3, 'زما ټولې خبرې سپينې دى، او زۀ رښتيا رښتيا وايم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_003.mp3', NULL, 1761758917, 1761758917),
(42189, 'Job 33:4', 'Job', 33, 4, 'د خُدائ پاک روح زۀ جوړ کړے يم، او د قادر خُدائ ساه ما له ژوند راکړے دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_004.mp3', NULL, 1761758917, 1761758917),
(42190, 'Job 33:5', 'Job', 33, 5, 'کۀ تا سره څۀ جواب وى نو ما له يې راکړه، د خبرې دپاره ځان تيار کړه او په هغې ټينګ ودرېږه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_005.mp3', NULL, 1761758917, 1761758917),
(42191, 'Job 33:6', 'Job', 33, 6, 'ګوره، زۀ هم د خُدائ پاک په نظر کښې ستا په شان يم، زۀ هم د خټې نه جوړ شوے وم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_006.mp3', NULL, 1761758917, 1761758917),
(42192, 'Job 33:7', 'Job', 33, 7, 'نو زما نه مۀ يرېږه، او زۀ به تا سره زياتے نۀ کوم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_007.mp3', NULL, 1761758917, 1761758917),
(42193, 'Job 33:8', 'Job', 33, 8, 'تا زما په مخکښې خبرې کړې دى، او ما ستا ټولې خبرې اورېدلې دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_008.mp3', NULL, 1761758917, 1761758917),
(42194, 'Job 33:9', 'Job', 33, 9, 'تۀ وائې چې، ”زۀ صفا او بې‌ګناه يم، زۀ معصُوم يم او په ما کښې هيڅ غلطى نشته.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_009.mp3', NULL, 1761758917, 1761758917),
(42195, 'Job 33:10', 'Job', 33, 10, 'خو خُدائ پاک په ما کښې غلطى لټوى، هغه ما خپل دشمن ګڼى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_010.mp3', NULL, 1761758917, 1761758917),
(42196, 'Job 33:11', 'Job', 33, 11, 'هغه زما په پښو کښې زولنۍ اچوى، او زما په هر حرکت يې نظر دے.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_011.mp3', NULL, 1761758917, 1761758917),
(42197, 'Job 33:12', 'Job', 33, 12, 'خو په دې خبره کښې تۀ غلط يې. زۀ به تا ته ووايم چې ولې ځکه چې خُدائ پاک د انسان نه لوئ دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_012.mp3', NULL, 1761758917, 1761758917),
(42198, 'Job 33:13', 'Job', 33, 13, 'تۀ په خُدائ پاک باندې اِلزام ولې لګوې، وائې چې هغه به زما د يوې خبرې جواب هم ونۀ کړى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_013.mp3', NULL, 1761758917, 1761758917),
(42199, 'Job 33:14', 'Job', 33, 14, 'ځکه چې خُدائ پاک بار بار کلام کوى، خو خلق دې ته غوږ نۀ ږدى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_014.mp3', NULL, 1761758917, 1761758917),
(42200, 'Job 33:15', 'Job', 33, 15, 'کله چې بنى آدم په خوب اودۀ وى او هغه خوب وينى يا رويا وينى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_015.mp3', NULL, 1761758917, 1761758917),
(42201, 'Job 33:16', 'Job', 33, 16, 'نو خُدائ پاک به د هغوئ غوږونه کولاو کړى، او د خبردارى په ذريعه به هغوئ يروى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_016.mp3', NULL, 1761758917, 1761758917),
(42202, 'Job 33:17', 'Job', 33, 17, 'هغه يې د بدو عملونو نه راوګرځوى، او د غرور نه يې وساتى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_017.mp3', NULL, 1761758917, 1761758917),
(42203, 'Job 33:18', 'Job', 33, 18, 'هغه يې د مرګ نه بچ کوى، او د مرګ درياب د تېرېدو نه يې بچ کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_018.mp3', NULL, 1761758917, 1761758917),
(42204, 'Job 33:19', 'Job', 33, 19, 'خُدائ پاک د بيمارۍ په ذريعه د خلقو اصلاح کوى، او د هغوئ په بدنونو باندې درد راولى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_019.mp3', NULL, 1761758917, 1761758917),
(42205, 'Job 33:20', 'Job', 33, 20, 'نو د هغوئ لوږه ختمه شى، او مزېدار خوراک ته يې هم زړۀ نۀ کيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_020.mp3', NULL, 1761758917, 1761758917),
(42206, 'Job 33:21', 'Job', 33, 21, 'د هغوئ بدنونه ويلى شى، او دوه ګوتې مخ يې راوځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_021.mp3', NULL, 1761758917, 1761758917),
(42207, 'Job 33:22', 'Job', 33, 22, 'هغوئ د مرګ په خولۀ ولاړ وى، او د مرګ فرښته د هغوئ انتظار کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_022.mp3', NULL, 1761758917, 1761758917),
(42208, 'Job 33:23', 'Job', 33, 23, 'خو کۀ د زرګونو فرښتو نه يوه فرښته راشى او چا ته صحيح لار وښائى نو دا بس دى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_023.mp3', NULL, 1761758917, 1761758917),
(42209, 'Job 33:24', 'Job', 33, 24, 'او هغه په هغه کس باندې مِهربانه شى او ووائى چې، هغه بچ کړه چې قبر ته لاړ نۀ شى، ځکه چې ما ته د هغۀ د ژوند قيمت مِلاو شوے دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_024.mp3', NULL, 1761758917, 1761758917),
(42210, 'Job 33:25', 'Job', 33, 25, 'د هغۀ بدن دې د ځوانۍ په وجه تازه شى، په هغۀ دې د ځوانۍ ورځې بيا راشى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_025.mp3', NULL, 1761758917, 1761758917),
(42211, 'Job 33:26', 'Job', 33, 26, 'بيا هغه خُدائ پاک ته سوال وکړى او سوال يې قبول شى، هغه په خوشحالۍ سره د خُدائ پاک حضور ته راشى، او هغه يې بيا يو نېک سړے جوړ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_026.mp3', NULL, 1761758917, 1761758917),
(42212, 'Job 33:27', 'Job', 33, 27, 'هغه به نورو کسانو ته وائى چې، ما ګناه کړې ده، او د نېکۍ په ځائ مې بدى کړې ده. او خُدائ پاک ما له د هغې سزا نۀ ده راکړې د څۀ چې زۀ لائق وم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_027.mp3', NULL, 1761758917, 1761758917),
(42213, 'Job 33:28', 'Job', 33, 28, 'خُدائ پاک زۀ د قبر نه بچ کړم، او زما ژوند به په رڼا کښې وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_028.mp3', NULL, 1761758917, 1761758917),
(42214, 'Job 33:29', 'Job', 33, 29, 'بې‌شکه چې دا د خُدائ پاک کارونه دى، او د انسان دپاره يې بار بار کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_029.mp3', NULL, 1761758917, 1761758917),
(42215, 'Job 33:30', 'Job', 33, 30, 'هغه يې د قبر نه بچ کوى، او د ژوند په خوند يې پوهوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_030.mp3', NULL, 1761758917, 1761758917),
(42216, 'Job 33:31', 'Job', 33, 31, 'ايُوبه، ما ته توجو شه او ما ته غوږ ونيسه، تۀ خاموش اوسه او زۀ به خبرې کوم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_031.mp3', NULL, 1761758917, 1761758917),
(42217, 'Job 33:32', 'Job', 33, 32, 'کۀ تۀ څۀ وائې، نو ووايه، زۀ غواړم چې تا بې‌ګناه ثابت کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_032.mp3', NULL, 1761758917, 1761758917),
(42218, 'Job 33:33', 'Job', 33, 33, 'کۀ داسې نۀ وى، نو ما ته غوږ ونيسه، خاموش شه او زۀ به تا ته د عقل ښودنه وکړم.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job33_verse_033.mp3', NULL, 1761758917, 1761758917),
(42219, 'Job 2:1', 'Job', 2, 1, 'يو ځل آسمانى مخلوق راغلو چې خپل ځانونه د مالِک خُدائ په مخکښې حاضر کړى او شېطان هم د هغوئ سره راغلو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_001.mp3', NULL, 1761758917, 1761758917),
(42220, 'Job 2:2', 'Job', 2, 2, 'مالِک خُدائ شېطان ته وفرمائيل، ”تا څۀ کول؟“ نو شېطان ووئيل، ”زۀ په زمکه ګرځېدم راګرځېدم.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_002.mp3', NULL, 1761758917, 1761758917),
(42221, 'Job 2:3', 'Job', 2, 3, 'نو مالِک خُدائ شېطان ته وفرمائيل، ”ستا زما د خِدمت کوونکى ايُوب په باره کښې څۀ خيال دے؟ په زمکه باندې د هغۀ په شان هيڅ څوک هم نشته، هغه يو بې‌داغه او نېک سړے دے چې هغه د خُدائ پاک نه يريږى او د بدۍ نه ځان ساتى. هغه تر اوسه پورې په خپل صداقت کښې قائم دے، اګر چې تا زۀ د هغۀ خِلاف لمسولم، چې بغېر د څۀ وجې نه يې په غضب آخته کړم.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_003.mp3', NULL, 1761758917, 1761758917),
(42222, 'Job 2:4', 'Job', 2, 4, 'بيا شېطان مالِک خُدائ ته ووئيل، ”خلق د خپل ژوند بچ کولو دپاره هر څۀ ورکوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_004.mp3', NULL, 1761758917, 1761758917),
(42223, 'Job 2:5', 'Job', 2, 5, 'خو کۀ د هغۀ په بدن باندې تکليف راولې، نو هغه به ستا په حضور کښې په تا لعنت ووائى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_005.mp3', NULL, 1761758917, 1761758917),
(42224, 'Job 2:6', 'Job', 2, 6, 'نو مالِک خُدائ شېطان ته وفرمائيل، ”بلکل ټيک ده هغه ستا په اختيار کښې دے خو هغه ژوندے پرېږده.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_006.mp3', NULL, 1761758917, 1761758917),
(42225, 'Job 2:7', 'Job', 2, 7, 'نو شېطان د مالِک خُدائ د حضور نه لاړو او په ايُوب باندې يې د سر نه تر پښو پورې خرابې دانې راوخېژولې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_007.mp3', NULL, 1761758917, 1761758917),
(42226, 'Job 2:8', 'Job', 2, 8, 'نو ايُوب د خاورې د مات لوښى يوه ټوټه واخستله او ځان يې ورباندې ګرولو او په ايرو باندې کښېناستو چې خپل خفګان څرګند کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_008.mp3', NULL, 1761758917, 1761758917),
(42227, 'Job 2:9', 'Job', 2, 9, 'نو ايُوب ته خپلې ښځې ووئيل، ”تر اوسه پورې تۀ لا په خپل صداقت قائم يې؟ په خُدائ پاک لعنت ووايه او مړ شه.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_009.mp3', NULL, 1761758917, 1761758917),
(42228, 'Job 2:10', 'Job', 2, 10, 'خو هغۀ خپلې ښځې ته وفرمائيل، ”تۀ خو لکه د کم عقلې ښځې په شان خبرې کوې، ولې مونږ به د خُدائ د طرفه صرف ښۀ څيزونه اخلو څۀ او هيڅکله به ترې نه بد نۀ اخلو؟“ خو د دې ټولو خبرو باوجود ايُوب د خُدائ پاک خِلاف يوه خبره هم ونۀ کړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_010.mp3', NULL, 1761758917, 1761758917),
(42229, 'Job 2:11', 'Job', 2, 11, 'نو چې کله د ايُوب درې ملګرى د هغه ټولو مصيبتونو نه خبر شول کوم چې په ايُوب باندې راغلى وُو، نو هغوئ هر يو د خپل خپل کور نه روان شول هغوئ په يو ځائ ايُوب له ورغلل چې د تسلۍ خبرې ورته وکړى. د هغوئ نومونه دا دى، اليفز تيمانى، بِلداد شوحى، او ضوفر نعماتى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_011.mp3', NULL, 1761758917, 1761758917),
(42230, 'Job 2:12', 'Job', 2, 12, 'کله چې هغوئ ايُوب د لرې نه وليدلو، نو هغه د پېژندګلو نه وتے وو خو چې کله يې وپېژندو نو په چغو چغو يې وژړل، هغوئ د غم نه خپلې چُوغې وشلولې او په سر باندې يې خاورې واچولې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_012.mp3', NULL, 1761758917, 1761758917),
(42231, 'Job 2:13', 'Job', 2, 13, 'هغوئ د هغۀ سره په زمکه باندې اووۀ شپې او اووۀ ورځې ناست وُو او يو کس هم هغۀ ته يوه خبره هم ونۀ کړه، ځکه چې هغوئ ته پته وه چې د هغۀ تکليف ډېر زيات دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job2_verse_013.mp3', NULL, 1761758917, 1761758917),
(42232, 'Ecclesiastes 11:1', 'Ecclesiastes', 11, 1, 'خپلې دانې په لمده ځمکه کې وشینده ځکه څو ورځې وروسته به ته هغه بېرته حاصل کړې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_001.mp3', NULL, 1761758917, 1761758917),
(42233, 'Ecclesiastes 11:2', 'Ecclesiastes', 11, 2, 'د خپلو دانو یوه برخه له اوو اتو کسانو سره شریکې کړه ځکه ته نه پوهېږې چې په ځمکه باندې به څه افت راځي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_002.mp3', NULL, 1761758917, 1761758917),
(42234, 'Ecclesiastes 11:3', 'Ecclesiastes', 11, 3, 'که ورېځې نمجنې او درندې شي نو په ځمکه باندې باران وریږي او که ونه جنوب یا شمال لوري ته چپه شي نو په هماغه ځای به پرته وي چې پرې رالویږي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_003.mp3', NULL, 1761758917, 1761758917),
(42235, 'Ecclesiastes 11:4', 'Ecclesiastes', 11, 4, 'څوک چې د باد لوري ته ګوري هغه بیا څه نه کري او څوک چې ورېځو ته ګوري هغه بیا حاصل نه رېبي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_004.mp3', NULL, 1761758917, 1761758917),
(42236, 'Ecclesiastes 11:5', 'Ecclesiastes', 11, 5, 'لکه څنګه چې ته نه پوهېږې چې باد له کوم ځایه لګیږي یا د امیدوارې ښځې په ګېډه کې ماشوم څرنګه لوییږي نو همدا شان ته د خدای په کارونو هم نه پوهېږې چې دا دواړه د هغه له خوا تر‌سره کیږي', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_005.mp3', NULL, 1761758917, 1761758917),
(42237, 'Ecclesiastes 11:6', 'Ecclesiastes', 11, 6, 'په سهار کې خپل تخم وکره او په ماښام کې هم لاس تر زنې مه کښېنه ځکه ته نه پوهېږې چې په کوم کار کې بریالیتوب شته په دې کار کې یا په هغه بل کار کې یا په دواړو کې په برابره توګه بریالیتوب شته', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_006.mp3', NULL, 1761758917, 1761758917),
(42238, 'Ecclesiastes 11:7', 'Ecclesiastes', 11, 7, 'نو د لمر روښنایي څومره خوږه ده او د انسان دپاره څومره ښه ده چې د لمر د روښنایۍ لاندې واوسیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_007.mp3', NULL, 1761758917, 1761758917),
(42239, 'Ecclesiastes 11:8', 'Ecclesiastes', 11, 8, 'په حقیقت کې، یو سړی چې ډېر کلونه عمر کوي هغه باید خوشحالي وکړي او له خپل ژوند نه خوند واخلي، خو هغه باید په یاد ولري چې د تیارې ورځې ډېرې زیاتې وي. نو هرڅه چې په راتلونکې کې پېښیږي هغه ټول لوګي او پوکي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_008.mp3', NULL, 1761758917, 1761758917),
(42240, 'Ecclesiastes 11:9', 'Ecclesiastes', 11, 9, 'نو ای ځوانه! د ځوانۍ په ورځو کې خوشحالي وکړه او د خپل ځلمیتوب له هرې شېبې نه یې خوند واخله. چېرته چې ستا زړه ځي او سترګې دې ګوري هلته دې ستا پښې هم لاړې شي. خو په دې پوه شه چې خدای به ستا د زړه د ارمانونو او عملونو قضاوت وکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_009.mp3', NULL, 1761758917, 1761758917),
(42241, 'Ecclesiastes 11:10', 'Ecclesiastes', 11, 10, 'له خپل زړه څخه غم او غوسه لېرې کړه او له خپل بدن څخه درد او کړاو وباسه، ځکه چې ځواني او د ځلمیتوب سباوون لوګی او پوکی دی.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ecclesiastes11_verse_010.mp3', NULL, 1761758917, 1761758917),
(42242, 'Ezekiel 38:1', 'Ezekiel', 38, 1, 'څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_001.mp3', NULL, 1761758917, 1761758917),
(42243, 'Ezekiel 38:2', 'Ezekiel', 38, 2, '«ای فاني انسانه، خپل مخ دې د جوج خواته چې د ماجوج د هېواد څخه دی او د ماشک او توبال پاچا دی، واړوه او د هغه په ضد نبوت وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_002.mp3', NULL, 1761758917, 1761758917),
(42244, 'Ezekiel 38:3', 'Ezekiel', 38, 3, 'زه څښتن تعالی داسې وایم: ‹ګوره، ای جوجه، د ماشک او توبال پاچا، زه ستا دښمن یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_003.mp3', NULL, 1761758917, 1761758917),
(42245, 'Ezekiel 38:4', 'Ezekiel', 38, 4, 'زه به تا راوګرځوم، ستا په ژامو کې به چنګکونه واچوم او تا به د خپلو ټولو لښکرو، اسونو او سپرو عسکرو سره چې شمېر یې ډېر زیات دی او ټول په زغرو، وړو او لویو سپرونو او تورو باندې سمبال دي، راوباسم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_004.mp3', NULL, 1761758917, 1761758917),
(42246, 'Ezekiel 38:5', 'Ezekiel', 38, 5, 'د هغوی سره به د فارس، ایتوپیا او لیبیا لښکرې وي چې د هغوی ټولو سره به سپرونه او د زغرو خولۍ‌ګانې وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_005.mp3', NULL, 1761758917, 1761758917),
(42247, 'Ezekiel 38:6', 'Ezekiel', 38, 6, 'د جومر او د شمال د لېرې ځای نه د بیت‌توجرمه د وطنونو څخه به ټول جنګیالي د هغه سره وي، یعنې د ډېرو قومونو سړي به ورسره وي.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_006.mp3', NULL, 1761758917, 1761758917),
(42248, 'Ezekiel 38:7', 'Ezekiel', 38, 7, 'هغه ته ووایه: ‹تیار اوسه، ته او ستا ټولې شاوخوا لښکرې باید ستا تر قوماندې لاندې تیاری ونیسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_007.mp3', NULL, 1761758917, 1761758917),
(42249, 'Ezekiel 38:8', 'Ezekiel', 38, 8, 'له ډېرو کلونو وروسته به زه تاته حکم درکړم چې په اسراییلو باندې حمله وکړې. دا به داسې هېواد وي چې خلک یې د جنګ نه وروسته ځای په ځای شوي وي. خلک به یې د ډېرو قومونو څخه راټول شوي وي او په هغو غرونو کې به واوسیږي چې ډېره موده وران او ویجاړ پراته وو. هغه وخت به هغوی ټول په امن کې ژوند تېر کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_008.mp3', NULL, 1761758917, 1761758917),
(42250, 'Ezekiel 38:9', 'Ezekiel', 38, 9, 'ته او ستا لښکر او ستا سره نور ډېر قومونه به لکه د توفان په شان حمله وکړئ او هغه وطن به لکه د ورېځې په شان پټ کړئ.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_009.mp3', NULL, 1761758917, 1761758917),
(42251, 'Ezekiel 38:10', 'Ezekiel', 38, 10, 'څښتن تعالی جوج ته داسې وایي: ‹کله چې هغه وخت راورسیږي، نو ستا ذهن ته به بد فکرونه راشي او یوه ناوړه نقشه به جوړه کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_010.mp3', NULL, 1761758917, 1761758917),
(42252, 'Ezekiel 38:11', 'Ezekiel', 38, 11, 'د ځان سره به ووایې چې په یو داسې بې‌وزله وطن باندې حمله کوم چې خلک یې په داسې ښارګوټو کې په امن او ارامۍ سره ژوند تېروي چې نه دېوالونه لري، نه دروازې او نه اړمونه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_011.mp3', NULL, 1761758917, 1761758917),
(42253, 'Ezekiel 38:12', 'Ezekiel', 38, 12, 'ته به هغه خلک لوټ او تالا کړې چې په داسې ښارونو کې اوسیږي چې یو وخت وران پراته وو. هغوی د نورو قومونو نه راټول شوي، اوس د څارویو او د مال او جایداد خاوندان دي او د نړۍ د سوداګرۍ په مرکز کې اوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_012.mp3', NULL, 1761758917, 1761758917),
(42254, 'Ezekiel 38:13', 'Ezekiel', 38, 13, 'د شیبا او ددان خلک او د ترشیش د ښار سوداګران به ستا نه پوښتنه کوي: ”ایا تا خپل لښکر راټول کړی چې د لوټ او تالان په خاطر حمله وکړې؟ ایا دا نیت لرې چې سپین زر، سره زر، څاروي او ډېره شتمني په غنیمت یوسئ؟“›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_013.mp3', NULL, 1761758917, 1761758917),
(42255, 'Ezekiel 38:14', 'Ezekiel', 38, 14, 'نو په دې خاطر ای فاني انسانه، نبوت وکړه او جوج ته ووایه چې څښتن تعالی داسې وایي: ‹کله چې ته ووینې چې زما قوم په امن کې ژوند تېروي، نو راویښ به شې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_014.mp3', NULL, 1761758917, 1761758917),
(42256, 'Ezekiel 38:15', 'Ezekiel', 38, 15, 'ته به د خپل ځای نه چې لېرې په شمال کې دی، د خپل لوی او قوي لښکر سره چې د ډېرو قومونو د عسکرو نه جوړ شوی دی او ټول به په اسونو باندې سپاره وي، راشې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_015.mp3', NULL, 1761758917, 1761758917),
(42257, 'Ezekiel 38:16', 'Ezekiel', 38, 16, 'تاسو به زما په قوم اسراییلو باندې داسې حمله کوئ، لکه ځمکه چې ورېځ پټوي. په وروستیو ورځو کې به زه تا ولېږم چې زما په وطن باندې حمله وکړې، ترڅو ای جوجه، قومونه په دې پوه شي چې زه څوک یم او ستا په وسیله به خپل سپېڅلتوب وښایم.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_016.mp3', NULL, 1761758917, 1761758917),
(42258, 'Ezekiel 38:17', 'Ezekiel', 38, 17, '«څښتن تعالی داسې وایي: ‹ایا ته هغه څوک یې چې ډېر پخوا مې ستا په هکله خبرې کړې وې؟ هغه وخت ما د خپلو خدمتګارانو یعنې د اسراییلو د نبیانو په وسیله ویلي وو. هغوی تر ډېرو کلونو پورې پېشګویي کوله چې په راتلونکو ورځو کې به زه یو کس په اسراییلو باندې د حملې دپاره راولم.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_017.mp3', NULL, 1761758917, 1761758917),
(42259, 'Ezekiel 38:18', 'Ezekiel', 38, 18, 'څښتن تعالی وایي: ‹په هماغه ورځ چې جوج په اسراییلو باندې حمله وکړي، نو زه به سخت په قهر یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_018.mp3', NULL, 1761758917, 1761758917),
(42260, 'Ezekiel 38:19', 'Ezekiel', 38, 19, 'زه په خپل غیرت او په سخت قهر کې اعلان کوم چې په هغه ورځ به د اسراییلو په وطن کې سخته زلزله وشي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_019.mp3', NULL, 1761758917, 1761758917),
(42261, 'Ezekiel 38:20', 'Ezekiel', 38, 20, 'ټول ماهیان او مرغان، ټول لوی حیوانات، خزندې او د ځمکې په مخ ټول انسانان به زما په حضور کې ولړزیږي. غرونه به راوغورځول شي، کمرې به ونړیږي او ټول دېوالونه به راچپه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_020.mp3', NULL, 1761758917, 1761758917),
(42262, 'Ezekiel 38:21', 'Ezekiel', 38, 21, 'زه به په خپلو ټولو غرونو کې د جوج په ضد جنګ راولم، ما څښتن تعالی داسې ویلي دي. د هغه عسکر به په خپلو کې یو بل په تورو باندې ووهي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_021.mp3', NULL, 1761758917, 1761758917),
(42263, 'Ezekiel 38:22', 'Ezekiel', 38, 22, 'زه به هغه په وبا او وینې تویولو سره محاکمه او هغه ته به سزا ورکړم. زه به په هغه او د هغه په لښکرو او نورو ډېرو قومونو باندې چې د هغه په خوا ولاړ دي، د باران توفان او ږلۍ د اور او ګوګړو سره نازل کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_022.mp3', NULL, 1761758917, 1761758917),
(42264, 'Ezekiel 38:23', 'Ezekiel', 38, 23, 'په دې ډول به زه ډېرو قومونو ته وښایم چې زه ډېر لوی او سپېڅلی ذات یم. نو بیا به هغوی پوه شي چې زه څښتن یم.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel38_verse_023.mp3', NULL, 1761758917, 1761758917),
(42265, 'Isaiah 4:1', 'Isaiah', 4, 1, 'کله چې هغه ورځ راشي، نو اووه ښځې به د یو سړي لمن ونیسي او ورته به ووایي: «مونږ په خپله د خپلو ځانونو دپاره خوراک او کالي تیاروو، یوازې غواړو چې ته زمونږ مېړه اوسې، ترڅو له دې شرمه وژغورل شو چې مونږ واده شوې نه یو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah4_verse_001.mp3', NULL, 1761758917, 1761758917),
(42266, 'Isaiah 4:2', 'Isaiah', 4, 2, 'هغه ورځ راتلونکې ده چې څښتن به د دې وطن هر بوټی او ونه لویه او ښایسته کړي او هغه حاصلات چې ځمکه یې ورکوي هغه به د هغو ټولو اسراییلیانو دپاره چې ژوندي پاتې کیږي، د ویاړ او عزت سبب شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah4_verse_002.mp3', NULL, 1761758917, 1761758917),
(42267, 'Isaiah 4:3', 'Isaiah', 4, 3, 'هغه خلک چې په صهیون کې پاتې شوي دي او لیکل شوي دي چې په اورشلیم کې به ژوندي واوسي، نو هغوی به سپېڅلي وګڼل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah4_verse_003.mp3', NULL, 1761758917, 1761758917),
(42268, 'Isaiah 4:4', 'Isaiah', 4, 4, 'له دې نه مخکې به څښتن د اسراییلو د قوم په هکله قضاوت وکړي او هغه به پاک کړي او د اورشلیم ګناهونه او هغه وینه چې هلته توی شوې ده، هغه به ووینځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah4_verse_004.mp3', NULL, 1761758917, 1761758917),
(42269, 'Isaiah 4:5', 'Isaiah', 4, 5, 'بیا به څښتن د صهیون په غره باندې او په هغو ټولو خلکو باندې چې په هغه ځای کې راټولیږي، د ورځې له خوا ورېځ او د شپې له خوا به ورباندې لوګی او د اور ځلېدونکې لمبې نازلې کړي. دا به د دې جلالي ځای دپاره یو پوښ وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah4_verse_005.mp3', NULL, 1761758917, 1761758917),
(42270, 'Isaiah 4:6', 'Isaiah', 4, 6, 'د هغه جلال به په ښار باندې د جونګړې په شان سیوری جوړ کړي چې د ورځې له ګرمۍ نه او همدارنګه د توفان او باران څخه یې خوندي وساتي او د هغه څخه به د امن ځای جوړ کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah4_verse_006.mp3', NULL, 1761758917, 1761758917),
(42271, 'Isaiah 34:1', 'Isaiah', 34, 1, 'ای د ټولو قومونو خلکو، نژدې راشئ او غوږ ونیسئ. ای د نړۍ ټولو خلکو واورئ!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_001.mp3', NULL, 1761758917, 1761758917),
(42272, 'Isaiah 34:2', 'Isaiah', 34, 2, 'ځکه څښتن په ټولو قومونو او د هغوی په لښکرو ډېر په قهر دی. هغوی به په مرګ محکوم او ټول به حلال کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_002.mp3', NULL, 1761758917, 1761758917),
(42273, 'Isaiah 34:3', 'Isaiah', 34, 3, 'د هغوی مړي به نه ښخیږي، د خوسا شویو مړو بوی به ټوله ځمکه ونیسي او د هغوی وینې به د غرونو نه جاري شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_003.mp3', NULL, 1761758917, 1761758917),
(42274, 'Isaiah 34:4', 'Isaiah', 34, 4, 'لمر، سپوږمۍ او ستوري به خواره واره او فنا شي. اسمان به لکه د طومار په شان تاو او راتاو شي او ستوري به داسې راولویږي لکه څنګه چې د انګورو د تاک څخه وچې پاڼې او د انځرو د ونو څخه وچ انځر رالویږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_004.mp3', NULL, 1761758917, 1761758917),
(42275, 'Isaiah 34:5', 'Isaiah', 34, 5, 'د څښتن تورې خپل کار په اسمان کې سر ته رسولی دی او اوس به د ادوم په خلکو ګوزار وکړي، یعنې هغه خلک چې څښتن په نابودۍ محکوم کړي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_005.mp3', NULL, 1761758917, 1761758917),
(42276, 'Isaiah 34:6', 'Isaiah', 34, 6, 'د هغه توره به په وینو رنګ او په وازګو کې پټه وي، یعنې د وریو او وزو په وینو او همدارنګه د پسونو د پښتورګو په وازګو کې. هو، څښتن به د ادوم د هېواد او د بزرې په ښار کې ډېر خلک لکه د قربانۍ په شان حلال کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_006.mp3', NULL, 1761758917, 1761758917),
(42277, 'Isaiah 34:7', 'Isaiah', 34, 7, 'حتی هغه خلک به هم مړه شي چې د ځنګلي غویانو او سخوندرانو په شان قوي دي. ځمکه به په وینو خړوبه او په وازګو به پټه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_007.mp3', NULL, 1761758917, 1761758917),
(42278, 'Isaiah 34:8', 'Isaiah', 34, 8, 'ځکه څښتن له دښمنانو څخه د بدل د اخیستلو ورځ او د صهیون د تاوان ورکولو دپاره یې کال ټاکلی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_008.mp3', NULL, 1761758917, 1761758917),
(42279, 'Isaiah 34:9', 'Isaiah', 34, 9, 'د ادوم سیندونه به د قیر څخه ډک او خاوره به یې په ګوګړو بدله شي او ټول وطن به د قیر په شان وسوځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_009.mp3', NULL, 1761758917, 1761758917),
(42280, 'Isaiah 34:10', 'Isaiah', 34, 10, 'ادوم به شپه او ورځ سوځي او تل به ورڅخه لوګی پورته کیږي. هغه وطن به له یو نسله تر بل نسله پورې وران وي او نور به هېڅوک له هغه ځایه تېر نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_010.mp3', NULL, 1761758917, 1761758917),
(42281, 'Isaiah 34:11', 'Isaiah', 34, 11, 'کونګیان او کارغان به هغه هېواد ونیسي او هغوی به په کې واوسیږي، ځکه څښتن اراده لري چې ادوم له منځه یوسي او هغه شاړ او خالي پرېږدي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_011.mp3', NULL, 1761758917, 1761758917),
(42282, 'Isaiah 34:12', 'Isaiah', 34, 12, 'د اشرافو څخه به هېڅوک ژوندی پاتې نه شي، ترڅو پاچا شي او ټول مشران به له منځه لاړ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_012.mp3', NULL, 1761758917, 1761758917),
(42283, 'Isaiah 34:13', 'Isaiah', 34, 13, 'په ټولو ماڼیو او دېوال لرونکو ښارونو کې به اغزي راشنه شي او سورلنډیان او کونګیان به په کې اوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_013.mp3', NULL, 1761758917, 1761758917),
(42284, 'Isaiah 34:14', 'Isaiah', 34, 14, 'په ادوم کې به د صحرا حیوانات د لېوانو سره قدم وهي او د وزانو په شکل پېریان به په کې یو بل ته نارې وهي. همدارنګه د مرغۍ په شان دېوان به د شپې په وخت هلته ځي چې د ارام کولو دپاره ځای پیدا کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_014.mp3', NULL, 1761758917, 1761758917),
(42285, 'Isaiah 34:15', 'Isaiah', 34, 15, 'کونګیان به په ادوم کې خپلې ځالې جوړوي، هګۍ به په کې اچوي، بچي به ورنه وباسي او د خپلو بچیو ساتنه به کوي. هلته به د باښو جوړې هم راشي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_015.mp3', NULL, 1761758917, 1761758917),
(42286, 'Isaiah 34:16', 'Isaiah', 34, 16, 'د څښتن کلام ولټوئ او ولولئ، ترڅو پوه شئ چې د هغه ټولې پېشګویۍ عملي کیږي. ټول وحشي حیوانات او مرغان به حاضر وي او هېڅ یو به بې جوړې نه وي. ځکه څښتن په خپله دا ویلي دي او د هغه روح به هغوی راټول کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_016.mp3', NULL, 1761758917, 1761758917),
(42287, 'Isaiah 34:17', 'Isaiah', 34, 17, 'دا څښتن دی چې د ادوم اندازه یې معلومه کړې ده او حیوانات او مرغان یې په کې وېشلي دي، ترڅو هغه هېواد تل د هغوی شي او نسل په نسل په هغه کې واوسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah34_verse_017.mp3', NULL, 1761758917, 1761758917),
(42288, 'Job 40:1', 'Job', 40, 1, 'بيا مالِک خُدائ ايُوب ته وفرمائيل،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_001.mp3', NULL, 1761758917, 1761758917),
(42289, 'Job 40:2', 'Job', 40, 2, '”تۀ اوس هم د قادر خُدائ سره بحث کول غواړې څۀ؟ څوک چې د خُدائ پاک سره بحث کوى نو هغه به جواب ورکوى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_002.mp3', NULL, 1761758917, 1761758917),
(42290, 'Job 40:3', 'Job', 40, 3, 'بيا ايُوب مالِک خُدائ له جواب ورکړو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_003.mp3', NULL, 1761758917, 1761758917),
(42291, 'Job 40:4', 'Job', 40, 4, '”ګوره، زۀ هيڅ هم نۀ يم، زۀ به تا له څۀ جواب درکړم؟ زۀ په خپله خولۀ باندې لاس ږدم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_004.mp3', NULL, 1761758917, 1761758917),
(42292, 'Job 40:5', 'Job', 40, 5, 'ما ډېر څۀ وئيلى دى، نور زۀ څۀ نۀ وايم.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_005.mp3', NULL, 1761758917, 1761758917),
(42293, 'Job 40:6', 'Job', 40, 6, 'بيا مالِک خُدائ د طوفان نه ايُوب له جواب ورکړو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_006.mp3', NULL, 1761758917, 1761758917),
(42294, 'Job 40:7', 'Job', 40, 7, '”نو اوس ورته ټينګ شه، زۀ به ستا نه تپوس وکړم او تۀ به ما له جواب راکړې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_007.mp3', NULL, 1761758917, 1761758917),
(42295, 'Job 40:8', 'Job', 40, 8, 'ولې تۀ د دې ثابِتولو کوشش کوې چې زۀ بې‌اِنصافه يم، او ما غلط وګڼې او خپل ځان ته صحيح ووائې؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_008.mp3', NULL, 1761758917, 1761758917),
(42296, 'Job 40:9', 'Job', 40, 9, 'تۀ د خُدائ پاک په شان تکړه يې څۀ، ستا آواز د هغۀ د تندر د آواز په شان کېدے شى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_009.mp3', NULL, 1761758917, 1761758917),
(42297, 'Job 40:10', 'Job', 40, 10, 'کۀ داسې وى نو په رُعب داب او شان و شوکت سره خپل ځان سنګار کړه، د عزت او درناوى په جامو باندې خپل ځان پټ کړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_010.mp3', NULL, 1761758917, 1761758917),
(42298, 'Job 40:11', 'Job', 40, 11, 'خپل ځان په قهر کړه، هر يو مغرور سړى ته ګوره او هغه سپک کړه،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_011.mp3', NULL, 1761758917, 1761758917),
(42299, 'Job 40:12', 'Job', 40, 12, 'ټولو مغروره خلقو ته وګوره او هغوئ عاجزان کړه، او بدعمله خلق ټک سره ووژنه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_012.mp3', NULL, 1761758917, 1761758917),
(42300, 'Job 40:13', 'Job', 40, 13, 'هغوئ ټول په خاورو کښې ښخ کړه، او هغوئ قبر کښې قېد کړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_013.mp3', NULL, 1761758917, 1761758917),
(42301, 'Job 40:14', 'Job', 40, 14, 'نو زۀ به دې هم صِفت وکړم، ځکه چې خپل طاقت تا بچ کولے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_014.mp3', NULL, 1761758917, 1761758917),
(42302, 'Job 40:15', 'Job', 40, 15, 'دريابى مېښې ته وګوره، چې هغه مې هم هغه شان جوړه کړې ده لکه څنګه مې چې تۀ جوړ کړے يې، دا د يو غوَيى په شان واښۀ خورى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_015.mp3', NULL, 1761758917, 1761758917),
(42303, 'Job 40:16', 'Job', 40, 16, 'د هغې طاقت د هغې په بدن کښې دے، او د هغې طاقت د هغې د خېټې په پټو کښې دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_016.mp3', NULL, 1761758917, 1761758917),
(42304, 'Job 40:17', 'Job', 40, 17, 'د هغې لکۍ لکه د دِيار د ونې په شان سخته ده، د هغې د پتُون پټې خپلو کښې غوټه شوې دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_017.mp3', NULL, 1761758917, 1761758917),
(42305, 'Job 40:18', 'Job', 40, 18, 'د دې هډوکى د زېړو نلکې دى، د هغې هډوکى د اوسپنې سيخونه دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_018.mp3', NULL, 1761758917, 1761758917),
(42306, 'Job 40:19', 'Job', 40, 19, 'دا د خُدائ پاک د کارنامو يو لوئ کار دے، او صرف د دې خالِق په دې باندې قابو موندلے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_019.mp3', NULL, 1761758917, 1761758917),
(42307, 'Job 40:20', 'Job', 40, 20, 'ځکه چې غرونه د دې دپاره خوراک پېدا کوى چرته چې ټول ځنګلى ځناور لوبې کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_020.mp3', NULL, 1761758917, 1761758917),
(42308, 'Job 40:21', 'Job', 40, 21, 'دا په اوبو کښې د نيلوفر بوټو لاندې پراتۀ وى او د لوخې په ډنډونو کښې پټ وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_021.mp3', NULL, 1761758917, 1761758917),
(42309, 'Job 40:22', 'Job', 40, 22, 'د نيلوفر بوټى ورباندې سورے کوى، او د نِهر د غاړې د وَلو ونې د دې نه ګېرچاپېره تاو وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_022.mp3', NULL, 1761758917, 1761758917),
(42310, 'Job 40:23', 'Job', 40, 23, 'کۀ سيند په موج کښې وى، نو دا نۀ يريږى، د اُردن سيند کۀ تر خولې پورې هم ډک وى نو دا نۀ يريږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_023.mp3', NULL, 1761758917, 1761758917),
(42311, 'Job 40:24', 'Job', 40, 24, 'څوک دا د کُنډو سره راوچتولے شى، يا يې څوک په پوزه کښې د قابو کولو دپاره پېزوان اچولے شى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job40_verse_024.mp3', NULL, 1761758917, 1761758917),
(42312, 'Songofsongs 6:1', 'Songofsongs', 6, 1, 'ستا جانان چرته لاړونه، په ټولو پېغلو کښې ښائسته جينۍ؟ ستا جانان چرته تلے دېنه؟ چې مونږ تا سره د هغۀ تلاش وکړونه؟ محبوبه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_001.mp3', NULL, 1761758917, 1761758917),
(42313, 'Songofsongs 6:2', 'Songofsongs', 6, 2, 'زما جانان خپل باغ ته راغلے دېنه، خپل د خوشبويانو کټ ته، چې خپله رمه په باغونو کښې وڅروينه، او د لاله ګلونه ترې نه راټول کړينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_002.mp3', NULL, 1761758917, 1761758917),
(42314, 'Songofsongs 6:3', 'Songofsongs', 6, 3, 'جانان زما او زۀ د جانان يمه، هغه چې د لاله په ګلونو کښې مزې کوينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_003.mp3', NULL, 1761758917, 1761758917),
(42315, 'Songofsongs 6:4', 'Songofsongs', 6, 4, 'زما محبوبې، تۀ لکه د تِرضاه د ښار په شان ښائسته ينه. آو، لکه د يروشلم په شان ښائسته ينه، او په يو ځل ليدو دې ما نه زړګے وړے دېنه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_004.mp3', NULL, 1761758917, 1761758917),
(42316, 'Songofsongs 6:5', 'Songofsongs', 6, 5, 'سترګې دې ما نه واړوه، ځکه چې زۀ يې بې‌وسه کړے يمه. ستا زلفى وَل وَل لکه د چېلو د رمو په شان دينه، چې د جِلعاد د غرۀ نه لاندې راکوزيږينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_005.mp3', NULL, 1761758917, 1761758917),
(42317, 'Songofsongs 6:6', 'Songofsongs', 6, 6, 'ستا غاښونه د سپينو ګډو په شان دينه، چې تازه ترې نه وړۍ اخوا شوې وينه، او تازه لمبولے شوے وينه. هر يو غاښ دې د بل سره جوړه دېنه، يو هم کنډم شوے نۀ دېنه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_006.mp3', NULL, 1761758917, 1761758917),
(42318, 'Songofsongs 6:7', 'Songofsongs', 6, 7, 'ستا اننګى د نقاب شاته لکه د ګلابى انار ځليږينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_007.mp3', NULL, 1761758917, 1761758917),
(42319, 'Songofsongs 6:8', 'Songofsongs', 6, 8, 'په شپېتو مَلِکو او په اتيا وينځو کښې او په بې‌شمېره پېغلو کښې،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_008.mp3', NULL, 1761758917, 1761758917),
(42320, 'Songofsongs 6:9', 'Songofsongs', 6, 9, 'خو زۀ به بيا هم خپله ګوګوشتکه خوښومه، زما کامله مينه، د خپلې مور ډېره خوښه ده نه، او د هغه چا ډېره نيازبينه چا چې زيږولې ده نه. پېغلې هغه وينى او د هغې صِفت کوينه، تر دې چې شهزادګۍ او شاهى وينځې د هغې د صِفت سندرې وائينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_009.mp3', NULL, 1761758917, 1761758917),
(42321, 'Songofsongs 6:10', 'Songofsongs', 6, 10, '”دا څوک ده چې لکه د سحر د رڼا په شان راوچتيږينه، لکه د سپوږمۍ په شان ښائسته، او د نمر په شان ځليږينه، او په يو ځل ليدو دې ما نه زړګے وړے دېنه.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_010.mp3', NULL, 1761758917, 1761758917),
(42322, 'Songofsongs 6:11', 'Songofsongs', 6, 11, 'زۀ د غوزانو باغ ته لاړمه او وادۍ ته د ګلونو د غوټو سيل ته لاړمه، د انګورو د ځيلو راټوکېدل ووينمه او چې انارو ګلونه کړى دى کۀ نه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_011.mp3', NULL, 1761758917, 1761758917),
(42323, 'Songofsongs 6:12', 'Songofsongs', 6, 12, 'زۀ په خپل ځان نۀ پوهېدمه، او د عشق نه رپېدمه لکه چې په شاهى ګاډۍ کښې سور يمه ښځې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_012.mp3', NULL, 1761758917, 1761758917),
(42324, 'Songofsongs 6:13', 'Songofsongs', 6, 13, 'واپس راشه، مونږ ته راواپس شه، اے د شولم پېغلې. واپس راشه، واپس راشه چې مونږ تا دوباره وګورونه. محبوب تاسو د شولم دې پېغلې ته ولې ګورئينه کله چې هغه د ګډېدونکو د دوه صفونو په مينځ کښې ډېره ښائسته ګډيږينه؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs6_verse_013.mp3', NULL, 1761758917, 1761758917),
(42325, 'Isaiah 25:1', 'Isaiah', 25, 1, 'ای څښتنه، ته یې خدای زما زه به کومه درناوی ستا او ثنا او صفت به کوم ستا د نامه ځکه تا کړي دي ډېر عجیبه کارونه هغه څه چې پلان کړي تا پخوا وو په وفادارۍ دې رسولي هغه سرته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_001.mp3', NULL, 1761758917, 1761758917),
(42326, 'Isaiah 25:2', 'Isaiah', 25, 2, 'تا بدل کړي دي ښارونه کنډوالو باندې او ورانې کړې دې دي ټینګې کلاګانې کومې ماڼۍ چې جوړې کړې وې پردو قومونو هغه شوې ورانې د تل دپاره داسې چې بیا به جوړې نه شي هېڅکله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_002.mp3', NULL, 1761758917, 1761758917),
(42327, 'Isaiah 25:3', 'Isaiah', 25, 3, 'نو په دې خاطر به وکړي ثنا او صفت ستا د نړۍ د تکړه قومونو خلک او خلک به تا نه وېره وکړي د ظالمو قومونو په ښارونو کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_003.mp3', NULL, 1761758917, 1761758917),
(42328, 'Isaiah 25:4', 'Isaiah', 25, 4, 'ځکه چې ته د مصیبت په وخت کې یې ساتونکی د غریبو او بې وسه خلکو تا ورکړې ده پناه هغوی ته د توفانونو وخت کې او ورکړی دې دی سیوری د سوځوونکې ګرمۍ په وخت کې د توفان په شان دی پوکی د ظالمانو چې لګیږي په دېوال', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_004.mp3', NULL, 1761758917, 1761758917),
(42329, 'Isaiah 25:5', 'Isaiah', 25, 5, 'لکه ګرمي د صحرا چې وچوي ځمکه خو ای څښتنه، غلي کوې ته اوازونه د پردو قومونو داسې لکه ورېځ چې سړوي ډېره ګرمي نو غلې کوې ته همدارنګه سندره د ظالمو خلکو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_005.mp3', NULL, 1761758917, 1761758917),
(42330, 'Isaiah 25:6', 'Isaiah', 25, 6, 'مطلق قادر څښتن به د صهیون په غره باندې د نړۍ ټولو قومونو ته د خوندورو خوراکونو او د انګورو د ښو زړو شرابو مېلمستیا تیاره کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_006.mp3', NULL, 1761758917, 1761758917),
(42331, 'Isaiah 25:7', 'Isaiah', 25, 7, 'دلته به هغه د غم څادر لېرې کړي چې په ټولو خلکو باندې هوار دی او د قومونو څخه به هغه کفن لېرې کړي چې په هغوی باندې پروت دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_007.mp3', NULL, 1761758917, 1761758917),
(42332, 'Isaiah 25:8', 'Isaiah', 25, 8, 'څښتن تعالی به د تل دپاره مرګ لېرې کړي! هغه به د هرچا د سترګو اوښکې وچې کړي او د خپلو خلکو هغه رسوایي او بې عزتي چې هغوی په ټوله نړۍ کې ورسره مخامخ دي، لېرې کړي. دا په خپله څښتن ویلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_008.mp3', NULL, 1761758917, 1761758917),
(42333, 'Isaiah 25:9', 'Isaiah', 25, 9, 'په هغه ورځ به خلک داسې وایي: «وګورئ، هغه زمونږ خدای دی چې ورته سترګې په لاره وو او مونږ یې ژغورلي یو. هغه څښتن دی چې مونږ د هغه نه هیله لرله، نو په دې خاطر چې هغه مونږ ژغوري، باید د خوشحالۍ جشن جوړ کړو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_009.mp3', NULL, 1761758917, 1761758917),
(42334, 'Isaiah 25:10', 'Isaiah', 25, 10, 'څښتن به د صهیون د غره ساتنه کوي، خو د موآب خلک به داسې تر پښو لاندې شي لکه بوس چې په ډېران کې تر پښو لاندې کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_010.mp3', NULL, 1761758917, 1761758917),
(42335, 'Isaiah 25:11', 'Isaiah', 25, 11, 'هغوی به د خپلې ژغورنې په خاطر د لامبوزنو په شان لاس او پښې وهي، خو څښتن به د هغوی مهارت له منځه یوسي او غرور به یې مات کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_011.mp3', NULL, 1761758917, 1761758917),
(42336, 'Isaiah 25:12', 'Isaiah', 25, 12, 'څښتن به د موآب جنګي کلاګانې چې لوړ لوړ دېوالونه لري، راوغورځوي او د خاورو سره به یې خاورې کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah25_verse_012.mp3', NULL, 1761758917, 1761758917),
(42337, 'Isaiah 12:1', 'Isaiah', 12, 1, 'داسې ورځ راروانه ده چې تاسو به دا سندره ووایئ: «ای څښتنه، زه کوم شکرګزاري ستا! که څه هم ته راته په قهر وې اوس نور په قهر نه یې او ماته تسلي راکوې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah12_verse_001.mp3', NULL, 1761758917, 1761758917),
(42338, 'Isaiah 12:2', 'Isaiah', 12, 2, 'ګورئ، چې خدای زما ژغورونکی دی زه به هغه باندې توکل کوم او نور به نه وېرېږم ځکه څښتن خدای زه قوي کړمه د هغه په هکله زه سندره وایم زه یې ژغورلی یمه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah12_verse_002.mp3', NULL, 1761758917, 1761758917),
(42339, 'Isaiah 12:3', 'Isaiah', 12, 3, 'څنګه چې تږي خوشحالیږي د کوهي په اوبو همداسې کړي به خوشحالي هغوی په هغه وخت چې خدای وژغوري خپل قوم»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah12_verse_003.mp3', NULL, 1761758917, 1761758917),
(42340, 'Isaiah 12:4', 'Isaiah', 12, 4, 'هغه ورځ راروانه ده چې تاسو به دا سندره ووایئ: «کړئ د څښتن شکر ادا! وکړئ دعا یې په نوم! هغه چې څه کړي بیان یې کړئ ټولو قومونو ته هغوی ته ووایئ چې څومره ډک دی د هغه نوم د جلال نه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah12_verse_004.mp3', NULL, 1761758917, 1761758917),
(42341, 'Isaiah 12:5', 'Isaiah', 12, 5, 'څښتن ته ووایئ سندره د هغه د پر جلاله کارنامو په خاطر پرېږدئ چې نړۍ ټوله د دې څخه خبره شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah12_verse_005.mp3', NULL, 1761758917, 1761758917),
(42342, 'Isaiah 12:6', 'Isaiah', 12, 6, 'ای اوسېدونکو د صهیون په لوړ اواز ووهئ چیغې او سندرې د خوښۍ ووایئ ځکه ډېر لوی دی سپېڅلی خدای د اسراییلو او اوسیږي ستاسو منځ کې»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah12_verse_006.mp3', NULL, 1761758917, 1761758917),
(42343, 'Ezekiel 8:1', 'Ezekiel', 8, 1, 'زمونږ د جلاوطنۍ په شپږم کال، د شپږمې میاشتې په پنځمه ورځ زه په خپل کور کې د یهودا د مشرانو سره ناست وم. ناڅاپه د څښتن تعالی قوت په ما باندې نازل شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_001.mp3', NULL, 1761758917, 1761758917),
(42344, 'Ezekiel 8:2', 'Ezekiel', 8, 2, 'ما وکتل او په رویا کې مې د انسان په شان یو شکل ولیده. بدن یې د ملا نه ښکته د اور د لمبو په شان ښکاره کېده او د ملا نه پورته د یو ځلېدونکي فلز په شان ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_002.mp3', NULL, 1761758917, 1761758917),
(42345, 'Ezekiel 8:3', 'Ezekiel', 8, 3, 'وروسته بیا هغه یو شی چې د لاس په شان ؤ، را‌اوږد کړ او زه یې د ویښتانو څخه ونیولم. په دې وخت کې په رویا کې د خدای روح اسمان ته پورته کړم او زه یې په اورشلیم کې د څښتن د کور د دنننۍ حوېلۍ د شمالي دروازې خولې ته بوتلم. هلته یو بت ؤ چې خدای یې ډېر په قهر کړ او د هغه غیرت یې راوپاراوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_003.mp3', NULL, 1761758917, 1761758917),
(42346, 'Ezekiel 8:4', 'Ezekiel', 8, 4, 'نو هلته مې د اسراییلو د خدای جلال ولیده چې د هغې رویا په شان ؤ چې په دره کې مې لیدلې وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_004.mp3', NULL, 1761758917, 1761758917),
(42347, 'Ezekiel 8:5', 'Ezekiel', 8, 5, 'بیا څښتن ماته وویل: «ای فاني انسانه، اوس شمال خواته وګوره.» نو ما هغې خواته وکتل او د دروازې شمال خواته مې د هغه بت د قربانۍ ځای ولیده چې د خدای غیرت یې راپارولی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_005.mp3', NULL, 1761758917, 1761758917),
(42348, 'Ezekiel 8:6', 'Ezekiel', 8, 6, 'څښتن ماته وویل: «ای فاني انسانه، ته وینې چې د اسراییلو قوم په څه کارونو باندې اخته دی؟ ګوره چې هغوی د کرکې وړ کارونه کوي او دا د دې سبب ګرځي چې زه د خپل سپېڅلي ځای څخه لېرې شم. خو ته به د دې څخه نور هم زیات د کرکې وړ کارونه ووینې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_006.mp3', NULL, 1761758917, 1761758917),
(42349, 'Ezekiel 8:7', 'Ezekiel', 8, 7, 'هغه زه د دنننۍ حوېلۍ د دروازې خولې ته بوتلم او په دېوال کې یې راته یو سوری راوښود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_007.mp3', NULL, 1761758917, 1761758917),
(42350, 'Ezekiel 8:8', 'Ezekiel', 8, 8, 'هغه ماته وویل: «ای فاني انسانه، دا سوری لوی کړه.» او ما هغه سوری لوی کړ او هلته مې یوه دروازه ولیدله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_008.mp3', NULL, 1761758917, 1761758917),
(42351, 'Ezekiel 8:9', 'Ezekiel', 8, 9, 'هغه راته وویل: «دننه لاړ شه او وګوره چې هغوی څنګه ناوړه او د کرکې وړ کارونه په دې ځای کې سرته رسوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_009.mp3', NULL, 1761758917, 1761758917),
(42352, 'Ezekiel 8:10', 'Ezekiel', 8, 10, 'نو زه دننه ورغلم او ومې لیدل چې په دېوالونو باندې د خزندو، ناپاکو حیواناتو او د هغو ټولو بتانو نقشونه چې اسراییلیانو ورته عبادت کاوه، ویستل شوي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_010.mp3', NULL, 1761758917, 1761758917),
(42353, 'Ezekiel 8:11', 'Ezekiel', 8, 11, 'د اسراییلو د قوم اویا مشران د هغو په مخکې هلته ولاړ وو چې په هغو کې د شافان زوی یازنیا هم شامل ؤ. هر یو په خپلو لاسونو کې د خوشبویۍ د سوځولو لوښی نیولی ؤ او د هغه نه د خوشبویۍ لوګی پورته کېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_011.mp3', NULL, 1761758917, 1761758917),
(42354, 'Ezekiel 8:12', 'Ezekiel', 8, 12, 'څښتن زما څخه پوښتنه وکړه: «ای فاني انسانه، ایا تا لیدلي دي چې د اسراییلو ټول مشران په خپله کوټه کې په پټه د خپل بت عبادت کوي؟ هغوی داسې وایي: ‹څښتن مونږ نه ویني، ځکه چې هغه دا هېواد پریښی دی.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_012.mp3', NULL, 1761758917, 1761758917),
(42355, 'Ezekiel 8:13', 'Ezekiel', 8, 13, 'بیا څښتن وویل: «ته به د دې څخه وروسته د دې نه هم ډېر د کرکې وړ کارونه چې هغوی یې کوي، ووینې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_013.mp3', NULL, 1761758917, 1761758917),
(42356, 'Ezekiel 8:14', 'Ezekiel', 8, 14, 'نو هغه زه د څښتن د کور د شمالي دروازې خولې ته بوتلم او هلته یې ښځې راته وښودلې چې ناستې وې او د خپل خدای تموز په مرګ یې ژړا کوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_014.mp3', NULL, 1761758917, 1761758917),
(42357, 'Ezekiel 8:15', 'Ezekiel', 8, 15, 'هغه پوښتنه وکړه: «ای فاني انسانه، ایا ته دا وینې؟ خو ته به د دې څخه وروسته د دې نه هم ډېر ناوړه او د کرکې وړ کارونه ووینې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_015.mp3', NULL, 1761758917, 1761758917),
(42358, 'Ezekiel 8:16', 'Ezekiel', 8, 16, 'نو بیا هغه زه د څښتن د کور دنننۍ حوېلۍ ته بوتلم. هلته د څښتن د کور د ننوتلو دروازې ته نژدې د قربانۍ د ځای او برنډې ترمنځ پنځه ویشت سړي ولاړ وو. هغوی د عبادت ځای ته شاګانې اړولې وې او خپل مخونه یې ختیځ خواته اړولي وو او لمر ته یې عبادت کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_016.mp3', NULL, 1761758917, 1761758917),
(42359, 'Ezekiel 8:17', 'Ezekiel', 8, 17, 'څښتن ماته وویل: «ای فاني انسانه، ایا ته دا وینې؟ ایا دا لازمه ده چې د یهودا قوم دا د کرکې وړ کارونه تر‌سره کړي، په ټول هېواد کې ظلم او زیاتی خپور کړي او زما قهر او غضب نور هم راوپاروي؟ هغوی ته وګوره چې څنګه په بې‌شرمۍ زما سپکاوی کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_017.mp3', NULL, 1761758917, 1761758917),
(42360, 'Ezekiel 8:18', 'Ezekiel', 8, 18, 'نو له دې امله به په هغوی باندې خپل غضب نازل کړم. زه به هغوی ته د مینې په سترګه ونه ګورم او په هغوی باندې به هېڅ رحم ونه کړم. هغوی به چیغې وهي او ماته به په ډېر لوړ اواز زارۍ کوي، خو زه به ورته غوږ ونه نیسم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel8_verse_018.mp3', NULL, 1761758917, 1761758917),
(42361, 'Jonah 2:1', 'Jonah', 2, 1, 'د ماهي د ګېډې څخه یونس خپل څښتن خدای ته دعا وکړه:', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_001.mp3', NULL, 1761758917, 1761758917),
(42362, 'Jonah 2:2', 'Jonah', 2, 2, 'په خپل تکلیف کې مې ای څښتنه تاته غږ وکړ او تا ځواب راکړ د مړو د نړۍ د ډېر ژور ځای څخه ما فریاد وکړ د مرستې په خاطر او تا واورېده', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_002.mp3', NULL, 1761758917, 1761758917),
(42363, 'Jonah 2:3', 'Jonah', 2, 3, 'تا زه ژورو اوبو ته ورګوزار کړم د بحیرې تل ته او سیلاب راګېر کړم او زما په سر تېرې شوې ستا زورورې څپې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_003.mp3', NULL, 1761758917, 1761758917),
(42364, 'Jonah 2:4', 'Jonah', 2, 4, 'نو ما وویل چې زه شړل شوی یمه ستا له نظره څخه خو بیا به هم زه سترګې واړوم ستا د سپېڅلي کور خواته', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_004.mp3', NULL, 1761758917, 1761758917),
(42365, 'Jonah 2:5', 'Jonah', 2, 5, 'اوبه راباندې راغلې او ساه اخیستی نه شم او شوې راچاپېرې له ما د بحیرې اوبه زما د سر څخه راتاو شول د بحیرې واښه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_005.mp3', NULL, 1761758917, 1761758917),
(42366, 'Jonah 2:6', 'Jonah', 2, 6, 'ورسېدم زه دغرونو بېخ ته لاندې ځمکې تل ترتله راګېر کړمه زه خو تا راووېستم ژوندی د مرګ له کندې څخه ای څښتنه زما خدایه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_006.mp3', NULL, 1761758917, 1761758917),
(42367, 'Jonah 2:7', 'Jonah', 2, 7, 'کله چې وتله زما ساه نو ته مې رایاد کړلې څښتنه او زما دعا ورسېدله تاته ستا سپېڅلي کور کې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_007.mp3', NULL, 1761758917, 1761758917),
(42368, 'Jonah 2:8', 'Jonah', 2, 8, 'چې بې‌ارزښته بتانو ته کړي عبادت څوک هغوی پریښی خپل امید دی د خدای د تلپاتې مینې', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_008.mp3', NULL, 1761758917, 1761758917),
(42369, 'Jonah 2:9', 'Jonah', 2, 9, 'خو د شکرګزارۍ په کولو سره زه به وړاندې کړمه تاته قرباني او ما چې منلی نذر، زه به یې ورکړمه راځي خلاصون د څښتن له خوا نه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_009.mp3', NULL, 1761758917, 1761758917),
(42370, 'Jonah 2:10', 'Jonah', 2, 10, 'بیا څښتن په ماهي باندې امر وکړ او ماهي یونس وچې ځمکې ته ورګوزار کړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/jonah2_verse_010.mp3', NULL, 1761758917, 1761758917),
(42371, 'Hosea 12:1', 'Hosea', 12, 1, 'څښتن وایي: «هغه کارونه چې د اسراییلو خلک یې د سهار نه تر ماښامه پورې کوي، هغه بې‌ګټې او خرابوونکي کارونه دي. په هغوی کې خیانت او ظلم زیاتې زیاتیږي. هغوی د آشوریانو سره تړونونه کوي او مصریانو ته د مرستې په خاطر د زیتون تېل ورکوي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_001.mp3', NULL, 1761758917, 1761758917),
(42372, 'Hosea 12:2', 'Hosea', 12, 2, 'څښتن د یهودا خلک ملامتوي او اسراییلو ته د هغه د خلکو د عملونو په سبب سزا ورکوي. د هغوی څخه به د خپلو کارونو بدل واخیستل شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_002.mp3', NULL, 1761758917, 1761758917),
(42373, 'Hosea 12:3', 'Hosea', 12, 3, 'د هغوی نیکه یعقوب د خپل غبرګوني ورور عیسو سره چې دواړه لا د مور په خېټه کې وو، جګړه وکړه. کله چې یعقوب لوی شو، هغه د خدای سره هم جنګ وکړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_003.mp3', NULL, 1761758917, 1761758917),
(42374, 'Hosea 12:4', 'Hosea', 12, 4, 'هغه د فرښتې سره غېږه ونیوله او په هغې باندې بریالی شو. هغه وژړل او د برکت دپاره یې سوال وکړ. په بیت‌ییل کې خدای زمونږ د نیکه یعقوب سره مخامخ شو او د هغه سره یې خبرې وکړې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_004.mp3', NULL, 1761758917, 1761758917),
(42375, 'Hosea 12:5', 'Hosea', 12, 5, 'څښتن هغه مطلق قادر خدای دی چې د هغه په نوم باندې عبادت کیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_005.mp3', NULL, 1761758917, 1761758917),
(42376, 'Hosea 12:6', 'Hosea', 12, 6, 'نو اوس ای د یعقوب اولادې، په خپل خدای باندې توکل کوئ او د هغه خواته راوګرځئ. وفادار او عادل اوسئ او په صبر سره خپل خدای ته انتظار کوئ چې هغه څه کوي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_006.mp3', NULL, 1761758917, 1761758917),
(42377, 'Hosea 12:7', 'Hosea', 12, 7, 'خو څښتن وایي: «د اسراییلو خلک هغه سوداګران دي چې د غلطو ترازوګانو څخه کار اخلي او دا خوښوي چې د خلکو سره ټګي وکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_007.mp3', NULL, 1761758917, 1761758917),
(42378, 'Hosea 12:8', 'Hosea', 12, 8, 'هغوی په غرور سره وایي: ‹مونږ شتمن یو او د ښه قسمت خاوندان یو. هېڅوک مونږ په دې نه شي ملامتولی چې مونږ په بې‌ایمانۍ سره دولتمن شوي یو.›', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_008.mp3', NULL, 1761758917, 1761758917),
(42379, 'Hosea 12:9', 'Hosea', 12, 9, 'خو زه ستاسو څښتن خدای یم چې تاسو یې د مصر نه راوویستلئ. زه به تاسو مجبور کړم چې یوځل بیا په خېمو کې واوسېږئ، لکه څنګه چې تاسو په دښته کې اوسېدلئ او ستاسو سره مې لیدنه وکړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_009.mp3', NULL, 1761758917, 1761758917),
(42380, 'Hosea 12:10', 'Hosea', 12, 10, 'ما د پیغمبرانو سره خبرې وکړې، دا زه وم چې هغوی ته مې ډېرې رویاګانې ورکړې او د پیغمبرانو په وسیله مې خپلو خلکو ته په مثالونو کې خبرداری ورکړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_010.mp3', NULL, 1761758917, 1761758917),
(42381, 'Hosea 12:11', 'Hosea', 12, 11, 'خو بیاهم هغوی د جلعاد په ښار کې د بتانو عبادت کوي او هرڅوک چې د هغوی عبادت کوي، هغه به تباه شي. د جلجال په ښار کې غویان قرباني کېدل، نو هلته چې کوم د قربانۍ ځایونه دي هغه به په پټیو کې د تیږو په ډېریو باندې بدل شي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_011.mp3', NULL, 1761758917, 1761758917),
(42382, 'Hosea 12:12', 'Hosea', 12, 12, 'زمونږ نیکه یعقوب سوریې ته وتښتېد. هلته د ښځې د پیدا کولو دپاره مجبور ؤ چې کار وکړي او پسونه وڅروي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_012.mp3', NULL, 1761758917, 1761758917),
(42383, 'Hosea 12:13', 'Hosea', 12, 13, 'څښتن یو پیغمبر ولېږه چې د اسراییلو خلک په مصر کې د غلامۍ نه خلاص کړي او په هغوی باندې پام وکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_013.mp3', NULL, 1761758917, 1761758917),
(42384, 'Hosea 12:14', 'Hosea', 12, 14, 'د اسراییلو خلکو څښتن ډېر سخت په قهر کړ. هغوی د خپلو جرمونو له امله د مرګ لایق دي. نو څښتن به هغوی ته د خپل سپکاوي په خاطر سزا ورکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/hosea12_verse_014.mp3', NULL, 1761758917, 1761758917),
(42385, 'Numbers 9:1', 'Numbers', 9, 1, 'د دوهم کال په لومړۍ میاشت وروسته له دې چې د اسراییلو قوم د مصر څخه راووت، څښتن د سینا په دښته کې د موسی سره خبرې وکړې. هغه وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_001.mp3', NULL, 1761758917, 1761758917),
(42386, 'Numbers 9:4', 'Numbers', 9, 4, 'نو موسی قوم ته وویل چې د فسحې اختر ولمانځي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_004.mp3', NULL, 1761758917, 1761758917),
(42387, 'Numbers 9:5', 'Numbers', 9, 5, 'او هغوی دا کار د اولې میاشتې د څوارلسمې ورځې په ماښام د سینا په دښته کې وکړ. قوم هرڅه هماغه شان وکړل لکه څنګه چې څښتن موسی ته حکم کړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_005.mp3', NULL, 1761758917, 1761758917),
(42388, 'Numbers 9:6', 'Numbers', 9, 6, 'خو ځینې خلک په مذهبي لحاظ ناپاک وو، ځکه چې د هغوی لاسونه په مړي باندې لګېدلي وو او هغوی ونه شو کولای چې په هغه ورځ د فسحې اختر ولمانځي. نو هغوی موسی او هارون ته ورغلل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_006.mp3', NULL, 1761758917, 1761758917),
(42389, 'Numbers 9:7', 'Numbers', 9, 7, 'او ویې ویل: «مونږ ناپاک یو، ځکه چې زمونږ لاسونه په مړي باندې لګېدلي دي، خو ولې نه شو کولای چې د فسحې اختر ولمانځو او د نورو اسراییلیانو سره په یو وخت څښتن ته نذرانې وړاندې کړو؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_007.mp3', NULL, 1761758917, 1761758917),
(42390, 'Numbers 9:8', 'Numbers', 9, 8, 'موسی په ځواب کې وویل: «صبر وکړئ چې زه په دې باندې ځان پوه کړم چې څښتن ستاسو په اړه څه حکم کوي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_008.mp3', NULL, 1761758917, 1761758917),
(42391, 'Numbers 9:9', 'Numbers', 9, 9, 'بیا څښتن موسی ته وویل چې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_009.mp3', NULL, 1761758917, 1761758917),
(42392, 'Numbers 9:10', 'Numbers', 9, 10, 'د اسراییلو خلکو ته ووایي: «که چېرې تاسو یا ستاسو د اولادې څخه څوک په مړي باندې په لګېدلو سره ناپاک شوی وي او یا په لېرې سفر کې وي، خو وغواړي چې د فسحې اختر ولمانځي،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_010.mp3', NULL, 1761758917, 1761758917),
(42393, 'Numbers 9:11', 'Numbers', 9, 11, 'نو هغه دې د دوهمې میاشتې د څوارلسمې ورځې په ماښام یعنې یوه میاشت وروسته ولمانځي. هغه دې د فسحې وری د فطیرې ډوډۍ او ترخو بوټو سره وخوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_011.mp3', NULL, 1761758917, 1761758917),
(42394, 'Numbers 9:12', 'Numbers', 9, 12, 'د هغه څخه دې هېڅ شی تر سهاره پورې نه پرېږدي او د حیوان هېڅ یو هډوکی دې نه ماتوي. کله چې هغه د فسحې اختر لمانځي، باید د دغو ټولو مقرراتو څخه پیروي وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_012.mp3', NULL, 1761758917, 1761758917),
(42395, 'Numbers 9:13', 'Numbers', 9, 13, 'خو که چېرې ستاسو څخه څوک په مذهبي لحاظ پاک وي او په سفر کې نه وي او د فسحې اختر نه لمانځي، هغه باید زما د قوم څخه وشړل شي. هغه ته به سزا ورکړل شي، ځکه چې ماته یې په ټاکلي وخت نذرانې نه دي وړاندې کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_013.mp3', NULL, 1761758917, 1761758917),
(42396, 'Numbers 9:14', 'Numbers', 9, 14, 'که چېرې هغه پردي خلک چې ستاسو په منځ کې اوسیږي وغواړي چې د فسحې اختر ولمانځي، باید د ټولو قوانینو او مقرراتو سره سم یې ولمانځي. همدا قانون په هرچا باندې که هغه اصلي اوسېدونکی وي یا پردي وي، عملي کیږي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_014.mp3', NULL, 1761758917, 1761758917),
(42397, 'Numbers 9:17', 'Numbers', 9, 17, 'هرکله چې به ورېځ د خېمې څخه پورته شوه، نو اسراییلیان به روان شول. کله به چې ورېځ راښکته شوه، هغوی به خېمې ودرولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_017.mp3', NULL, 1761758917, 1761758917),
(42398, 'Numbers 9:18', 'Numbers', 9, 18, 'قوم د څښتن په حکم حرکت کاوه او د هغه په حکم به یې خېمې ودرولې. تر هغه وخته پورې چې په خېمه باندې به ورېځ وه، هغوی به په هماغه کمپ کې پاتې کېدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_018.mp3', NULL, 1761758917, 1761758917),
(42399, 'Numbers 9:19', 'Numbers', 9, 19, 'کله چې به ورېځ په خېمې باندې تر ډېره وخته پورې پاتې کېدله، هغوی د څښتن اطاعت کاوه او کډه یې نه کوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_019.mp3', NULL, 1761758917, 1761758917),
(42400, 'Numbers 9:20', 'Numbers', 9, 20, 'کله کله به ورېځ په خېمې باندې یوازې د یو څو ورځو دپاره پاتې کېدله، په هر حال کې به هغوی د څښتن د حکم سره سم په کمپ کې پاتې کېدل یا به یې کډه کوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_020.mp3', NULL, 1761758917, 1761758917),
(42401, 'Numbers 9:21', 'Numbers', 9, 21, 'کله کله ورېځ یوازې د ماښام څخه تر سهاره پورې پاتې کېدله، څنګه به چې ورېځ پورته شوه، هغوی به کډه کوله. هرکله چې ورېځ پورته کېدله، هغوی کډه کوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_021.mp3', NULL, 1761758917, 1761758917),
(42402, 'Numbers 9:22', 'Numbers', 9, 22, 'که دا به دوه ورځې، یوه میاشت یا به ډېره موده وه، ترڅو چې په خېمې باندې به ورېځ وه هغوی کډه نه کوله. خو کله چې ورېځ پورته کېدله، هغوی به کډه کوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_022.mp3', NULL, 1761758917, 1761758917),
(42403, 'Numbers 9:23', 'Numbers', 9, 23, 'هغوی به د څښتن په حکم خېمې ودرولې او د هغه په حکم به یې حرکت کاوه. هغوی د څښتن د حکمونو څخه چې د موسی په وسیله یې کول، اطاعت کاوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/numbers9_verse_023.mp3', NULL, 1761758917, 1761758917),
(42404, 'Ezekiel 29:1', 'Ezekiel', 29, 1, 'زمونږ د جلاوطنۍ په لسم کال د لسمې میاشتې په دولسمه ورځ څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel29_verse_001.mp3', NULL, 1761758917, 1761758917),
(42405, 'Ezekiel 29:2', 'Ezekiel', 29, 2, '«ای فاني انسانه، د مصر پاچا فرعون ته مخ ورواړوه. د هغه او د مصر د ټولو خلکو په خلاف نبوت وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel29_verse_002.mp3', NULL, 1761758917, 1761758917),
(42406, 'Ezekiel 29:3', 'Ezekiel', 29, 3, 'هغه ته ووایه چې څښتن تعالی داسې وایي: ‹ای د مصر پاچا فرعونه، زه ستا په خلاف یم، ته داسې یوه لویه بلا یې چې په سیندونو کې پروت یې. ته وایې چې د نیل سیند زما دی او ما د خپل ځان دپاره جوړ کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel29_verse_003.mp3', NULL, 1761758917, 1761758917),
(42407, 'Ezekiel 29:4', 'Ezekiel', 29, 4, 'زه به ستا په ژامه کې چنګکونه واچوم او ستا د سیندونو ماهیان به تا پورې کلک ونښلوم. بیا به تا د هغو ماهیانو سره چې درپورې نښتي دي، ستا د سیندونو نه راوباسم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel29_verse_004.mp3', NULL, 1761758917, 1761758917),
(42408, 'Ezekiel 29:5', 'Ezekiel', 29, 5, 'زه به تا او هغه ټول ماهیان په دښته کې وغورځوم او هلته به یې پرېږدم. ستا مړی به په ځمکه باندې پروت وي او ښخ به نه شي. زه به هغه د حیواناتو او مرغانو د خوراک کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel29_verse_005.mp3', NULL, 1761758917, 1761758917),
(42409, 'Ezekiel 29:6', 'Ezekiel', 29, 6, 'بیا به د مصر ټول خلک پوه شي چې زه څښتن یم.› څښتن وایي: ‹اسراییلیانو په مصریانو باندې تکیه کوله چې ملاتړ به یې وکړي، خو تاسو د یوې کمزورې لوخې څخه جوړه شوې امسا په شان وئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel29_verse_006.mp3', NULL, 1761758917, 1761758917),
(42410, 'Ezekiel 29:7', 'Ezekiel', 29, 7, 'کله چې هغوی درباندې تکیه وکړه، نو ته ماته شوې، د هغوی اوږې دې سورۍ کړې او د هغوی ملاګانې دې ژوبل کړې.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel29_verse_007.mp3', NULL, 1761758917, 1761758917);